type Shape = Circle(Int) | Rect(Int, Int) | Dot
fn shape_area(s: Shape) -> Int = match s { Circle(r) => 3 * r * r, Rect(w, h) => w * h, Dot => 0 }
fn total_shape_area(xs: List[Shape]) -> Int = fold(xs, 0, fn(acc: Int, s: Shape) => acc + shape_area(s))
test total_shape_area_check = total_shape_area([Circle(2), Rect(3, 4)]) == 24

