type QueueLine = NoOne | Waiting(Int)
fn arrive(l: QueueLine) -> QueueLine = match l { NoOne => Waiting(1), Waiting(n) => Waiting(n + 1) }
fn leave(l: QueueLine) -> QueueLine = match l { NoOne => NoOne, Waiting(n) => if n <= 1 then NoOne else Waiting(n - 1) }
test line_arrive = arrive(arrive(NoOne)) == Waiting(2)
test line_leave = leave(Waiting(1)) == NoOne

type Tank = DryTank | Litres(Int)
