fn burn(t: Tank, n: Int) -> Tank = match t { DryTank => DryTank, Litres(k) => if k <= n then DryTank else Litres(k - n) }
test tank_burn = burn(Litres(10), 4) == Litres(6)
test tank_dry = burn(DryTank, 1) == DryTank

