type DoorMove = Knock | Push | Pull
fn door_step(d: Door, m: DoorMove) -> Door = match m { Knock => d, Push => OpenDoor, Pull => ShutDoor }
fn door_run(xs: List[DoorMove]) -> Door = fold(xs, ShutDoor, door_step)
test door_opened = door_run([Push, Knock]) == OpenDoor
test door_shut = door_run([Push, Pull]) == ShutDoor

type Counter2 = ZeroC | TallyC(Int)
type CounterOp = Add(Int) | Reset
fn counter_step(c: Counter2, op: CounterOp) -> Counter2 = match op { Add(n) => match c { ZeroC => TallyC(n), TallyC(k) => TallyC(k + n) }, Reset => ZeroC }
fn counter_run(ops: List[CounterOp]) -> Int = match fold(ops, ZeroC, counter_step) { ZeroC => 0, TallyC(n) => n }
test counter_run_sum = counter_run([Add(2), Add(3)]) == 5
test counter_run_reset = counter_run([Add(2), Reset, Add(1)]) == 1

type SwitchState = OffSwitch | OnSwitch
type FlipAct = FlipIt | ForceOff
fn flip_step(s: SwitchState, f: FlipAct) -> SwitchState = match f { FlipIt => match s { OffSwitch => OnSwitch, OnSwitch => OffSwitch }, ForceOff => OffSwitch }
fn flip_run(xs: List[FlipAct]) -> SwitchState = fold(xs, OffSwitch, flip_step)
test flip_three = flip_run([FlipIt, FlipIt, FlipIt]) == OnSwitch
test flip_force = flip_run([FlipIt, ForceOff]) == OffSwitch

type TrafficMode = Normal | Flashing | Shutdown
type TrafficEvent = StartNormal | StartFlash | StopAll
fn mode_step(m: TrafficMode, e: TrafficEvent) -> TrafficMode = match e { StartNormal => Normal, StartFlash => Flashing, StopAll => Shutdown }
fn mode_run(es: List[TrafficEvent]) -> TrafficMode = fold(es, Normal, mode_step)
test mode_last_wins = mode_run([StartFlash, StopAll]) == Shutdown
test mode_normal = mode_run([StartFlash, StartNormal]) == Normal

type StackState = EmptyStack | HasItems(Int)
type StackOp = Put | Take
fn stack_step(s: StackState, op: StackOp) -> StackState = match op { Put => match s { EmptyStack => HasItems(1), HasItems(n) => HasItems(n + 1) }, Take => match s { EmptyStack => EmptyStack, HasItems(n) => if n <= 1 then EmptyStack else HasItems(n - 1) } }
fn stack_run(ops: List[StackOp]) -> Int = match fold(ops, EmptyStack, stack_step) { EmptyStack => 0, HasItems(n) => n }
test stack_net = stack_run([Put, Put, Take]) == 1
test stack_floor = stack_run([Take, Take]) == 0

type Board = NilScore | Scored(Int)
type ScoreMove = Goal(Int) | Wipe
fn board_step(b: Board, m: ScoreMove) -> Board = match m { Goal(n) => match b { NilScore => Scored(n), Scored(k) => Scored(k + n) }, Wipe => NilScore }
fn board_total(ms: List[ScoreMove]) -> Int = match fold(ms, NilScore, board_step) { NilScore => 0, Scored(n) => n }
test board_goals = board_total([Goal(2), Goal(3)]) == 5
test board_wiped = board_total([Goal(2), Wipe, Goal(1)]) == 1

type EngineState = OffEngine | IdleEngine | RevEngine(Int)
type EngineOp = Ignite | Rev(Int) | Kill
fn engine_step(e: EngineState, op: EngineOp) -> EngineState = match op { Ignite => match e { OffEngine => IdleEngine, _ => e }, Rev(n) => match e { OffEngine => OffEngine, IdleEngine => RevEngine(n), RevEngine(k) => RevEngine(k + n) }, Kill => OffEngine }
fn engine_run(ops: List[EngineOp]) -> Int = match fold(ops, OffEngine, engine_step) { RevEngine(n) => n, _ => 0 }
test engine_revs = engine_run([Ignite, Rev(2), Rev(3)]) == 5
test engine_killed = engine_run([Ignite, Rev(4), Kill]) == 0

type Pen = Capped | Nib
type PenAct = Uncap | Write | Recap
fn pen_step(p: Pen, a: PenAct) -> Pen = match a { Uncap => Nib, Write => p, Recap => Capped }
fn pen_run(xs: List[PenAct]) -> Pen = fold(xs, Capped, pen_step)
test pen_recapped = pen_run([Uncap, Write, Recap]) == Capped
test pen_nib = pen_run([Uncap]) == Nib

type Turnstile = LockedGate | OpenGate
fn enter(t: Turnstile) -> Result[Turnstile, Str] = match t { LockedGate => Err("locked"), OpenGate => Ok(LockedGate) }
test enter_locked = match enter(LockedGate) { Ok(_) => false, Err(m) => m == "locked" }
test enter_open = match enter(OpenGate) { Ok(t) => t == LockedGate, Err(_) => false }

type Lift = LiftIdle | LiftMoving(Int)
fn halt_lift(l: Lift) -> Result[Lift, Str] = match l { LiftIdle => Err("not moving"), LiftMoving(_) => Ok(LiftIdle) }
test halt_idle = match halt_lift(LiftIdle) { Ok(_) => false, Err(s) => s == "not moving" }
test halt_moving = match halt_lift(LiftMoving(2)) { Ok(s) => s == LiftIdle, Err(_) => false }

type Account = ClosedAccount | OpenAccount(Int)
fn withdraw(a: Account, n: Int) -> Result[Account, Str] = match a { ClosedAccount => Err("closed"), OpenAccount(b) => if b < n then Err("insufficient") else Ok(OpenAccount(b - n)) }
test withdraw_ok = match withdraw(OpenAccount(50), 20) { Ok(OpenAccount(b)) => b == 30, _ => false }
test withdraw_short = match withdraw(OpenAccount(5), 20) { Err(s) => s == "insufficient", _ => false }

type Vault = SealedVault | Unsealed
fn unlock(v: Vault) -> Option[Vault] = match v { SealedVault => Some(Unsealed), Unsealed => None }
test unlock_once = match unlock(SealedVault) { Some(s) => s == Unsealed, None => false }
test unlock_twice = match unlock(Unsealed) { Some(_) => false, None => true }

type JobState = WaitingJob | RunningJob | FinishedJob
fn begin_job(j: JobState) -> Result[JobState, Str] = match j { WaitingJob => Ok(RunningJob), RunningJob => Err("already running"), FinishedJob => Err("finished") }
test job_waiting = match begin_job(WaitingJob) { Ok(s) => s == RunningJob, Err(_) => false }
test job_running = match begin_job(RunningJob) { Err(m) => m == "already running", _ => false }

type TrafficLight = StopLight | CautionLight | GoLight
fn parse_light(s: Str) -> Option[TrafficLight] = if s == "stop" then Some(StopLight) else if s == "caution" then Some(CautionLight) else if s == "go" then Some(GoLight) else None
test parse_go = match parse_light("go") { Some(l) => l == GoLight, None => false }
test parse_halt = match parse_light("halt") { Some(_) => false, None => true }

type Payment = Unpaid | Authorized(Int) | Captured(Int) | Declined
fn capture(p: Payment) -> Result[Payment, Str] = match p { Unpaid => Err("not authorized"), Authorized(n) => Ok(Captured(n)), Captured(_) => Err("already captured"), Declined => Err("declined") }
test capture_auth = match capture(Authorized(7)) { Ok(Captured(n)) => n == 7, _ => false }
test capture_unpaid = match capture(Unpaid) { Err(s) => s == "not authorized", _ => false }

type Checkout = Shopping | InCart(Int) | Purchased
fn add_item(c: Checkout, n: Int) -> Result[Checkout, Str] = match c { Purchased => Err("already paid"), Shopping => Ok(InCart(n)), InCart(k) => Ok(InCart(k + n)) }
test add_first = match add_item(Shopping, 2) { Ok(s) => s == InCart(2), _ => false }
test add_paid = match add_item(Purchased, 1) { Err(m) => m == "already paid", _ => false }

type SleepState = Dormant | Awake
fn wake(s: SleepState) -> Result[SleepState, Str] = match s { Dormant => Ok(Awake), Awake => Err("already awake") }
test wake_once = match wake(Dormant) { Ok(Awake) => true, _ => false }
test wake_twice = match wake(Awake) { Err(_) => true, _ => false }

type Session = Anonymous | LoggedIn(Str)
fn login(s: Session, name: Str) -> Result[Session, Str] = match s { Anonymous => if name == "" then Err("empty name") else Ok(LoggedIn(name)), LoggedIn(_) => Err("already logged in") }
test login_ok = match login(Anonymous, "ada") { Ok(LoggedIn(n)) => n == "ada", _ => false }
test login_empty = match login(Anonymous, "") { Err(m) => m == "empty name", _ => false }

type Ticket = Fresh | Used | ExpiredTicket
fn scan(t: Ticket) -> Result[Ticket, Str] = match t { Fresh => Ok(Used), Used => Err("used ticket"), ExpiredTicket => Err("expired ticket") }
test scan_fresh = match scan(Fresh) { Ok(Used) => true, _ => false }
test scan_used = match scan(Used) { Err(m) => m == "used ticket", _ => false }

type JobPhase = PendingPhase | ActivePhase | CompletedPhase
fn activate(p: JobPhase) -> Option[JobPhase] = match p { PendingPhase => Some(ActivePhase), ActivePhase => None, CompletedPhase => None }
test activate_pending = match activate(PendingPhase) { Some(ActivePhase) => true, _ => false }
test activate_done = match activate(CompletedPhase) { Some(_) => false, None => true }

type Color = RedColor | GreenColor | BlueColor
fn color_code(c: Color) -> Int = match c { RedColor => 0, GreenColor => 1, BlueColor => 2 }
fn color_name(c: Color) -> Str = match c { RedColor => "red", GreenColor => "green", BlueColor => "blue" }
test color_code_green = color_code(GreenColor) == 1
test color_name_blue = color_name(BlueColor) == "blue"

type Priority = LowP | NormalP | HighP
fn priority_rank(p: Priority) -> Int = match p { LowP => 0, NormalP => 5, HighP => 9 }
fn top(xs: List[Priority]) -> Priority = fold(xs, LowP, fn(a, b) => if priority_rank(a) >= priority_rank(b) then a else b)
test top_high = top([LowP, HighP, NormalP]) == HighP
test top_single = top([NormalP]) == NormalP

type Direction = NorthD | SouthD | EastD | WestD
fn turn_right(d: Direction) -> Direction = match d { NorthD => EastD, EastD => SouthD, SouthD => WestD, WestD => NorthD }
fn turn_left(d: Direction) -> Direction = match d { NorthD => WestD, WestD => SouthD, SouthD => EastD, EastD => NorthD }
test right_four = turn_right(turn_right(turn_right(turn_right(NorthD)))) == NorthD
test left_north = turn_left(NorthD) == WestD

type Axis = Horizontal | Vertical
fn flip_axis(a: Axis) -> Axis = match a { Horizontal => Vertical, Vertical => Horizontal }
fn axis_name(a: Axis) -> Str = match a { Horizontal => "h", Vertical => "v" }
test flip_axis_name = axis_name(flip_axis(Horizontal)) == "v"
test axis_double = flip_axis(flip_axis(Vertical)) == Vertical

type Units = Metric | Imperial
fn unit_label(u: Units) -> Str = match u { Metric => "cm", Imperial => "in" }
fn to_metric(n: Int, u: Units) -> Int = match u { Metric => n, Imperial => n * 2 }
test imperial_double = to_metric(3, Imperial) == 6
test metric_label = unit_label(Metric) == "cm"

type Suit = Hearts | Spades | Clubs | Diamonds
fn suit_symbol(s: Suit) -> Str = match s { Hearts => "H", Spades => "S", Clubs => "C", Diamonds => "D" }
fn red_suit(s: Suit) -> Bool = match s { Hearts => true, Diamonds => true, _ => false }
test hearts_red = red_suit(Hearts)
test spades_black = !red_suit(Spades)
test club_symbol = suit_symbol(Clubs) == "C"

type Rank = Rookie | Veteran | Elite
fn promote(r: Rank) -> Rank = match r { Rookie => Veteran, Veteran => Elite, Elite => Elite }
fn power(r: Rank) -> Int = match r { Rookie => 1, Veteran => 2, Elite => 3 }
test promote_power = power(promote(Rookie)) == 2
test elite_stays = promote(Elite) == Elite

type Weather = Sunny | Cloudy | Stormy
fn umbrella(w: Weather) -> Bool = match w { Sunny => false, Cloudy => false, Stormy => true }
fn weather_score(w: Weather) -> Int = match w { Sunny => 3, Cloudy => 2, Stormy => 0 }
test storm_umbrella = umbrella(Stormy)
test sunny_score = weather_score(Sunny) == 3

type DoorState = DoorClosed | DoorOpen
type RoomState = EmptyRoom | Occupied(DoorState)
fn enter_room(r: RoomState) -> RoomState = match r { EmptyRoom => Occupied(DoorOpen), Occupied(d) => Occupied(d) }
fn close_door(r: RoomState) -> RoomState = match r { EmptyRoom => EmptyRoom, Occupied(_) => Occupied(DoorClosed) }
test enter_opens = enter_room(EmptyRoom) == Occupied(DoorOpen)
test close_after = close_door(enter_room(EmptyRoom)) == Occupied(DoorClosed)

type ValveState = ValveShut | ValveOpen
type PumpState = PumpOff | PumpOn(ValveState)
fn start_pump(p: PumpState) -> PumpState = match p { PumpOff => PumpOn(ValveShut), PumpOn(v) => PumpOn(v) }
fn open_valve(p: PumpState) -> PumpState = match p { PumpOff => PumpOff, PumpOn(_) => PumpOn(ValveOpen) }
test pump_starts = start_pump(PumpOff) == PumpOn(ValveShut)
test pump_valve = open_valve(start_pump(PumpOff)) == PumpOn(ValveOpen)

type Power = PowerOff | PowerOn
type Device = DeviceDown | DeviceUp(Power)
fn plug(d: Device) -> Device = match d { DeviceDown => DeviceUp(PowerOn), DeviceUp(p) => DeviceUp(p) }
fn unplug(d: Device) -> Device = match d { DeviceDown => DeviceDown, DeviceUp(_) => DeviceDown }
test plug_then_unplug = unplug(plug(DeviceDown)) == DeviceDown
test plug_up = plug(DeviceDown) == DeviceUp(PowerOn)

type Mode = CoolMode | HeatMode | OffMode
type Thermostat = ThermoIdle | ThermoActive(Mode)
fn select_mode(t: Thermostat, m: Mode) -> Thermostat = match t { ThermoIdle => ThermoIdle, ThermoActive(_) => ThermoActive(m) }
fn activate_t(t: Thermostat) -> Thermostat = match t { ThermoIdle => ThermoActive(CoolMode), ThermoActive(m) => ThermoActive(m) }
test select_heat = select_mode(activate_t(ThermoIdle), HeatMode) == ThermoActive(HeatMode)
test select_idle = select_mode(ThermoIdle, HeatMode) == ThermoIdle

type DoorL = LockState | UnlockState
type Safe = SafeShut | SafeOpen(DoorL)
fn arm(s: Safe) -> Safe = match s { SafeShut => SafeShut, SafeOpen(_) => SafeShut }
fn disarm(s: Safe) -> Safe = match s { SafeShut => SafeOpen(LockState), SafeOpen(_) => SafeOpen(UnlockState) }
test disarm_arm = arm(disarm(SafeShut)) == SafeShut
test disarm_open = disarm(SafeShut) == SafeOpen(LockState)

type Bulb = BulbOff | BulbOn
type Fixture = FixtureIdle | FixtureLit(Bulb)
fn switch_on(f: Fixture) -> Fixture = match f { FixtureIdle => FixtureLit(BulbOn), FixtureLit(_) => FixtureLit(BulbOn) }
fn switch_off(f: Fixture) -> Fixture = match f { FixtureIdle => FixtureIdle, FixtureLit(_) => FixtureLit(BulbOff) }
test fixture_on = switch_on(FixtureIdle) == FixtureLit(BulbOn)
test fixture_off = switch_off(switch_on(FixtureIdle)) == FixtureLit(BulbOff)

type State = SIdle | SReady | SDone
fn is_done(s: State) -> Bool = match s { SDone => true, _ => false }
fn count_done(xs: List[State]) -> Int = fold(xs, 0, fn(n, s) => if is_done(s) then n + 1 else n)
test count_done_two = count_done([SIdle, SDone, SDone]) == 2
test count_done_none = count_done([SIdle, SReady]) == 0

type Tone = Quiet | Loud
fn loudness(t: Tone) -> Int = match t { Quiet => 0, Loud => 1 }
fn total_loud(xs: List[Tone]) -> Int = fold(xs, 0, fn(n, t) => n + loudness(t))
test total_mixed = total_loud([Quiet, Loud, Loud]) == 2
test total_quiet = total_loud([Quiet]) == 0

type Cell = DeadCell | AliveCell
fn toggle_cell(c: Cell) -> Cell = match c { DeadCell => AliveCell, AliveCell => DeadCell }
fn step_row(xs: List[Cell]) -> List[Cell] = map(xs, toggle_cell)
test step_row_first = get(step_row([DeadCell, AliveCell]), 0) == Some(AliveCell)
test step_row_len = len(step_row([DeadCell])) == 1

type Medal = Bronze | Silver | Gold
fn medal_points(m: Medal) -> Int = match m { Bronze => 1, Silver => 2, Gold => 3 }
fn best(xs: List[Medal]) -> Medal = fold(xs, Bronze, fn(a, b) => if medal_points(a) >= medal_points(b) then a else b)
test best_gold = best([Bronze, Gold, Silver]) == Gold
test best_single = best([Silver]) == Silver

type Bit = ZeroBit | OneBit
fn bit_value(b: Bit) -> Int = match b { ZeroBit => 0, OneBit => 1 }
fn bits_value(xs: List[Bit]) -> Int = fold(xs, 0, fn(acc, b) => acc * 2 + bit_value(b))
test bits_101 = bits_value([OneBit, ZeroBit, OneBit]) == 5
test bits_11 = bits_value([OneBit, OneBit]) == 3

type Answer = Yes | No | Maybe
fn confident(a: Answer) -> Bool = match a { Yes => true, No => true, Maybe => false }
fn count_confident(xs: List[Answer]) -> Int = fold(xs, 0, fn(n, a) => if confident(a) then n + 1 else n)
test confident_two = count_confident([Yes, Maybe, No]) == 2
test confident_none = count_confident([Maybe]) == 0

type TickState = Tick | Tock
fn toggle_tick(t: TickState) -> TickState = match t { Tick => Tock, Tock => Tick }
fn alternate(t: TickState, n: Int) -> TickState = if n <= 0 then t else alternate(toggle_tick(t), n - 1)
test alternate_even = alternate(Tick, 4) == Tick
test alternate_odd = alternate(Tick, 3) == Tock

type Step = StepA | StepB | StepC
fn advance_step(s: Step) -> Step = match s { StepA => StepB, StepB => StepC, StepC => StepA }
fn advance_n(s: Step, n: Int) -> Step = if n <= 0 then s else advance_n(advance_step(s), n - 1)
test advance_three = advance_n(StepA, 3) == StepA
test advance_four = advance_n(StepA, 4) == StepB

type Signal = GreenSig | YellowSig | RedSig
fn next_signal(s: Signal) -> Signal = match s { GreenSig => YellowSig, YellowSig => RedSig, RedSig => GreenSig }
fn cycles(s: Signal, n: Int) -> Signal = if n <= 0 then s else cycles(next_signal(s), n - 1)
test cycles_six = cycles(GreenSig, 6) == GreenSig
test cycles_one = cycles(GreenSig, 1) == YellowSig

type Flip = OffFlip | OnFlip
fn toggle_f(f: Flip) -> Flip = match f { OffFlip => OnFlip, OnFlip => OffFlip }
fn toggle_n(f: Flip, n: Int) -> Flip = if n <= 0 then f else toggle_n(toggle_f(f), n - 1)
test toggle_even = toggle_n(OffFlip, 10) == OffFlip
test toggle_odd = toggle_n(OffFlip, 7) == OnFlip

type Level = LevelOne | LevelTwo | LevelThree | LevelFour
fn climb(l: Level) -> Level = match l { LevelOne => LevelTwo, LevelTwo => LevelThree, LevelThree => LevelFour, LevelFour => LevelFour }
fn climb_n(l: Level, n: Int) -> Level = if n <= 0 then l else climb_n(climb(l), n - 1)
test climb_top = climb_n(LevelOne, 5) == LevelFour
test climb_one = climb_n(LevelOne, 1) == LevelTwo

type Phase = AllRed | NorthSouth | EastWest
fn phase_next(p: Phase) -> Phase = match p { AllRed => NorthSouth, NorthSouth => EastWest, EastWest => AllRed }
fn phase_after(p: Phase, n: Int) -> Phase = if n <= 0 then p else phase_after(phase_next(p), n - 1)
test phase_three = phase_after(AllRed, 3) == AllRed
test phase_two = phase_after(AllRed, 2) == EastWest

type Coin = Heads | Tails
fn flip_coin(c: Coin) -> Coin = match c { Heads => Tails, Tails => Heads }
fn flips(c: Coin, n: Int) -> Coin = if n <= 0 then c else flips(flip_coin(c), n - 1)
test flips_even = flips(Heads, 8) == Heads
test flips_odd = flips(Heads, 9) == Tails

type Gear = FirstGear | SecondGear | ThirdGear
fn shift_up(g: Gear) -> Gear = match g { FirstGear => SecondGear, SecondGear => ThirdGear, ThirdGear => ThirdGear }
fn shift_down(g: Gear) -> Gear = match g { FirstGear => FirstGear, SecondGear => FirstGear, ThirdGear => SecondGear }
fn drive_up(g: Gear, n: Int) -> Gear = if n <= 0 then g else drive_up(shift_up(g), n - 1)
test ups = drive_up(FirstGear, 3) == ThirdGear
test down = shift_down(ThirdGear) == SecondGear

type Point = { x: Int, y: Int }
type Move = Step(Point) | Stay
fn move(p: Point, m: Move) -> Point = match m { Step(d) => Point { x: p.x + d.x, y: p.y + d.y }, Stay => p }
test moved = move(Point { x: 1, y: 2 }, Step(Point { x: 3, y: 4 })) == Point { x: 4, y: 6 }
test stayed = move(Point { x: 1, y: 2 }, Stay) == Point { x: 1, y: 2 }

type Vec = { dx: Int, dy: Int }
type Dir = LeftTurn | RightTurn
fn turn(v: Vec, d: Dir) -> Vec = match d { LeftTurn => Vec { dx: 0 - v.dy, dy: v.dx }, RightTurn => Vec { dx: v.dy, dy: 0 - v.dx } }
test left_turn = turn(Vec { dx: 1, dy: 0 }, LeftTurn) == Vec { dx: 0, dy: 1 }
test right_turn = turn(Vec { dx: 0, dy: 1 }, RightTurn) == Vec { dx: 1, dy: 0 }

type Cell = { row: Int, col: Int }
type Visitor = AtCell(Cell) | Nowhere
fn cell_id(v: Visitor) -> Int = match v { AtCell(c) => c.row * 10 + c.col, Nowhere => 0 - 1 }
test cell_id_ok = cell_id(AtCell(Cell { row: 3, col: 4 })) == 34
test nowhere_id = cell_id(Nowhere) == 0 - 1

type Grade = { score: Int }
type Verdict = Distinction | Merit | PassGrade | FailGrade
fn verdict_of(g: Grade) -> Verdict = match g.score { s if s >= 85 => Distinction, s if s >= 70 => Merit, s if s >= 50 => PassGrade, _ => FailGrade }
test distinction = verdict_of(Grade { score: 90 }) == Distinction
test fail_grade = verdict_of(Grade { score: 10 }) == FailGrade

type Zodiac = Aries | Taurus | Gemini
fn parse_zodiac(s: Str) -> Option[Zodiac] = match s { "aries" => Some(Aries), "taurus" => Some(Taurus), "gemini" => Some(Gemini), _ => None }
