test parse_leo = match parse_zodiac("leo") { Some(_) => false, None => true }

type Op = Plus | Minus
fn apply_op(o: Op, a: Int, b: Int) -> Int = match o { Plus => a + b, Minus => a - b }
fn parse_op(s: Str) -> Option[Op] = if s == "+" then Some(Plus) else if s == "-" then Some(Minus) else None
