test parse_minus = match parse_op("-") { Some(o) => apply_op(o, 7, 3) == 4, None => false }

type Command = Go | Halt | Wait
fn parse_command(word: Str) -> Option[Command] = match word { "go" => Some(Go), "halt" => Some(Halt), "wait" => Some(Wait), _ => None }
fn run_command(word: Str) -> Int = match parse_command(word) { Some(Go) => 1, Some(Halt) => 0, Some(Wait) => 2, None => 0 - 1 }
test run_go = run_command("go") == 1
test run_unknown = run_command("fly") == 0 - 1

type Sound = Beep | Buzz | Silent
fn from_char(c: Str) -> Option[Sound] = match c { "b" => Some(Beep), "z" => Some(Buzz), "." => Some(Silent), _ => None }
test beep_char = match from_char("b") { Some(s) => s == Beep, None => false }
test bad_char = match from_char("x") { Some(_) => false, None => true }

type Level = Debug | Info | Warn | Severe
fn rank(l: Level) -> Int = match l { Debug => 0, Info => 1, Warn => 2, Severe => 3 }
fn at_least(l: Level, min: Level) -> Bool = rank(l) >= rank(min)
