test debug_not_warn = !at_least(Debug, Warn)

type Relay = RelayA | RelayB
type Output = OutputHigh | OutputLow
fn relay_out(r: Relay) -> Output = match r { RelayA => OutputHigh, RelayB => OutputLow }
fn invert(o: Output) -> Output = match o { OutputHigh => OutputLow, OutputLow => OutputHigh }
