test relay_b = relay_out(RelayB) == OutputLow

type Washer = WasherOff | Washing | Rinsing | Spinning | WasherDone
fn start_wash(w: Washer) -> Washer = match w { WasherOff => Washing, _ => w }
fn advance_wash(w: Washer) -> Washer = match w { Washing => Rinsing, Rinsing => Spinning, Spinning => WasherDone, _ => w }
fn is_finished(w: Washer) -> Bool = match w { WasherDone => true, _ => false }
