test wash_idle = !is_finished(WasherOff)

type Coffee = CoffeeIdle | Grinding | Brewing | CoffeeReady
fn button(c: Coffee) -> Coffee = match c { CoffeeIdle => Grinding, _ => c }
fn finish_grind(c: Coffee) -> Coffee = match c { Grinding => Brewing, _ => c }
fn finish_brew(c: Coffee) -> Coffee = match c { Brewing => CoffeeReady, _ => c }
test coffee_ready = finish_brew(finish_grind(button(CoffeeIdle))) == CoffeeReady
test coffee_done = button(CoffeeReady) == CoffeeReady

type Atm = AtmIdle | CardInserted | PinEntered | Dispensing | AtmDone
fn insert_card(a: Atm) -> Atm = match a { AtmIdle => CardInserted, _ => a }
