fn restOf(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn insertOne(x: Int, ys: List[Int]) -> List[Int] =
  if len(ys) == 0 then [x]
  else if x <= list_at(ys, 0) then [x] ++ ys
  else [list_at(ys, 0)] ++ insertOne(x, restOf(ys))

fn sortUp(xs: List[Int]) -> List[Int] =
  if len(xs) == 0 then []
  else insertOne(list_at(xs, 0), sortUp(restOf(xs)))

test sort_one = sortUp([3, 1, 2]) == [1, 2, 3]
test more_three = sortUp([9, 8, 7, 6]) == [6, 7, 8, 9]

fn dropHead(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn placeIn(x: Int, ys: List[Int]) -> List[Int] =
  if len(ys) == 0 then [x]
  else if x <= list_at(ys, 0) then [x] ++ ys
  else [list_at(ys, 0)] ++ placeIn(x, dropHead(ys))

fn orderInts(xs: List[Int]) -> List[Int] =
  if len(xs) == 0 then []
  else placeIn(list_at(xs, 0), orderInts(dropHead(xs)))

test sort_two = orderInts([5, 2, 9, 1]) == [1, 2, 5, 9]
test more_four = orderInts([2]) == [2]

fn tailOf(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn siftInto(x: Int, ys: List[Int]) -> List[Int] =
  if len(ys) == 0 then [x]
  else if x <= list_at(ys, 0) then [x] ++ ys
  else [list_at(ys, 0)] ++ siftInto(x, tailOf(ys))

fn isort(xs: List[Int]) -> List[Int] =
  if len(xs) == 0 then []
  else siftInto(list_at(xs, 0), isort(tailOf(xs)))

test sort_three = isort([4, 4, 1]) == [1, 4, 4]
test more_five = isort([2, 2, 2]) == [2, 2, 2]

fn behind(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn slotIn(x: Int, ys: List[Int]) -> List[Int] =
  if len(ys) == 0 then [x]
  else if x <= list_at(ys, 0) then [x] ++ ys
  else [list_at(ys, 0)] ++ slotIn(x, behind(ys))

fn sortAsc(xs: List[Int]) -> List[Int] =
  if len(xs) == 0 then []
  else slotIn(list_at(xs, 0), sortAsc(behind(xs)))

test sort_four = sortAsc([7, 0, 3, 8, 2]) == [0, 2, 3, 7, 8]
