fn takeSome(xs: List[Int], n: Int) -> List[Int] =
  if n <= 0 then []
  else if len(xs) == 0 then []
  else [list_at(xs, 0)] ++ takeSome(dropFirst(xs), n - 1)

fn skipN(xs: List[Int], n: Int) -> List[Int] =
  if n <= 0 then xs
  else if len(xs) == 0 then []
  else skipN(dropFirst(xs), n - 1)

fn mergeRuns(a: List[Int], b: List[Int]) -> List[Int] =
  if len(a) == 0 then b
  else if len(b) == 0 then a
  else if list_at(a, 0) <= list_at(b, 0) then [list_at(a, 0)] ++ mergeRuns(dropFirst(a), b)
  else [list_at(b, 0)] ++ mergeRuns(a, dropFirst(b))

fn rankUp(xs: List[Int]) -> List[Int] =
  if len(xs) <= 1 then xs
  else let m = len(xs) / 2 in mergeRuns(rankUp(takeSome(xs, m)), rankUp(skipN(xs, m)))

