  else if len(b) == 0 then a
  else if list_at(a, 0) <= list_at(b, 0) then [list_at(a, 0)] ++ mergeTwo(afterHead(a), b)
  else [list_at(b, 0)] ++ mergeTwo(a, afterHead(b))

