type Split = { lower: List[Int], upper: List[Int] }

fn dropFirst(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn divideAt(xs: List[Int], p: Int) -> Split =
  let start = Split { lower: [], upper: [] } in
  fold(xs, start, fn(acc: Split, x: Int) =>
    if x < p then Split { lower: push(acc.lower, x), upper: acc.upper }
    else Split { lower: acc.lower, upper: push(acc.upper, x) })

fn arrange(xs: List[Int]) -> List[Int] =
  if len(xs) <= 1 then xs
  else let p = list_at(xs, 0) in
       let rest = dropFirst(xs) in
       let parts = divideAt(rest, p) in
       arrange(parts.lower) ++ [p] ++ arrange(parts.upper)

