fn mergeSorted(a: List[Int], b: List[Int]) -> List[Int] =
  if len(a) == 0 then b
  else if len(b) == 0 then a
  else if list_at(a, 0) <= list_at(b, 0) then [list_at(a, 0)] ++ mergeSorted(withoutHead(a), b)
  else [list_at(b, 0)] ++ mergeSorted(a, withoutHead(b))

