  if len(a) == 0 then b
  else if len(b) == 0 then a
  else if list_at(a, 0) <= list_at(b, 0) then [list_at(a, 0)] ++ blendSorted(dropFirst(a), b)
  else [list_at(b, 0)] ++ blendSorted(a, dropFirst(b))

