fn combineTwo(a: List[Int], b: List[Int]) -> List[Int] =
  if len(a) == 0 then b
  else if len(b) == 0 then a
  else if list_at(a, 0) <= list_at(b, 0) then [list_at(a, 0)] ++ combineTwo(afterHead(a), b)
  else [list_at(b, 0)] ++ combineTwo(a, afterHead(b))

test first_check = combineTwo([2, 2], [2, 2]) == [2, 2, 2, 2]
test also_six = combineTwo([7], [8]) == [7, 8]

fn restOf(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn mergeSorted(a: List[Int], b: List[Int]) -> List[Int] =
  if len(a) == 0 then b
  else if len(b) == 0 then a
  else if list_at(a, 0) <= list_at(b, 0) then [list_at(a, 0)] ++ mergeSorted(restOf(a), b)
  else [list_at(b, 0)] ++ mergeSorted(a, restOf(b))

test second_check = mergeSorted([1, 4], []) == [1, 4]
test also_seven = mergeSorted([1, 3, 5], [2, 4]) == [1, 2, 3, 4, 5]

fn dropHead(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn blendSorted(a: List[Int], b: List[Int]) -> List[Int] =
  if len(a) == 0 then b
  else if len(b) == 0 then a
  else if list_at(a, 0) <= list_at(b, 0) then [list_at(a, 0)] ++ blendSorted(dropHead(a), b)
  else [list_at(b, 0)] ++ blendSorted(a, dropHead(b))

test third_check = blendSorted([-3, 0], [-1, 2]) == [-3, -1, 0, 2]
test also_eight = blendSorted([], [1, 2]) == [1, 2]

fn tailOf(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn combineTwo(a: List[Int], b: List[Int]) -> List[Int] =
  if len(a) == 0 then b
  else if len(b) == 0 then a
  else if list_at(a, 0) <= list_at(b, 0) then [list_at(a, 0)] ++ combineTwo(tailOf(a), b)
  else [list_at(b, 0)] ++ combineTwo(a, tailOf(b))

test fourth_check = combineTwo([7], [8]) == [7, 8]
test also_one = combineTwo([2, 2], [2, 2]) == [2, 2, 2, 2]

fn vowels(s: Str) -> Int =
  fold(chars(s), 0, fn(n, c) => if contains("aeiou", to_lower(c)) then n + 1 else n)

test vowels_lower = vowels("programming") == 3

fn count_vowel(s: Str) -> Int = walk(s, 0)

fn walk(s: Str, i: Int) -> Int =
  if i >= len(s) then 0
  else if contains("AEIOUaeiou", slice(s, i, i + 1)) then 1 + walk(s, i + 1)
  else walk(s, i + 1)

test count_vowel_mixed = count_vowel("Queue") == 4

fn consonants(s: Str) -> Int =
  fold(chars(s), 0, fn(n, c) =>
    if contains("aeiou", to_lower(c)) then n
    else if contains("abcdefghijklmnopqrstuvwxyz", to_lower(c)) then n + 1
    else n)

test consonants_word = consonants("strength") == 7

fn digits_in(s: Str) -> Int =
  fold(chars(s), 0, fn(n, c) => if contains("0123456789", c) then n + 1 else n)

test digits_in_ok = digits_in("a1b22c333") == 6

fn count_digit(s: Str) -> Int = scan(s, 0)

fn scan(s: Str, i: Int) -> Int =
  if i >= len(s) then 0
  else if contains("0123456789", slice(s, i, i + 1)) then 1 + scan(s, i + 1)
  else scan(s, i + 1)

test count_digit_simple = count_digit("12ab34") == 4

fn upper_count(s: Str) -> Int =
  fold(chars(s), 0, fn(k, c) => if c == to_upper(c) && c != to_lower(c) then k + 1 else k)

test upper_count_ok = upper_count("QalLang") == 2

fn lower_count(s: Str) -> Int =
  fold(chars(s), 0, fn(k, c) => if c != to_upper(c) && c == to_lower(c) then k + 1 else k)

test lower_count_ok = lower_count("QalLang") == 5

fn space_count(s: Str) -> Int =
  fold(chars(s), 0, fn(k, c) => if c == " " then k + 1 else k)

test space_count_ok = space_count("a b  c") == 3

fn letter_count(s: Str) -> Int =
  fold(chars(s), 0, fn(k, c) => if to_lower(c) != to_upper(c) then k + 1 else k)

test letter_count_ok = letter_count("a1 B2!") == 2

fn punctuation_count(s: Str) -> Int =
  fold(chars(s), 0, fn(k, c) => if contains(",.;:!?", c) then k + 1 else k)

test punct_ok = punctuation_count("Hi, there!") == 2

fn count_char(s: Str, i: Int, t: Str) -> Int =
  if i >= len(s) then 0
  else if slice(s, i, i + 1) == t then 1 + count_char(s, i + 1, t)
  else count_char(s, i + 1, t)

test count_a = count_char("banana", 0, "a") == 3

fn sentence_count(s: Str) -> Int =
  len(filter(split(s, "."), fn(p) => trim(p) != ""))

test sentence_count_ok = sentence_count("One. Two. Three.") == 3

fn distinct_letters(s: Str) -> List[Str] = map_keys(chars_map(s))

fn chars_map(s: Str) -> Map[Str, Int] =
  let start: Map[Str, Int] = map_new() in
  fold(chars(s), start, fn(m, c) => map_put(m, c, 1))

test distinct_letters_ok = len(distinct_letters("hello")) == 4

fn word_lengths(s: Str) -> List[Int] =
  map(split(s, " "), fn(w) => len(w))

test word_lengths_ok = word_lengths("ab cde fghi") == [2, 3, 4]

fn total_chars(words: List[Str]) -> Int =
  fold(words, 0, fn(n, w) => n + len(w))

test total_chars_ok = total_chars(split("aa bb ccc", " ")) == 7

fn mirror(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) => c ++ out)

test mirror_ok = mirror("abc") == "cba"

fn reversed(s: Str) -> Str = from_chars(reverse(chars(s)))

fn from_chars(xs: List[Str]) -> Str =
  fold(xs, "", fn(out, c) => out ++ c)

test reversed_ok = reversed("qal") == "laq"

fn capital(s: Str) -> Str =
  if len(s) == 0 then s
  else to_upper(slice(s, 0, 1)) ++ slice(s, 1, len(s))

test capital_ok = capital("qal") == "Qal"

fn titleize(s: Str) -> Str =
  join(map(split(s, " "), fn(w) => capital(w)), " ")

fn capital(w: Str) -> Str =
  if w == "" then w else to_upper(slice(w, 0, 1)) ++ to_lower(slice(w, 1, len(w)))

test titleize_ok = titleize("hello wide world") == "Hello Wide World"

fn toggle(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) =>
    if c == to_upper(c) && c != to_lower(c) then out ++ to_lower(c) else out ++ to_upper(c))

test toggle_ok = toggle("Qal") == "qAL"

fn alternating(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) =>
    if len(out) % 2 == 0 then out ++ to_upper(c) else out ++ to_lower(c))

test alternating_ok = alternating("abcd") == "AbCd"

fn squeeze_spaces(s: Str) -> Str = squeeze(s, 0, false)

fn squeeze(s: Str, i: Int, prev_space: Bool) -> Str =
  if i >= len(s) then ""
  else if slice(s, i, i + 1) == " " then squeeze_space(s, i, prev_space)
  else slice(s, i, i + 1) ++ squeeze(s, i + 1, false)

fn squeeze_space(s: Str, i: Int, prev_space: Bool) -> Str =
  if prev_space then squeeze(s, i + 1, true)
  else " " ++ squeeze(s, i + 1, true)

test squeeze_ok = squeeze_spaces("a   b  c") == "a b c"

fn no_spaces(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) => if c == " " then out else out ++ c)

test no_spaces_ok = no_spaces("a b c") == "abc"

fn drop_front(s: Str, ch: Str) -> Str =
  if len(s) == 0 then s
  else if slice(s, 0, 1) == ch then drop_front(slice(s, 1, len(s)), ch)
  else s

fn drop_back(s: Str, ch: Str) -> Str =
  if len(s) == 0 then s
  else if slice(s, len(s) - 1, len(s)) == ch then drop_back(slice(s, 0, len(s) - 1), ch)
  else s

fn drop_edges(s: Str, ch: Str) -> Str = drop_front(drop_back(s, ch), ch)

test drop_edges_ok = drop_edges("***hi***", "*") == "hi"

fn replace_vowels(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) => if contains("aeiou", c) then out ++ "*" else out ++ c)

test replace_vowels_ok = replace_vowels("qal language") == "q*l l*ng**g*"

fn mask_digits(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) => if contains("0123456789", c) then out ++ "#" else out ++ c)

test mask_digits_ok = mask_digits("PIN 4821") == "PIN ####"

fn slug(s: Str) -> Str =
  fold(chars(to_lower(trim(s))), "", fn(out, c) =>
    if c == " " then out ++ "-" else out ++ c)

test slug_ok = slug("Hello QAL World") == "hello-qal-world"

fn repeat(s: Str, n: Int) -> Str =
  if n <= 0 then "" else s ++ repeat(s, n - 1)

test repeat_ok = repeat("ab", 3) == "ababab"

fn pad_left(s: Str, width: Int, fill: Str) -> Str =
  if len(s) >= width then s else pad_left(fill ++ s, width, fill)

test pad_left_ok = pad_left("7", 3, "0") == "007"

fn pad_right(s: Str, width: Int, fill: Str) -> Str =
  if len(s) >= width then s else pad_right(s ++ fill, width, fill)

test pad_right_ok = pad_right("ab", 5, ".") == "ab..."

fn clip(s: Str, n: Int) -> Str =
  if len(s) <= n then s else slice(s, 0, n) ++ "..."

test clip_ok = clip("truncate me", 4) == "trun..."

fn unquote(s: Str) -> Str =
  if len(s) < 2 then s
  else if slice(s, 0, 1) != "\"" then s
  else if slice(s, len(s) - 1, len(s)) != "\"" then s
  else slice(s, 1, len(s) - 1)

test unquote_ok = unquote("\"hi\"") == "hi"

fn caesar_shift(c: Str, k: Int) -> Str =
  let n = char_code(c) in
  let kk = ((k % 26) + 26) % 26 in
  if n >= 97 && n <= 122 then from_char_code(97 + (n - 97 + kk) % 26)
  else if n >= 65 && n <= 90 then from_char_code(65 + (n - 65 + kk) % 26)
  else c

fn caesar(s: Str, k: Int) -> Str =
  fold(chars(s), "", fn(out, c) => out ++ caesar_shift(c, k))

test caesar_ok = caesar("Attack at dawn", 3) == "Dwwdfn dw gdzq"

fn rot13(s: Str) -> Str = encode(s, 13)

fn encode(s: Str, k: Int) -> Str =
  fold(chars(s), "", fn(out, c) =>
    let n = char_code(c) in
    if n >= 97 && n <= 122 then out ++ from_char_code(97 + (n - 97 + k) % 26)
    else if n >= 65 && n <= 90 then out ++ from_char_code(65 + (n - 65 + k) % 26)
    else out ++ c)

test rot13_ok = rot13("Hello") == "Uryyb"

fn initials(s: Str) -> Str =
  fold(split(s, " "), "", fn(out, w) => out ++ to_upper(slice(w, 0, 1)))

test initials_ok = initials("ada lovelace") == "AL"

fn first_word(s: Str) -> Str =
  match get(split(trim(s), " "), 0) { Some(w) => w, None => "" }

test first_word_ok = first_word("alpha beta") == "alpha"

fn last_word(s: Str) -> Str =
  let ws = split(trim(s), " ") in
  match get(ws, len(ws) - 1) { Some(w) => w, None => "" }

test last_word_ok = last_word("alpha beta") == "beta"

fn drop_prefix(s: Str, p: Str) -> Str =
  if starts_with(s, p) then slice(s, len(p), len(s)) else s

test drop_prefix_ok = drop_prefix("unhappy", "un") == "happy"

fn swap_case(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) =>
    if to_lower(c) == c then out ++ to_upper(c) else out ++ to_lower(c))

test swap_case_ok = swap_case("aB1") == "Ab1"

fn chars_at_even(s: Str) -> Str =
  fold(range(0, len(s)), "", fn(out, i) =>
    if i % 2 == 0 then out ++ slice(s, i, i + 1) else out)

test chars_at_even_ok = chars_at_even("abcdef") == "ace"

fn every_other(s: Str) -> Str =
  fold(range(0, len(s)), "", fn(out, i) =>
    if i % 2 == 1 then out ++ slice(s, i, i + 1) else out)

test every_other_ok = every_other("abcdef") == "bdf"

fn take(s: Str, n: Int) -> Str =
  if n <= 0 then "" else if n >= len(s) then s else slice(s, 0, n)

test take_ok = take("abcdef", 3) == "abc"

fn drop_first(s: Str, n: Int) -> Str =
  if n <= 0 then s else if n >= len(s) then "" else slice(s, n, len(s))

test drop_first_ok = drop_first("abcdef", 2) == "cdef"

fn middle(s: Str) -> Str =
  if len(s) <= 2 then "" else slice(s, 1, len(s) - 1)

test middle_ok = middle("[abc]") == "abc"

fn swap_ends(s: Str) -> Str =
  if len(s) < 2 then s
  else slice(s, len(s) - 1, len(s)) ++ slice(s, 1, len(s) - 1) ++ slice(s, 0, 1)

test swap_ends_ok = swap_ends("qal") == "laq"

fn wrap(s: Str, n: Int) -> Str =
  if n <= 0 then s
  else fold(range(0, len(s)), "", fn(out, i) =>
    if i > 0 && i % n == 0 then out ++ "\n" ++ slice(s, i, i + 1)
    else out ++ slice(s, i, i + 1))

test wrap_ok = wrap("abcdef", 3) == "abc\ndef"

fn parse_int(s: Str) -> Int =
  match to_int(trim(s)) { Some(n) => n, None => 0 }

test parse_int_ok = parse_int(" 42 ") == 42

fn parse_or(s: Str, d: Int) -> Int =
  match to_int(s) { Some(n) => n, None => d }

test parse_or_bad = parse_or("nope", -1) == -1
test parse_or_good = parse_or("-7", 0) == -7

fn looks_numeric(s: Str) -> Bool =
  match to_int(trim(s)) { Some(_) => true, None => false }

test looks_numeric_ok = looks_numeric("123") && !looks_numeric("12a")

fn max_csv(line: Str) -> Option[Int] =
  let start: Option[Int] = None in
  fold(split(line, ","), start, fn(best, part) =>
    match to_int(trim(part)) {
      None => best,
      Some(n) => match best { None => Some(n), Some(m) => if n > m then Some(n) else Some(m) }
    })

test max_csv_ok = max_csv("4, 9, 2") == Some(9)

fn parse_ints(s: Str) -> Option[List[Int]] =
  let start: Option[List[Int]] = Some([]) in
  fold(split(s, ","), start, fn(acc, part) =>
    match acc {
      None => None,
      Some(xs) => match to_int(trim(part)) {
        Some(n) => Some(push(xs, n)),
        None => None
      }
    })

test parse_ints_ok = parse_ints("1,2,3") == Some([1, 2, 3])
test parse_ints_bad = parse_ints("1,x") == None

fn parse_bool(s: Str) -> Option[Bool] =
  let t = to_lower(trim(s)) in
  if t == "true" then Some(true)
  else if t == "false" then Some(false)
  else None

test parse_bool_ok = parse_bool(" TRUE ") == Some(true)

fn pct(s: Str) -> Option[Int] =
  let n = len(s) in
  if n < 2 then None
  else if slice(s, n - 1, n) != "%" then None
  else to_int(trim(slice(s, 0, n - 1)))

test pct_ok = pct("50%") == Some(50)

fn parse_duration(s: Str) -> Option[Int] =
  let n = len(s) in
  if n < 2 then None
  else if slice(s, n - 1, n) != "s" then None
  else to_int(trim(slice(s, 0, n - 1)))

test parse_duration_ok = parse_duration("90s") == Some(90)

type Span = { start: Int, end: Int }

fn parse_span(s: Str) -> Option[Span] =
  match index_of(s, "-") {
    None => None,
    Some(i) => match to_int(slice(s, 0, i)) {
      None => None,
      Some(a) => match to_int(slice(s, i + 1, len(s))) {
        None => None,
        Some(b) => Some(Span { start: a, end: b })
      }
    }
  }

test parse_span_ok = parse_span("3-7") == Some(Span { start: 3, end: 7 })

type Entry = { key: Str, value: Str }

fn parse_entry(s: Str) -> Option[Entry] =
  match index_of(s, "=") {
    None => None,
    Some(i) => Some(Entry { key: trim(slice(s, 0, i)), value: trim(slice(s, i + 1, len(s))) })
  }

test parse_entry_ok = parse_entry(" name = ada ") == Some(Entry { key: "name", value: "ada" })

fn param_count(query: Str) -> Int =
  len(filter(split(query, "&"), fn(p) => contains(p, "=")))

test param_count_ok = param_count("a=1&b=2&bad") == 2

type Entry = { key: Str, value: Str }

fn parse_entry(s: Str) -> Option[Entry] =
  match index_of(s, "=") {
    None => None,
    Some(i) => Some(Entry { key: trim(slice(s, 0, i)), value: trim(slice(s, i + 1, len(s))) })
  }

fn query_map(query: Str) -> Map[Str, Str] =
  let start: Map[Str, Str] = map_new() in
  fold(split(query, "&"), start, fn(m, part) =>
    match parse_entry(part) {
      None => m,
      Some(e) => map_put(m, e.key, e.value)
    })

test query_map_ok = map_get(query_map("a=1&b=2"), "b") == Some("2")

fn header_value(raw: Str, name: Str) -> Option[Str] =
  let start: Map[Str, Str] = map_new() in
  let m = fold(split(raw, ";"), start, fn(acc, part) =>
    match index_of(part, ":") {
      None => acc,
      Some(i) => map_put(acc, trim(slice(part, 0, i)), trim(slice(part, i + 1, len(part))))
    }) in
  map_get(m, name)

test header_value_ok = header_value("Host: qal.dev; Port: 80", "Port") == Some("80")

fn hex_value(c: Str) -> Option[Int] =
  if contains("0123456789", c) then Some(char_code(c) - 48)
  else if contains("abcdef", to_lower(c)) then Some(char_code(to_lower(c)) - 87)
  else None

fn parse_hex(s: Str) -> Option[Int] =
  let start: Option[Int] = Some(0) in
  fold(chars(s), start, fn(acc, c) =>
    match acc {
      None => None,
      Some(n) => match hex_value(c) { None => None, Some(d) => Some(n * 16 + d) }
    })

test parse_hex_ok = parse_hex("ff") == Some(255)

fn from_hex(s: Str) -> Option[Int] = hex_rec(s, 0, 0)

fn hex_rec(s: Str, i: Int, acc: Int) -> Option[Int] =
  if i >= len(s) then Some(acc)
  else match hex_digit(slice(s, i, i + 1)) {
    None => None,
    Some(d) => hex_rec(s, i + 1, acc * 16 + d)
  }

fn hex_digit(c: Str) -> Option[Int] =
  match index_of("0123456789abcdef", to_lower(c)) {
    Some(i) => Some(i),
    None => None
  }

test from_hex_ok = from_hex("1A") == Some(26)

fn to_binary(n: Int) -> Str =
  if n <= 0 then "0" else binary_rec(n, "")

fn binary_rec(n: Int, acc: Str) -> Str =
  if n == 0 then acc else binary_rec(n / 2, from_int(n % 2) ++ acc)

test to_binary_ok = to_binary(13) == "1101"

fn parse_binary(s: Str) -> Option[Int] = bin_rec(s, 0, 0)

fn bin_rec(s: Str, i: Int, acc: Int) -> Option[Int] =
  if i >= len(s) then Some(acc)
  else if slice(s, i, i + 1) == "0" then bin_rec(s, i + 1, acc * 2)
  else if slice(s, i, i + 1) == "1" then bin_rec(s, i + 1, acc * 2 + 1)
  else None

test parse_binary_ok = parse_binary("1101") == Some(13)

fn digit_sum(s: Str) -> Int =
  fold(chars(s), 0, fn(total, c) =>
    if contains("0123456789", c) then total + (char_code(c) - 48) else total)

test digit_sum_ok = digit_sum("a1b2c3") == 6

fn top_word(s: Str) -> Str =
  let m = bag(split(s, " ")) in
  fold(map_keys(m), "", fn(best, w) => better(m, best, w))

fn better(m: Map[Str, Int], best: Str, w: Str) -> Str =
  if best == "" then w
  else if count_of(m, w) > count_of(m, best) then w
  else best

fn count_of(m: Map[Str, Int], w: Str) -> Int =
  match map_get(m, w) { Some(n) => n, None => 0 }

fn bag(words: List[Str]) -> Map[Str, Int] =
  let start: Map[Str, Int] = map_new() in
  fold(words, start, fn(m, w) => bump(m, w))

fn bump(m: Map[Str, Int], w: Str) -> Map[Str, Int] =
  let seen = match map_get(m, w) { Some(n) => n, None => 0 } in
  map_put(m, w, seen + 1)

test top_word_ok = top_word("b a b c b") == "b"

fn longest_word(s: Str) -> Str =
  fold(split(s, " "), "", fn(best, w) => if len(w) > len(best) then w else best)

test longest_word_ok = longest_word("go little elephant") == "elephant"

fn avg_len(s: Str) -> Int =
  let ws = split(s, " ") in
  if len(ws) == 0 then 0 else total_len(ws) / len(ws)

fn total_len(ws: List[Str]) -> Int = fold(ws, 0, fn(n, w) => n + len(w))

test avg_len_ok = avg_len("abcd ef") == 3

fn lengths(s: Str) -> List[Int] =
  map(split(s, " "), fn(w) => len(w))

test lengths_ok = lengths("a bb ccc") == [1, 2, 3]

fn filter_by_len(s: Str, k: Int) -> List[Str] =
  filter(split(s, " "), fn(w) => len(w) == k)

test filter_by_len_ok = filter_by_len("a bb cc ddd", 2) == ["bb", "cc"]

fn words_with(s: Str, ch: Str) -> List[Str] =
  filter(split(s, " "), fn(w) => contains(w, ch))

test words_with_ok = words_with("apple pear plum", "l") == ["apple", "plum"]

fn shared_start(a: Str, b: Str) -> Str = walk(a, b, 0)

fn walk(a: Str, b: Str, i: Int) -> Str =
  if i >= len(a) || i >= len(b) then slice(a, 0, i)
  else if slice(a, i, i + 1) == slice(b, i, i + 1) then walk(a, b, i + 1)
  else slice(a, 0, i)

test shared_start_ok = shared_start("prefix", "prelude") == "pre"

fn common_end(a: Str, b: Str) -> Str =
  let n = if len(a) < len(b) then len(a) else len(b) in
  let k = end_walk(a, b, 0, n) in
  slice(a, len(a) - k, len(a))

fn end_walk(a: Str, b: Str, k: Int, n: Int) -> Int =
  if k >= n then k
  else if slice(a, len(a) - 1 - k, len(a) - k) == slice(b, len(b) - 1 - k, len(b) - k) then end_walk(a, b, k + 1, n)
  else k

