fn hamming(a: Str, b: Str) -> Option[Int] =
  if len(a) != len(b) then None
  else Some(fold(range(0, len(a)), 0, fn(n, i) =>
    if slice(a, i, i + 1) == slice(b, i, i + 1) then n else n + 1))

