fn is_palindrome(s: Str) -> Bool =
  let t = to_lower(s) in
  t == reverse_str(t)

fn reverse_str(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) => c ++ out)

test is_palindrome_ok = is_palindrome("Level")

fn is_palindrome_phrase(s: Str) -> Bool =
  let t = letters_only(to_lower(s)) in
  t == reverse_str(t)

fn letters_only(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) =>
    if contains("abcdefghijklmnopqrstuvwxyz", c) then out ++ c else out)

fn reverse_str(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) => c ++ out)

test phrase_ok = is_palindrome_phrase("A man, a plan, a canal: Panama")

fn anagrams(a: Str, b: Str) -> Bool =
