type Token = Word(Str) | Number(Int) | Marker

fn token_of(part: Str) -> Token =
  match to_int(part) {
    Some(n) => Number(n),
    None => if part == "#" then Marker else Word(part)
  }

fn render(t: Token) -> Str =
  match t { Word(w) => w, Number(n) => from_int(n), Marker => "#" }

test token_ok = render(token_of("42")) == "42" && render(token_of("#")) == "#"

type Token = Word(Str) | Number(Int)

fn tokens_of(s: Str) -> List[Token] = map(split(s, " "), fn(p) => token_of(p))

fn token_of(p: Str) -> Token =
  match to_int(p) { Some(n) => Number(n), None => Word(p) }

fn token_text(t: Token) -> Str = match t { Word(w) => w, Number(n) => from_int(n) }

fn render(s: Str) -> Str = join(map(tokens_of(s), fn(t) => token_text(t)), " ")

test tokens_ok = render("a 1 b") == "a 1 b"

type State = InWord | InSpace

fn count_words(s: Str) -> Int = walk(s, 0, InSpace)

fn walk(s: Str, i: Int, st: State) -> Int =
  if i >= len(s) then tail_count(st)
  else if slice(s, i, i + 1) == " " then on_space(s, i, st)
  else walk(s, i + 1, InWord)

fn on_space(s: Str, i: Int, st: State) -> Int =
  if st == InWord then 1 + walk(s, i + 1, InSpace) else walk(s, i + 1, InSpace)

fn tail_count(st: State) -> Int = if st == InWord then 1 else 0

test count_words_ok = count_words("a  bb c") == 3

fn split_all(s: Str, seps: List[Str]) -> List[Str] =
  fold(seps, [s], fn(parts, sep) => flat(map(parts, fn(p) => split(p, sep))))

fn flat(xss: List[List[Str]]) -> List[Str] =
  let start: List[Str] = [] in
  fold(xss, start, fn(acc, xs) => concat(acc, xs))

test split_all_ok = split_all("a,b;c", [",", ";"]) == ["a", "b", "c"]

