type HeadTail = { head: Str, tail: Str }

fn pairs_to_map(xs: List[HeadTail]) -> Map[Str, Str] =
  let start: Map[Str, Str] = map_new() in
  fold(xs, start, fn(m, p) => map_put(m, p.head, p.tail))

