fn is_date(s: Str) -> Bool =
  if len(s) != 10 then false
  else if slice(s, 4, 5) != "-" then false
  else if slice(s, 7, 8) != "-" then false
  else is_digits(slice(s, 0, 4)) && is_digits(slice(s, 5, 7)) && is_digits(slice(s, 8, 10))

fn is_digits(t: Str) -> Bool =
  len(t) > 0 && fold(chars(t), true, fn(ok, c) => ok && contains("0123456789", c))

