fn is_time(s: Str) -> Bool =
  if len(s) != 5 then false
  else if slice(s, 2, 3) != ":" then false
  else match to_int(slice(s, 0, 2)) {
    None => false,
    Some(h) => match to_int(slice(s, 3, 5)) {
      None => false,
      Some(m) => h >= 0 && h <= 23 && m >= 0 && m <= 59
    }
  }

