fn sum_digits_rec(s: Str) -> Int = digit_walk(s, 0, 0)

fn digit_walk(s: Str, i: Int, acc: Int) -> Int =
  if i >= len(s) then acc
  else if contains("0123456789", slice(s, i, i + 1)) then digit_walk(s, i + 1, acc + (char_code(slice(s, i, i + 1)) - 48))
  else digit_walk(s, i + 1, acc)

test sum_digits_rec_ok = sum_digits_rec("x9y9") == 18

fn rle(s: Str) -> Str = rle_walk(chars(s), 0, "")

fn rle_walk(cs: List[Str], i: Int, out: Str) -> Str =
  if i >= len(cs) then out else rle_go(cs, i, out)

fn rle_go(cs: List[Str], i: Int, out: Str) -> Str =
  let run = run_len(cs, i, list_at(cs, i)) in
  rle_walk(cs, i + run, out ++ list_at(cs, i) ++ from_int(run))

fn run_len(cs: List[Str], i: Int, c: Str) -> Int =
  if i >= len(cs) then 0
  else if list_at(cs, i) == c then 1 + run_len(cs, i + 1, c)
  else 0

test rle_ok = rle("aabccc") == "a2b1c3"

fn count_runs(s: Str) -> Int =
  if len(s) == 0 then 0
  else 1 + fold(range(1, len(s)), 0, fn(n, i) =>
    if slice(s, i, i + 1) != slice(s, i - 1, i) then n + 1 else n)

test count_runs_ok = count_runs("aabccc") == 3

fn squeeze_dup(s: Str) -> Str = dup_walk(s, 0, "")

fn dup_walk(s: Str, i: Int, out: Str) -> Str =
  if i >= len(s) then out
  else if i > 0 then dup_step(s, i, out)
  else dup_walk(s, i + 1, out ++ slice(s, 0, 1))

fn dup_step(s: Str, i: Int, out: Str) -> Str =
  if slice(s, i, i + 1) == slice(s, i - 1, i) then dup_walk(s, i + 1, out)
  else dup_walk(s, i + 1, out ++ slice(s, i, i + 1))

test squeeze_dup_ok = squeeze_dup("aabbccd") == "abcd"

fn sorted_chars(s: Str) -> Str =
