fn swap_ends(s: Str) -> Str =
  let ws = split(s, " ") in
  let n = len(ws) in
  if n < 2 then s else join(reorder(ws, n), " ")

fn reorder(ws: List[Str], n: Int) -> List[Str] =
  concat([list_at(ws, n - 1)], concat(map(range(1, n - 1), fn(i) => list_at(ws, i)), [list_at(ws, 0)]))

