type Entry = { key: Str, value: Str }

fn entry_of(p: Str) -> Entry =
  match index_of(p, "=") {
    None => Entry { key: p, value: "" },
    Some(i) => Entry { key: trim(slice(p, 0, i)), value: trim(slice(p, i + 1, len(p))) }
  }

fn entries(line: Str) -> List[Entry] = map(split(line, ","), fn(p) => entry_of(p))

fn entry_value(p: Str) -> Str =
  let e = entry_of(p) in
  e.value

