fn top(s: Str) -> Str =
  let ws = split(s, " ") in
  fold(ws, "", fn(best, w) => pick(ws, best, w))

fn pick(ws: List[Str], best: Str, w: Str) -> Str =
  if best == "" then w
  else if count_in(ws, w) > count_in(ws, best) then w
  else best

fn count_in(ws: List[Str], w: Str) -> Int = len(filter(ws, fn(x) => x == w))

test top_ok = top("b a b c b") == "b"

fn digit_groups(s: Str) -> List[Str] =
  filter(split(s, " "), fn(p) => fold(chars(p), true, fn(ok, c) => ok && contains("0123456789", c)))

