# Withdrawals never push stock below zero.
fn stock(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn take(m: Map[Str, Int], k: Str, qty: Int) -> Map[Str, Int] =
  if stock(m, k) >= qty then map_put(m, k, stock(m, k) - qty) else m

fn shelf() -> Map[Str, Int] =
  let a: Map[Str, Int] = map_new() in
  let b = map_put(a, "pen", 5) in
  map_put(b, "ink", 2)

test take_ok = stock(take(shelf(), "pen", 2), "pen") == 3
test take_deny = take(shelf(), "ink", 2 + 1) == shelf()
test take_unknown = take(shelf(), "zzz", 1) == shelf()

# Withdrawals never push stock below zero.
fn quantity(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn consume(m: Map[Str, Int], k: Str, qty: Int) -> Map[Str, Int] =
  if quantity(m, k) >= qty then map_put(m, k, quantity(m, k) - qty) else m

fn store() -> Map[Str, Int] =
  let a: Map[Str, Int] = map_new() in
  let b = map_put(a, "bolt", 7) in
  map_put(b, "nut", 4)

