  match map_get(m, k) { Some(n) => n, None => 0 }

fn withdraw(m: Map[Str, Int], k: Str, qty: Int) -> Map[Str, Int] =
  if on_hand(m, k) >= qty then map_put(m, k, on_hand(m, k) - qty) else m

