  Counter { label: c.label, value: c.value + 1 }

fn reset(c: Counter) -> Counter =
  Counter { label: c.label, value: 0 }

fn sum(cs: List[Counter]) -> Int =
  fold(cs, 0, fn(a, c) => a + c.value)

