    Some(t) => map_put(m, k, Tally { hits: t.hits + 1, misses: t.misses }),
    None => map_put(m, k, Tally { hits: 1, misses: 0 }),
  }

fn miss(m: Map[Str, Tally], k: Str) -> Map[Str, Tally] =
  match map_get(m, k) {
    Some(t) => map_put(m, k, Tally { hits: t.hits, misses: t.misses + 1 }),
    None => map_put(m, k, Tally { hits: 0, misses: 1 }),
  }

fn hits(m: Map[Str, Tally], k: Str) -> Int =
  match map_get(m, k) { Some(t) => t.hits, None => 0 }

