# The mode of an integer list through a histogram.
fn at(m: Map[Int, Int], k: Int) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn histogram(nums: List[Int]) -> Map[Int, Int] =
  fold(nums, map_new(), fn(acc, n) => map_put(acc, n, at(acc, n) + 1))

fn mode(nums: List[Int]) -> Option[Int] =
  let h = histogram(nums) in
  let start: Option[Int] = None in
  fold(map_keys(h), start, fn(best, k) =>
    match best {
      None => Some(k),
      Some(b) => if at(h, k) > at(h, b) then Some(k) else best,
    })

