fn restock(m: Map[Str, Int], k: Str, qty: Int) -> Map[Str, Int] =
  map_put(m, k, stock(m, k) + qty)

fn low(m: Map[Str, Int], k: Str, minimum: Int) -> Bool =
  stock(m, k) < minimum

