# A stats record that keeps counts and the longest word.
type Stats = { counts: Map[Str, Int], longest: Str }

fn lookup(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn longer(a: Str, b: Str) -> Str = if len(a) >= len(b) then a else b

fn fresh() -> Stats = Stats { counts: map_new(), longest: "" }

fn absorb(s: Stats, w: Str) -> Stats =
  Stats { counts: map_put(s.counts, w, lookup(s.counts, w) + 1), longest: longer(s.longest, w) }

fn scan(words: List[Str]) -> Stats =
  fold(words, fresh(), fn(acc, w) => absorb(acc, w))

test scan_longest = let s = scan(["red", "blue", "red", "green", "red"]) in s.longest == "green"
test scan_count = let s = scan(["red", "blue", "red", "green", "red"]) in lookup(s.counts, "red") == 3
test scan_empty = let s = scan([]) in s.longest == "" && map_size(s.counts) == 0

# A stats record that keeps counts and the longest word.
type Digest = { bag: Map[Str, Int], longest: Str }

fn count_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn bigger_word(a: Str, b: Str) -> Str = if len(a) >= len(b) then a else b

fn blank_stats() -> Digest = Digest { bag: map_new(), longest: "" }

fn add_word(s: Digest, w: Str) -> Digest =
  Digest { bag: map_put(s.bag, w, count_of(s.bag, w) + 1), longest: bigger_word(s.longest, w) }

fn digest_words(words: List[Str]) -> Digest =
  fold(words, blank_stats(), fn(acc, w) => add_word(acc, w))

test digest_words_longest = let s = digest_words(["cat", "dog", "cat", "bird"]) in s.longest == "bird"
test digest_words_count = let s = digest_words(["cat", "dog", "cat", "bird"]) in count_of(s.bag, "cat") == 2
test digest_words_empty = let s = digest_words([]) in s.longest == "" && map_size(s.bag) == 0

# A stats record that keeps counts and the longest word.
type Summary = { tally: Map[Str, Int], best: Str }

fn value_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn pick_long(a: Str, b: Str) -> Str = if len(a) >= len(b) then a else b

fn start() -> Summary = Summary { tally: map_new(), best: "" }

fn take_in(s: Summary, w: Str) -> Summary =
  Summary { tally: map_put(s.tally, w, value_of(s.tally, w) + 1), best: pick_long(s.best, w) }

fn collect(words: List[Str]) -> Summary =
  fold(words, start(), fn(acc, w) => take_in(acc, w))

test collect_longest = let s = collect(["sun", "rain", "sun", "snow", "rain", "sun"]) in s.best == "rain"
test collect_count = let s = collect(["sun", "rain", "sun", "snow", "rain", "sun"]) in value_of(s.tally, "sun") == 3
test collect_empty = let s = collect([]) in s.best == "" && map_size(s.tally) == 0

# A stats record that keeps counts and the longest word.
type Profile = { store: Map[Str, Int], longest: Str }

fn read_at(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn max_str(a: Str, b: Str) -> Str = if len(a) >= len(b) then a else b

fn empty_stats() -> Profile = Profile { store: map_new(), longest: "" }

fn note_word(s: Profile, w: Str) -> Profile =
  Profile { store: map_put(s.store, w, read_at(s.store, w) + 1), longest: max_str(s.longest, w) }

fn survey(words: List[Str]) -> Profile =
  fold(words, empty_stats(), fn(acc, w) => note_word(acc, w))

