# A stats record that keeps counts and the longest word.
type Brief = { ledger: Map[Str, Int], biggest: Str }

fn tally_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn wider(a: Str, b: Str) -> Str = if len(a) >= len(b) then a else b

