# Two aggregations over the same rows: sums and headcounts.
type Row = { dept: Str, pay: Int }

fn lookup(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn add(m: Map[Str, Int], k: Str, v: Int) -> Map[Str, Int] =
  map_put(m, k, lookup(m, k) + v)

fn pay_by(xs: List[Row]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, r) => add(acc, r.dept, r.pay))

fn head_by(xs: List[Row]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, r) => map_put(acc, r.dept, lookup(acc, r.dept) + 1))

fn sample() -> List[Row] = [Row { dept: "eng", pay: 100 }, Row { dept: "ops", pay: 50 }, Row { dept: "eng", pay: 20 }]

