# Two aggregations over the same rows: sums and headcounts.
type Line = { team: Str, score: Int }

fn value_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn accrue(m: Map[Str, Int], k: Str, v: Int) -> Map[Str, Int] =
  map_put(m, k, value_of(m, k) + v)

fn sum_by(xs: List[Line]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, r) => accrue(acc, r.team, r.score))

fn count_by(xs: List[Line]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, r) => map_put(acc, r.team, value_of(acc, r.team) + 1))

fn rows() -> List[Line] = [Line { team: "a", score: 5 }, Line { team: "b", score: 7 }, Line { team: "a", score: 1 }]

test sum_by_value = value_of(sum_by(rows()), "a") == 6
test count_by_value = value_of(count_by(rows()), "b") == 1
test sum_by_size = map_size(sum_by(rows())) == 2

# Two aggregations over the same rows: sums and headcounts.
type Cell = { zone: Str, total: Int }

fn score_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn credit(m: Map[Str, Int], k: Str, v: Int) -> Map[Str, Int] =
  map_put(m, k, score_of(m, k) + v)

fn total_by(xs: List[Cell]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, r) => credit(acc, r.zone, r.total))

fn tally_by(xs: List[Cell]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, r) => map_put(acc, r.zone, score_of(acc, r.zone) + 1))

fn data() -> List[Cell] = [Cell { zone: "north", total: 9 }, Cell { zone: "south", total: 3 }, Cell { zone: "north", total: 2 }]

test total_by_value = score_of(total_by(data()), "north") == 11
test tally_by_value = score_of(tally_by(data()), "south") == 1
test total_by_size = map_size(total_by(data())) == 2

# Two aggregations over the same rows: sums and headcounts.
type Item = { group: Str, weight: Int }

fn read_at(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn fold_in(m: Map[Str, Int], k: Str, v: Int) -> Map[Str, Int] =
  map_put(m, k, read_at(m, k) + v)

fn cost_by(xs: List[Item]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, r) => fold_in(acc, r.group, r.weight))

fn people_by(xs: List[Item]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, r) => map_put(acc, r.group, read_at(acc, r.group) + 1))

