# A budget record holding a spending map.
type Budget = { cap: Int, spent: Map[Str, Int] }

fn lookup(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn spend(b: Budget, cat: Str, amt: Int) -> Budget =
  Budget { cap: b.cap, spent: map_put(b.spent, cat, lookup(b.spent, cat) + amt) }

fn outlay(b: Budget) -> Int = fold(map_values(b.spent), 0, fn(a, n) => a + n)

fn fresh() -> Budget = Budget { cap: 10, spent: map_new() }

test outlay_sum = outlay(spend(spend(fresh(), "food", 3), "food", 2)) == 5
test outlay_cap = outlay(spend(fresh(), "rent", 10)) == 10
test spend_field = let b = spend(fresh(), "fun", 4) in lookup(b.spent, "fun") == 4

# A budget record holding a spending map.
type Purse = { limit: Int, outgoings: Map[Str, Int] }

fn value_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn charge(b: Purse, cat: Str, amt: Int) -> Purse =
  Purse { limit: b.limit, outgoings: map_put(b.outgoings, cat, value_of(b.outgoings, cat) + amt) }

fn total_spent(b: Purse) -> Int = fold(map_values(b.outgoings), 0, fn(a, n) => a + n)

fn blank() -> Purse = Purse { limit: 50, outgoings: map_new() }

test total_spent_sum = total_spent(charge(charge(blank(), "food", 3), "food", 2)) == 5
test total_spent_cap = total_spent(charge(blank(), "rent", 50)) == 50
test charge_field = let b = charge(blank(), "fun", 4) in value_of(b.outgoings, "fun") == 4

# A budget record holding a spending map.
type Fund = { ceiling: Int, costs: Map[Str, Int] }

fn count_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn pay_out(b: Fund, cat: Str, amt: Int) -> Fund =
  Fund { ceiling: b.ceiling, costs: map_put(b.costs, cat, count_of(b.costs, cat) + amt) }

fn burn(b: Fund) -> Int = fold(map_values(b.costs), 0, fn(a, n) => a + n)

fn start() -> Fund = Fund { ceiling: 0, costs: map_new() }

test burn_sum = burn(pay_out(pay_out(start(), "food", 3), "food", 2)) == 5
test burn_cap = burn(pay_out(start(), "rent", 0)) == 0
test pay_out_field = let b = pay_out(start(), "fun", 4) in count_of(b.costs, "fun") == 4

# A budget record holding a spending map.
type Pot = { max: Int, charges: Map[Str, Int] }

fn read_at(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn buy(b: Pot, cat: Str, amt: Int) -> Pot =
  Pot { max: b.max, charges: map_put(b.charges, cat, read_at(b.charges, cat) + amt) }

fn sum_spent(b: Pot) -> Int = fold(map_values(b.charges), 0, fn(a, n) => a + n)

