test buy_field = let b = buy(new(), "fun", 4) in read_at(b.charges, "fun") == 4

# A budget record holding a spending map.
type Wallet = { bound: Int, debits: Map[Str, Int] }

fn get_or_zero(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn draw(b: Wallet, cat: Str, amt: Int) -> Wallet =
  Wallet { bound: b.bound, debits: map_put(b.debits, cat, get_or_zero(b.debits, cat) + amt) }

fn cost_total(b: Wallet) -> Int = fold(map_values(b.debits), 0, fn(a, n) => a + n)

fn open() -> Wallet = Wallet { bound: 7, debits: map_new() }

test cost_total_sum = cost_total(draw(draw(open(), "food", 3), "food", 2)) == 5
test cost_total_cap = cost_total(draw(open(), "rent", 7)) == 7
test draw_field = let b = draw(open(), "fun", 4) in get_or_zero(b.debits, "fun") == 4

