# Compare the key sets of two counters.
fn lookup(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn tally(xs: List[Str]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, w) => map_put(acc, w, lookup(acc, w) + 1))

fn common(a: Map[Str, Int], b: Map[Str, Int]) -> List[Str] =
  filter(map_keys(a), fn(k) => map_has(b, k))

fn only_first(a: Map[Str, Int], b: Map[Str, Int]) -> List[Str] =
  filter(map_keys(a), fn(k) => !map_has(b, k))

test common_list = common(tally(["red", "blue", "red", "green", "red"]), tally(["red", "extra"])) == ["red"]
