# Tally the words of a short sentence.
fn split_text(text: Str) -> List[Str] =
  filter(map(split(trim(text), " "), fn(p) => trim(p)), fn(p) => len(p) > 0)

fn read_at(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn phrase_counts(text: Str) -> Map[Str, Int] =
  fold(split_text(text), map_new(), fn(acc, w) => map_put(acc, w, read_at(acc, w) + 1))

test phrase_counts_value = read_at(phrase_counts("red green blue red"), "red") == 2
test phrase_counts_size = map_size(phrase_counts("red green blue red")) == 3
test split_text_count = len(split_text("red green blue red")) == 4

# Tally the words of a short sentence.
fn pieces(text: Str) -> List[Str] =
  filter(map(split(trim(text), " "), fn(p) => trim(p)), fn(p) => len(p) > 0)

fn tally_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn word_freq(text: Str) -> Map[Str, Int] =
  fold(pieces(text), map_new(), fn(acc, w) => map_put(acc, w, tally_of(acc, w) + 1))

test word_freq_value = tally_of(word_freq("go go stop stop go"), "go") == 3
test word_freq_size = map_size(word_freq("go go stop stop go")) == 2
test pieces_count = len(pieces("go go stop stop go")) == 5

# Frequent integers above a count threshold.
fn at(m: Map[Int, Int], k: Int) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn histogram(nums: List[Int]) -> Map[Int, Int] =
  fold(nums, map_new(), fn(acc, n) => map_put(acc, n, at(acc, n) + 1))

fn heavy(m: Map[Int, Int], minimum: Int) -> List[Int] =
  filter(map_keys(m), fn(k) => at(m, k) >= minimum)

test heavy_keys = heavy(histogram([4, 1, 4, 2, 1, 4]), 2) == [1, 4]
test heavy_size = len(heavy(histogram([4, 1, 4, 2, 1, 4]), 2)) == 2
test heavy_none = len(heavy(histogram([4, 1, 4, 2, 1, 4]), 99)) == 0

# Frequent integers above a count threshold.
fn count_at(m: Map[Int, Int], k: Int) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn counter(nums: List[Int]) -> Map[Int, Int] =
  fold(nums, map_new(), fn(acc, n) => map_put(acc, n, count_at(acc, n) + 1))

fn frequent(m: Map[Int, Int], minimum: Int) -> List[Int] =
  filter(map_keys(m), fn(k) => count_at(m, k) >= minimum)

test frequent_keys = frequent(counter([7, 7, 3]), 2) == [7]
test frequent_size = len(frequent(counter([7, 7, 3]), 2)) == 1
test frequent_none = len(frequent(counter([7, 7, 3]), 99)) == 0

# Frequent integers above a count threshold.
fn value_of(m: Map[Int, Int], k: Int) -> Int =
