# Group integers by parity into lists, using a map.
fn key(n: Int) -> Str = if n % 2 == 0 then "even" else "odd"

fn empty_list() -> List[Int] = []

fn bucket(m: Map[Str, List[Int]], k: Str) -> List[Int] =
  match map_get(m, k) { Some(xs) => xs, None => empty_list() }

fn add(m: Map[Str, List[Int]], k: Str, n: Int) -> Map[Str, List[Int]] =
  map_put(m, k, push(bucket(m, k), n))

fn by_parity(nums: List[Int]) -> Map[Str, List[Int]] =
  fold(nums, map_new(), fn(acc, n) => add(acc, key(n), n))

test by_parity_even = bucket(by_parity([4, 1, 4, 2, 1, 4]), "even") == [4, 4, 2, 4]
test by_parity_odd = bucket(by_parity([4, 1, 4, 2, 1, 4]), "odd") == [1, 1]
test by_parity_size = map_size(by_parity([4, 1, 4, 2, 1, 4])) == 2

# Group integers by parity into lists, using a map.
fn parity(n: Int) -> Str = if n % 2 == 0 then "even" else "odd"

fn no_nums() -> List[Int] = []

fn slot(m: Map[Str, List[Int]], k: Str) -> List[Int] =
  match map_get(m, k) { Some(xs) => xs, None => no_nums() }

fn append_num(m: Map[Str, List[Int]], k: Str, n: Int) -> Map[Str, List[Int]] =
  map_put(m, k, push(slot(m, k), n))

fn split_parity(nums: List[Int]) -> Map[Str, List[Int]] =
  fold(nums, map_new(), fn(acc, n) => append_num(acc, parity(n), n))

test split_parity_even = slot(split_parity([7, 7, 3]), "even") == []
test split_parity_odd = slot(split_parity([7, 7, 3]), "odd") == [7, 7, 3]
test split_parity_size = map_size(split_parity([7, 7, 3])) == 1

# Group integers by parity into lists, using a map.
fn label(n: Int) -> Str = if n % 2 == 0 then "even" else "odd"

fn blank() -> List[Int] = []

fn pile(m: Map[Str, List[Int]], k: Str) -> List[Int] =
  match map_get(m, k) { Some(xs) => xs, None => blank() }

fn file(m: Map[Str, List[Int]], k: Str, n: Int) -> Map[Str, List[Int]] =
  map_put(m, k, push(pile(m, k), n))

fn parity_lists(nums: List[Int]) -> Map[Str, List[Int]] =
  fold(nums, map_new(), fn(acc, n) => file(acc, label(n), n))

test parity_lists_even = pile(parity_lists([0, 1, 0, 2, 1, 0]), "even") == [0, 0, 2, 0]
test parity_lists_odd = pile(parity_lists([0, 1, 0, 2, 1, 0]), "odd") == [1, 1]
test parity_lists_size = map_size(parity_lists([0, 1, 0, 2, 1, 0])) == 2

# Group integers by parity into lists, using a map.
fn side(n: Int) -> Str = if n % 2 == 0 then "even" else "odd"

fn none_list() -> List[Int] = []

fn list_slot(m: Map[Str, List[Int]], k: Str) -> List[Int] =
  match map_get(m, k) { Some(xs) => xs, None => none_list() }

fn insert(m: Map[Str, List[Int]], k: Str, n: Int) -> Map[Str, List[Int]] =
  map_put(m, k, push(list_slot(m, k), n))

fn even_odd(nums: List[Int]) -> Map[Str, List[Int]] =
  fold(nums, map_new(), fn(acc, n) => insert(acc, side(n), n))

test even_odd_even = list_slot(even_odd([-2, 5, -2, 5, 5]), "even") == [-2, -2]
test even_odd_odd = list_slot(even_odd([-2, 5, -2, 5, 5]), "odd") == [5, 5, 5]
