# Group integers by parity into lists, using a map.
fn class_of(n: Int) -> Str = if n % 2 == 0 then "even" else "odd"

fn vacant() -> List[Int] = []

fn group_of(m: Map[Str, List[Int]], k: Str) -> List[Int] =
  match map_get(m, k) { Some(xs) => xs, None => vacant() }

fn drop_in(m: Map[Str, List[Int]], k: Str, n: Int) -> Map[Str, List[Int]] =
  map_put(m, k, push(group_of(m, k), n))

fn halves(nums: List[Int]) -> Map[Str, List[Int]] =
  fold(nums, map_new(), fn(acc, n) => drop_in(acc, class_of(n), n))

test halves_even = group_of(halves([9, 8, 9, 9, 8]), "even") == [8, 8]
test halves_odd = group_of(halves([9, 8, 9, 9, 8]), "odd") == [9, 9, 9]
test halves_size = map_size(halves([9, 8, 9, 9, 8])) == 2

# Command variants applied to a record holding a counter map.
type State = { counts: Map[Str, Int], total: Int }

type Cmd = Once(Str) | Twice(Str) | Forget(Str)

fn lookup(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn fresh() -> State = State { counts: map_new(), total: 0 }

fn note(s: State, w: Str) -> State =
  State { counts: map_put(s.counts, w, lookup(s.counts, w) + 1), total: s.total + 1 }

fn apply(s: State, c: Cmd) -> State = match c {
  Once(w) => note(s, w),
  Twice(w) => note(note(s, w), w),
  Forget(w) => State { counts: map_del(s.counts, w), total: s.total },
}

test apply_twice = let s = apply(fresh(), Twice("a")) in lookup(s.counts, "a") == 2 && s.total == 2
test apply_forget = let s = apply(apply(fresh(), Once("b")), Forget("b")) in map_size(s.counts) == 0
test apply_empty = let s = apply(fresh(), Forget("q")) in s.total == 0

# Command variants applied to a record holding a counter map.
type Board = { bag: Map[Str, Int], seen: Int }

type Move = One(Str) | Pair(Str) | Erase(Str)

fn value_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn blank() -> Board = Board { bag: map_new(), seen: 0 }

fn record(s: Board, w: Str) -> Board =
  Board { bag: map_put(s.bag, w, value_of(s.bag, w) + 1), seen: s.seen + 1 }

fn run_cmd(s: Board, c: Move) -> Board = match c {
  One(w) => record(s, w),
  Pair(w) => record(record(s, w), w),
  Erase(w) => Board { bag: map_del(s.bag, w), seen: s.seen },
}

test run_cmd_twice = let s = run_cmd(blank(), Pair("a")) in value_of(s.bag, "a") == 2 && s.seen == 2
test run_cmd_forget = let s = run_cmd(run_cmd(blank(), One("b")), Erase("b")) in map_size(s.bag) == 0
test run_cmd_empty = let s = run_cmd(blank(), Erase("q")) in s.seen == 0

# Command variants applied to a record holding a counter map.
type Sheet = { tally: Map[Str, Int], events: Int }

type Task = Single(Str) | Double(Str) | Clear(Str)

fn count_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn start() -> Sheet = Sheet { tally: map_new(), events: 0 }

fn log_word(s: Sheet, w: Str) -> Sheet =
  Sheet { tally: map_put(s.tally, w, count_of(s.tally, w) + 1), events: s.events + 1 }

fn carry_out(s: Sheet, c: Task) -> Sheet = match c {
  Single(w) => log_word(s, w),
  Double(w) => log_word(log_word(s, w), w),
  Clear(w) => Sheet { tally: map_del(s.tally, w), events: s.events },
}

test carry_out_twice = let s = carry_out(start(), Double("a")) in count_of(s.tally, "a") == 2 && s.events == 2
test carry_out_forget = let s = carry_out(carry_out(start(), Single("b")), Clear("b")) in map_size(s.tally) == 0
test carry_out_empty = let s = carry_out(start(), Clear("q")) in s.events == 0

# Command variants applied to a record holding a counter map.
type Card = { store: Map[Str, Int], visits: Int }

type Act = Tick(Str) | Twice(Str) | Drop(Str)

fn read_at(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn new_state() -> Card = Card { store: map_new(), visits: 0 }

fn enter(s: Card, w: Str) -> Card =
  Card { store: map_put(s.store, w, read_at(s.store, w) + 1), visits: s.visits + 1 }

fn perform(s: Card, c: Act) -> Card = match c {
  Tick(w) => enter(s, w),
  Twice(w) => enter(enter(s, w), w),
  Drop(w) => Card { store: map_del(s.store, w), visits: s.visits },
}

test perform_twice = let s = perform(new_state(), Twice("a")) in read_at(s.store, "a") == 2 && s.visits == 2
test perform_forget = let s = perform(perform(new_state(), Tick("b")), Drop("b")) in map_size(s.store) == 0
test perform_empty = let s = perform(new_state(), Drop("q")) in s.visits == 0

# Command variants applied to a record holding a counter map.
type Log = { ledger: Map[Str, Int], turns: Int }

type Job = Hit(Str) | Two(Str) | Wipe(Str)

fn get_or_zero(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn open() -> Log = Log { ledger: map_new(), turns: 0 }

fn mark(s: Log, w: Str) -> Log =
  Log { ledger: map_put(s.ledger, w, get_or_zero(s.ledger, w) + 1), turns: s.turns + 1 }

fn do(s: Log, c: Job) -> Log = match c {
  Hit(w) => mark(s, w),
  Two(w) => mark(mark(s, w), w),
  Wipe(w) => Log { ledger: map_del(s.ledger, w), turns: s.turns },
}

test do_twice = let s = do(open(), Two("a")) in get_or_zero(s.ledger, "a") == 2 && s.turns == 2
test do_forget = let s = do(do(open(), Hit("b")), Wipe("b")) in map_size(s.ledger) == 0
test do_empty = let s = do(open(), Wipe("q")) in s.turns == 0

