# A scoreboard built from a list of scoring events.
type Event = { who: Str, pts: Int }

fn lookup(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn board(xs: List[Event]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, e) => map_put(acc, e.who, lookup(acc, e.who) + e.pts))

fn champ(m: Map[Str, Int]) -> Option[Str] =
  let start: Option[Str] = None in
  fold(map_keys(m), start, fn(best, k) =>
    match best {
      None => Some(k),
      Some(b) => if lookup(m, k) > lookup(m, b) then Some(k) else best,
    })

fn events() -> List[Event] = [Event { who: "ann", pts: 5 }, Event { who: "bo", pts: 7 }, Event { who: "ann", pts: 3 }]

test board_score = lookup(board(events()), "ann") == 8
test champ_winner = champ(board(events())) == Some("ann")
test board_size = map_size(board(events())) == 2

# A scoreboard built from a list of scoring events.
type Score = { player: Str, points: Int }

fn value_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn scoreboard(xs: List[Score]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, e) => map_put(acc, e.player, value_of(acc, e.player) + e.points))

fn leader(m: Map[Str, Int]) -> Option[Str] =
  let start: Option[Str] = None in
  fold(map_keys(m), start, fn(best, k) =>
    match best {
      None => Some(k),
      Some(b) => if value_of(m, k) > value_of(m, b) then Some(k) else best,
    })

fn plays() -> List[Score] = [Score { player: "kai", points: 2 }, Score { player: "lia", points: 9 }, Score { player: "kai", points: 1 }]

test scoreboard_score = value_of(scoreboard(plays()), "kai") == 3
test leader_winner = leader(scoreboard(plays())) == Some("lia")
test scoreboard_size = map_size(scoreboard(plays())) == 2

