# A scoreboard built from a list of scoring events.
type Point = { who: Str, score: Int }

fn read_at(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn totals(xs: List[Point]) -> Map[Str, Int] =
