fn best_player(m: Map[Str, Int]) -> Option[Str] =
  let start: Option[Str] = None in
  fold(map_keys(m), start, fn(best, k) =>
    match best {
      None => Some(k),
      Some(b) => if read_at(m, k) > read_at(m, b) then Some(k) else best,
    })

fn moves() -> List[Point] = [Point { who: "ivy", score: 10 }, Point { who: "jon", score: 3 }, Point { who: "ivy", score: 5 }]

test totals_score = read_at(totals(moves()), "ivy") == 15
test best_player_winner = best_player(totals(moves())) == Some("ivy")
