# A scoreboard built from a list of scoring events.
type Goal = { player: Str, delta: Int }

fn count_of(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn table(xs: List[Goal]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, e) => map_put(acc, e.player, count_of(acc, e.player) + e.delta))

fn top_name(m: Map[Str, Int]) -> Option[Str] =
  let start: Option[Str] = None in
  fold(map_keys(m), start, fn(best, k) =>
