  else match get(xs, 0) {
    Some(a) => match get(xs, 1) {
      Some(b) => if a < 0 || b < 0 then Err(BadCode(a + b)) else Ok(a * 10 + b),
      None => Err(ShortCode)
    },
    None => Err(ShortCode)
  }
