test bracket_senior = bracket(70) == Err(Senior(70))

type PwErr = NoUpper | NoDigit | TooShort(Int)
fn check_pw(s: Str) -> Result[Int, PwErr] =
  if len(s) < 6 then Err(TooShort(len(s)))
  else if !contains(s, from_char_code(65)) then Err(NoUpper)
  else if !contains(s, from_int(1)) then Err(NoDigit)
  else Ok(len(s))
test check_pw_ok = check_pw(from_char_code(65) ++ from_int(12345)) == Ok(6)
test check_pw_bad = check_pw(from_int(123456)) == Err(NoUpper)

type BoundedErr = Under(Int) | Over(Int)
fn bounded(n: Int) -> Result[Int, BoundedErr] =
