test over_hit = first_over([2, 9, 4], 0, 5) == Some(9)
test over_miss = first_over([2, 4], 0, 5) == None

fn last_over(xs: List[Int], i: Int, t: Int, acc: Option[Int]) -> Option[Int] =
  if i >= len(xs) then acc
  else match get(xs, i) {
    Some(n) => if n > t then last_over(xs, i + 1, t, Some(n)) else last_over(xs, i + 1, t, acc),
    None => acc
  }
test last_over_hit = last_over([9, 2, 8], 0, 5, None) == Some(8)
test last_over_miss = last_over([1, 2], 0, 5, None) == None

