type SumErr = Stop(Int)
fn sum_until(xs: List[Int], i: Int, acc: Int) -> Result[Int, SumErr] =
  if i >= len(xs) then Ok(acc)
  else match get(xs, i) {
    Some(n) => if n < 0 then Err(Stop(n)) else sum_until(xs, i + 1, acc + n),
    None => Ok(acc)
  }
