test validate_bad = validate_all([1, -1], 0) == Err(BadValue(-1))

type BadErr = Found(Int)
fn find_bad(xs: List[Int], i: Int) -> Result[Int, BadErr] =
  if i >= len(xs) then Ok(-1)
  else match get(xs, i) {
    Some(n) => if n == 0 then Err(Found(i)) else find_bad(xs, i + 1),
    None => Ok(-1)
  }
