type ZeroErr = HitZero(Int)
fn sum_until_zero(xs: List[Int], i: Int, acc: Int) -> Result[Int, ZeroErr] =
  if i >= len(xs) then Ok(acc)
  else match get(xs, i) {
    Some(n) => if n == 0 then Err(HitZero(acc)) else sum_until_zero(xs, i + 1, acc + n),
    None => Ok(acc)
  }
test zero_ok = sum_until_zero([1, 2], 0, 0) == Ok(3)
test zero_hit = sum_until_zero([1, 0, 2], 0, 0) == Err(HitZero(1))

type AvgErr = EmptyList | Negative(Int)
fn avg_sum(xs: List[Int], i: Int) -> Result[Int, AvgErr] =
  if len(xs) == 0 then Err(EmptyList)
  else if i >= len(xs) then Ok(0)
  else match get(xs, i) {
    Some(n) => if n < 0 then Err(Negative(n)) else match avg_sum(xs, i + 1) { Ok(s) => Ok(n + s), Err(e) => Err(e) },
    None => Ok(0)
  }
test avg_ok = avg_sum([2, 4], 0) == Ok(6)
test avg_empty = avg_sum([], 0) == Err(EmptyList)

type DupErr = Dup(Int)
fn dup_adj(xs: List[Int], i: Int) -> Result[Int, DupErr] =
  if i + 1 >= len(xs) then Ok(-1)
  else match get(xs, i) {
    Some(a) => match get(xs, i + 1) {
      Some(b) => if a == b then Err(Dup(a)) else dup_adj(xs, i + 1),
      None => Ok(-1)
    },
    None => Ok(-1)
  }
test dup_hit = dup_adj([1, 2, 2], 0) == Err(Dup(2))
test dup_none = dup_adj([1, 2], 0) == Ok(-1)

type SortErr = OutOfOrder(Int, Int)
fn sorted(xs: List[Int], i: Int) -> Result[Int, SortErr] =
  if i + 1 >= len(xs) then Ok(1)
  else match get(xs, i) {
    Some(a) => match get(xs, i + 1) {
      Some(b) => if a > b then Err(OutOfOrder(a, b)) else sorted(xs, i + 1),
      None => Ok(1)
    },
    None => Ok(1)
  }
