type Heap[T] = HLeaf | HNode(Heap[T], T, Heap[T])
fn heap_size[T](t: Heap[T]) -> Int = match t { HLeaf => 0, HNode(l, _, r) => heap_size(l) + 1 + heap_size(r) }
test heap_size_pair = heap_size(HNode(HLeaf, 10, HNode(HLeaf, 20, HLeaf))) == 2

type Ast[T] = ALeaf | ANode(Ast[T], T, Ast[T])
fn ast_count[T](t: Ast[T]) -> Int = match t { ALeaf => 0, ANode(l, _, r) => 1 + ast_count(l) + ast_count(r) }
test ast_count_float = ast_count(ANode(ALeaf, 1.5, ALeaf)) == 1

type Tree2[T] = Leaf2 | Node2(Tree2[T], T, Tree2[T])
fn node_total[T](t: Tree2[T]) -> Int = match t { Leaf2 => 0, Node2(l, _, r) => 1 + node_total(l) + node_total(r) }
test node_total_two = node_total(Node2(Node2(Leaf2, "a", Leaf2), "b", Leaf2)) == 2

type Chain[T] = End | Link(Chain[T], T, Chain[T])
fn links[T](t: Chain[T]) -> Int = links_acc(t, 0)
fn links_acc[T](t: Chain[T], acc: Int) -> Int = match t { End => acc, Link(l, _, r) => links_acc(r, links_acc(l, acc + 1)) }
test links_three = links(Link(Link(End, 1, End), 2, Link(End, 3, End))) == 3

type Bin[T] = Empty | Fork(Bin[T], T, Bin[T])
fn tall[T](t: Bin[T]) -> Int = match t { Empty => 0, Fork(l, _, r) => let a = tall(l) in let b = tall(r) in 1 + (if a > b then a else b) }
test tall_leaf = tall(Fork(Empty, 2, Fork(Empty, 3, Empty))) == 2

type Bin[T] = Empty | Fork(Bin[T], T, Bin[T])
fn flip[T](t: Bin[T]) -> Bin[T] = match t { Empty => Empty, Fork(l, x, r) => Fork(flip(r), x, flip(l)) }
fn sample() -> Bin[Int] = Fork(Fork(Empty, 1, Empty), 2, Fork(Empty, 3, Empty))
test flip_twice = flip(flip(sample())) == sample()

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn transform[T, U](t: Tree[T], f: fn(T) -> U) -> Tree[U] = match t { Leaf => Leaf, Node(l, x, r) => Node(transform(l, f), f(x), transform(r, f)) }
test transform_inc = transform(Node(Node(Leaf, 1, Leaf), 2, Leaf), fn(n) => n + 10) == Node(Node(Leaf, 11, Leaf), 12, Leaf)

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn label[T](t: Tree[T], f: fn(T) -> Str) -> Tree[Str] = match t { Leaf => Leaf, Node(l, x, r) => Node(label(l, f), f(x), label(r, f)) }
test label_bool = label(Node(Leaf, true, Leaf), fn(b) => if b then "yes" else "no") == Node(Leaf, "yes", Leaf)

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn inorder[T](t: Tree[T]) -> List[T] = match t { Leaf => [], Node(l, x, r) => inorder(l) ++ [x] ++ inorder(r) }
test inorder_sorted = inorder(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == [1, 2, 3]

type BTree[T] = Tip | Branch(BTree[T], T, BTree[T])
fn preorder[T](t: BTree[T]) -> List[T] = match t { Tip => [], Branch(l, x, r) => [x] ++ preorder(l) ++ preorder(r) }
test preorder_three = preorder(Branch(Branch(Tip, "a", Tip), "b", Tip)) == ["b", "a"]

type Bin[T] = Empty | Fork(Bin[T], T, Bin[T])
fn postorder[T](t: Bin[T]) -> List[T] = match t { Empty => [], Fork(l, x, r) => postorder(l) ++ postorder(r) ++ [x] }
test postorder_small = postorder(Fork(Fork(Empty, 1, Empty), 2, Empty)) == [1, 2]

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn right_list[T](t: Tree[T]) -> List[T] = match t { Leaf => [], Node(l, x, r) => right_list(r) ++ [x] ++ right_list(l) }
test right_list_rev = right_list(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == [3, 2, 1]

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn leaves_of[T](t: Tree[T]) -> List[T] = match t { Leaf => [], Node(Leaf, x, Leaf) => [x], Node(l, _, r) => leaves_of(l) ++ leaves_of(r) }
test leaves_two = leaves_of(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == [1, 3]

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn inorder[T](t: Tree[T]) -> List[T] = match t { Leaf => [], Node(l, x, r) => inorder(l) ++ [x] ++ inorder(r) }
fn mirror[T](t: Tree[T]) -> Tree[T] = match t { Leaf => Leaf, Node(l, x, r) => Node(mirror(r), x, mirror(l)) }
test mirror_reverses = inorder(mirror(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf)))) == [3, 2, 1]

type Pair[A, B] = { fst: A, snd: B }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn pairs(t: Tree[Pair[Int, Str]]) -> List[Pair[Int, Str]] = match t { Leaf => [], Node(l, p, r) => pairs(l) ++ [p] ++ pairs(r) }
test pairs_one = pairs(Node(Leaf, Pair { fst: 1, snd: "x" }, Leaf)) == [Pair { fst: 1, snd: "x" }]

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn count_t[T](t: Tree[T]) -> Int = match t { Leaf => 0, Node(l, _, r) => 1 + count_t(l) + count_t(r) }
fn forest_count[T](ts: List[Tree[T]]) -> Int = fold(ts, 0, fn(a, t) => a + count_t(t))
test forest_count_three = forest_count([Node(Leaf, 1, Leaf), Node(Node(Leaf, 2, Leaf), 3, Leaf)]) == 3

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn height_t(t: Tree[Int]) -> Int = match t { Leaf => 0, Node(l, _, r) => 1 + max_of(height_t(l), height_t(r)) }
fn max_of(a: Int, b: Int) -> Int = if a > b then a else b
fn tallest(ts: List[Tree[Int]]) -> Int = fold(ts, 0, fn(a, t) => let h = height_t(t) in if h > a then h else a)
test tallest_two = tallest([Node(Leaf, 1, Leaf), Node(Node(Leaf, 2, Leaf), 3, Leaf)]) == 2

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn count_if[T](t: Tree[T], p: fn(T) -> Bool) -> Int = match t { Leaf => 0, Node(l, x, r) => (if p(x) then 1 else 0) + count_if(l, p) + count_if(r, p) }
test count_if_big = count_if(Node(Node(Leaf, 1, Leaf), 5, Node(Leaf, 9, Leaf)), fn(n) => n > 4) == 2

type BTree[T] = Tip | Branch(BTree[T], T, BTree[T])
fn cnt[T](t: BTree[T]) -> Int = match t { Tip => 0, Branch(l, _, r) => 1 + cnt(l) + cnt(r) }
fn count_if[T](t: BTree[T], p: fn(T) -> Bool) -> Int = match t { Tip => 0, Branch(l, x, r) => (if p(x) then 1 else 0) + count_if(l, p) + count_if(r, p) }
fn all_of[T](t: BTree[T], p: fn(T) -> Bool) -> Bool = count_if(t, p) == cnt(t)
test all_positive = all_of(Branch(Branch(Tip, 1, Tip), 2, Tip), fn(n) => n > 0)
test not_all_big = !all_of(Branch(Branch(Tip, 1, Tip), 2, Tip), fn(n) => n > 1)

type Pair[A, B] = { fst: A, snd: B }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn count_if[T](t: Tree[T], p: fn(T) -> Bool) -> Int = match t { Leaf => 0, Node(l, x, r) => (if p(x) then 1 else 0) + count_if(l, p) + count_if(r, p) }
test pair_pred = count_if(Node(Leaf, Pair { fst: 2, snd: true }, Leaf), fn(p) => p.snd && p.fst > 1) == 1

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn count_if[T](t: Tree[T], p: fn(T) -> Bool) -> Int = match t { Leaf => 0, Node(l, x, r) => (if p(x) then 1 else 0) + count_if(l, p) + count_if(r, p) }
fn odd(n: Int) -> Bool = n % 2 != 0
fn odds(t: Tree[Int]) -> Int = count_if(t, odd)
test odds_two = odds(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == 2

fn both[A](p: fn(A) -> Bool, q: fn(A) -> Bool, x: A) -> Bool = p(x) && q(x)
test both_ok = both(fn(n) => n > 0, fn(n) => n < 10, 5)
test both_fail = !both(fn(n) => n > 0, fn(n) => n < 10, 50)

fn apply_twice[A](f: fn(A) -> A, x: A) -> A = f(f(x))
test twice_add = apply_twice(fn(n) => n + 3, 1) == 7
test twice_str = apply_twice(fn(s) => s ++ "!", "hi") == "hi!!"

fn pipe[A, B, C](x: A, f: fn(A) -> B, g: fn(B) -> C) -> C = g(f(x))
test pipe_num = pipe(2, fn(n) => n + 1, fn(n) => n * 10) == 30
test pipe_text = pipe("ab", fn(s) => len(s), fn(n) => n + 1) == 3

fn map_each[A](xs: List[A], f: fn(A) -> A) -> List[A] = map(xs, f)
test map_each_bang = map_each(["a", "b"], fn(s) => s ++ "!") == ["a!", "b!"]
test map_each_neg = map_each([1, -2], fn(n) => -n) == [-1, 2]

type Box[T] = { item: T }
fn map_box[T, U](b: Box[T], f: fn(T) -> U) -> Box[U] = Box { item: f(b.item) }
test map_box_add = map_box(Box { item: 2 }, fn(n) => n + 3) == Box { item: 5 }

type Pair[A, B] = { fst: A, snd: B }
fn swap[A, B](p: Pair[A, B]) -> Pair[B, A] = Pair { fst: p.snd, snd: p.fst }
test swap_pair = swap(Pair { fst: 1, snd: "z" }) == Pair { fst: "z", snd: 1 }

type Pair[A, B] = { fst: A, snd: B }
fn map_first[A, B, C](p: Pair[A, B], f: fn(A) -> C) -> Pair[C, B] = Pair { fst: f(p.fst), snd: p.snd }
test map_first_len = map_first(Pair { fst: "abc", snd: 2 }, fn(s) => len(s)) == Pair { fst: 3, snd: 2 }

type Either[A, B] = Le(A) | Ri(B)
fn map_ri[A, B, C](e: Either[A, B], f: fn(B) -> C) -> Either[A, C] = match e { Le(a) => Le(a), Ri(b) => Ri(f(b)) }
fn bump_right(e: Either[Str, Int]) -> Either[Str, Int] = map_ri(e, fn(n) => n + 1)
test map_ri_left = map_ri(Le(1), fn(n: Int) => n + 1) == Le(1)
test map_ri_right = bump_right(Ri(2)) == Ri(3)

type State[A, B] = { fst: A, snd: B }
fn map_snd[A, B, C](s: State[A, B], f: fn(B) -> C) -> State[A, C] = State { fst: s.fst, snd: f(s.snd) }
test map_snd_inc = map_snd(State { fst: "a", snd: 1 }, fn(n) => n + 1) == State { fst: "a", snd: 2 }

type Box[T] = { item: T }
fn wrap[T](x: T) -> Box[T] = Box { item: x }
fn unwrap[T](b: Box[T]) -> T = b.item
fn nest[T](b: Box[T]) -> Box[Box[T]] = wrap(b)
test unwrap_nested = unwrap(unwrap(nest(wrap(3)))) == 3

type Pair[A, B] = { fst: A, snd: B }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn count[T](t: Tree[T]) -> Int = match t { Leaf => 0, Node(l, _, r) => 1 + count(l) + count(r) }
fn both_counts(t: Tree[Int], u: Tree[Str]) -> Pair[Int, Int] = Pair { fst: count(t), snd: count(u) }
test both_counts_one = both_counts(Node(Leaf, 1, Leaf), Node(Leaf, "a", Node(Leaf, "b", Leaf))) == Pair { fst: 1, snd: 2 }

type Box[T] = { item: T }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn in_box[T](t: Tree[T]) -> Box[Tree[T]] = Box { item: t }
fn item_of[T](b: Box[T]) -> T = b.item
test boxed_tree = item_of(in_box(Node(Leaf, 6, Leaf))) == Node(Leaf, 6, Leaf)

type Pair[A, B] = { fst: A, snd: B }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn maxi(a: Int, b: Int) -> Int = if a > b then a else b
fn stats[T](t: Tree[T]) -> Pair[Int, Int] = match t { Leaf => Pair { fst: 0, snd: 0 }, Node(l, _, r) => let sl = stats(l) in let sr = stats(r) in Pair { fst: 1 + sl.fst + sr.fst, snd: 1 + maxi(sl.snd, sr.snd) } }
test stats_chain = stats(Node(Node(Leaf, 1, Leaf), 2, Leaf)) == Pair { fst: 2, snd: 2 }

type BTree[T] = Tip | Branch(BTree[T], T, BTree[T])
fn path_sum[T](t: BTree[T], d: Int) -> Int = match t { Tip => 0, Branch(l, _, r) => d + path_sum(l, d + 1) + path_sum(r, d + 1) }
test path_sum_chain = path_sum(Branch(Branch(Tip, 1, Tip), 2, Tip), 0) == 1

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn rot_left[T](t: Tree[T]) -> Tree[T] = match t { Leaf => Leaf, Node(l, x, Leaf) => Node(l, x, Leaf), Node(l, x, Node(m, y, r)) => Node(Node(l, x, m), y, r) }
test rot_left_shape = rot_left(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == Node(Node(Node(Leaf, 1, Leaf), 2, Leaf), 3, Leaf)

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn push_left[T](t: Tree[T], x: T) -> Tree[T] = match t { Leaf => Node(Leaf, x, Leaf), Node(l, v, r) => Node(push_left(l, x), v, r) }
test push_left_shape = push_left(Node(Leaf, 2, Leaf), 1) == Node(Node(Leaf, 1, Leaf), 2, Leaf)

type Bin[T] = Empty | Fork(Bin[T], T, Bin[T])
fn push_right[T](t: Bin[T], x: T) -> Bin[T] = match t { Empty => Fork(Empty, x, Empty), Fork(l, v, r) => Fork(l, v, push_right(r, x)) }
test push_right_shape = push_right(Fork(Empty, 1, Empty), 2) == Fork(Empty, 1, Fork(Empty, 2, Empty))

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn left_nodes[T](t: Tree[T]) -> Int = match t { Leaf => 0, Node(l, _, r) => 1 + left_nodes(l) + left_nodes(r) }
test left_nodes_two = left_nodes(Node(Node(Leaf, 1, Leaf), 2, Leaf)) == 2

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn internal[T](t: Tree[T]) -> Int = match t { Leaf => 0, Node(Leaf, _, Leaf) => 0, Node(l, _, r) => 1 + internal(l) + internal(r) }
test internal_two = internal(Node(Node(Leaf, 1, Node(Leaf, 2, Leaf)), 3, Leaf)) == 2

type Tree = Leaf | Node(Tree, Int, Tree)
fn sum(t: Tree) -> Int = match t { Leaf => 0, Node(l, x, r) => x + sum(l) + sum(r) }
test sum_three = sum(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == 6

type Tree = Leaf | Node(Tree, Int, Tree)
fn total_acc(t: Tree, acc: Int) -> Int = match t { Leaf => acc, Node(l, x, r) => total_acc(r, total_acc(l, acc + x)) }
test total_acc_two = total_acc(Node(Node(Leaf, 4, Leaf), 6, Leaf), 0) == 10

type Tree = Leaf | Node(Tree, Int, Tree)
fn biggest(a: Int, b: Option[Int]) -> Int = match b { None => a, Some(y) => if y > a then y else a }
fn max_val(t: Tree) -> Option[Int] = match t { Leaf => None, Node(l, x, r) => Some(biggest(biggest(x, max_val(l)), max_val(r))) }
test max_val_deep = max_val(Node(Node(Leaf, 4, Leaf), 9, Node(Leaf, 2, Leaf))) == Some(9)

type Tree = Leaf | Node(Tree, Int, Tree)
fn smaller(a: Int, b: Option[Int]) -> Int = match b { None => a, Some(y) => if y < a then y else a }
fn min_val(t: Tree) -> Option[Int] = match t { Leaf => None, Node(l, x, r) => Some(smaller(smaller(x, min_val(l)), min_val(r))) }
test min_val_two = min_val(Node(Leaf, 5, Node(Leaf, 2, Leaf))) == Some(2)

type Tree = Leaf | Node(Tree, Int, Tree)
fn between(t: Tree, lo: Int, hi: Int) -> Bool = match t { Leaf => true, Node(l, x, r) => lo < x && x < hi && between(l, lo, x) && between(r, x, hi) }
fn sorted(t: Tree) -> Bool = match t { Leaf => true, Node(l, x, r) => between(l, -1000, x) && between(r, x, 1000) }
test sorted_ok = sorted(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf)))
test sorted_bad = !sorted(Node(Node(Leaf, 5, Leaf), 2, Leaf))

type Tree = Leaf | Node(Tree, Int, Tree)
fn insert(t: Tree, x: Int) -> Tree = match t { Leaf => Node(Leaf, x, Leaf), Node(l, v, r) => if x < v then Node(insert(l, x), v, r) else if x > v then Node(l, v, insert(r, x)) else t }
fn has(t: Tree, x: Int) -> Bool = match t { Leaf => false, Node(l, v, r) => if x == v then true else if x < v then has(l, x) else has(r, x) }
test insert_then_has = has(insert(insert(Node(Leaf, 5, Leaf), 2), 8), 8)
test insert_dup = has(insert(insert(Node(Leaf, 5, Leaf), 5), 1), 5)

type Tree = Leaf | Node(Tree, Int, Tree)
fn insert(t: Tree, x: Int) -> Tree = match t { Leaf => Node(Leaf, x, Leaf), Node(l, v, r) => if x < v then Node(insert(l, x), v, r) else if x > v then Node(l, v, insert(r, x)) else t }
fn has(t: Tree, x: Int) -> Bool = match t { Leaf => false, Node(l, v, r) => if x == v then true else if x < v then has(l, x) else has(r, x) }
fn from_list(xs: List[Int]) -> Tree = fold(xs, Leaf, fn(t, x) => insert(t, x))
test from_list_has = has(from_list([3, 1, 2]), 2)

type Tree = Leaf | Node(Tree, Int, Tree)
fn flatten(t: Tree) -> List[Int] = match t { Leaf => [], Node(l, x, r) => flatten(l) ++ [x] ++ flatten(r) }
test flatten_bst = flatten(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == [1, 2, 3]

type Tree = Leaf | Node(Tree, Int, Tree)
fn negatives(t: Tree) -> Int = match t { Leaf => 0, Node(l, x, r) => (if x < 0 then 1 else 0) + negatives(l) + negatives(r) }
test negatives_one = negatives(Node(Node(Leaf, -3, Leaf), 4, Leaf)) == 1

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn join_all(t: Tree[Str]) -> Str = match t { Leaf => "", Node(l, s, r) => join_all(l) ++ s ++ join_all(r) }
test join_two = join_all(Node(Node(Leaf, "ab", Leaf), "cd", Leaf)) == "abcd"

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn count_true(t: Tree[Bool]) -> Int = match t { Leaf => 0, Node(l, b, r) => (if b then 1 else 0) + count_true(l) + count_true(r) }
test count_true_two = count_true(Node(Node(Leaf, true, Leaf), false, Node(Leaf, true, Leaf))) == 2

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn sum_floats(t: Tree[Float]) -> Float = match t { Leaf => 0.0, Node(l, x, r) => x + sum_floats(l) + sum_floats(r) }
test sum_floats_small = sum_floats(Node(Node(Leaf, 1.5, Leaf), 2.0, Leaf)) == 3.5

type Pair[A, B] = { fst: A, snd: B }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn pair_sum(t: Tree[Pair[Int, Int]]) -> Int = match t { Leaf => 0, Node(l, p, r) => p.fst + p.snd + pair_sum(l) + pair_sum(r) }
test pair_sum_two = pair_sum(Node(Node(Leaf, Pair { fst: 1, snd: 2 }, Leaf), Pair { fst: 3, snd: 4 }, Leaf)) == 10

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn list_sizes(t: Tree[List[Int]]) -> Int = match t { Leaf => 0, Node(l, xs, r) => len(xs) + list_sizes(l) + list_sizes(r) }
test list_sizes_two = list_sizes(Node(Node(Leaf, [1, 2], Leaf), [3], Leaf)) == 3

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn is_some[T](o: Option[T]) -> Bool = match o { Some(_) => true, None => false }
fn count_some(t: Tree[Option[Int]]) -> Int = match t { Leaf => 0, Node(l, o, r) => (if is_some(o) then 1 else 0) + count_some(l) + count_some(r) }
test count_some_two = count_some(Node(Node(Leaf, Some(1), Leaf), None, Leaf)) == 1

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn is_ok(v: Result[Int, Str]) -> Bool = match v { Ok(_) => true, Err(_) => false }
fn count_ok(t: Tree[Result[Int, Str]]) -> Int = match t { Leaf => 0, Node(l, v, r) => (if is_ok(v) then 1 else 0) + count_ok(l) + count_ok(r) }
test count_ok_two = count_ok(Node(Node(Leaf, Ok(1), Leaf), Err("bad"), Leaf)) == 1

type Rec = { k: Int, v: Str }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn rec_keys(t: Tree[Rec]) -> List[Int] = match t { Leaf => [], Node(l, r, rr) => rec_keys(l) ++ [r.k] ++ rec_keys(rr) }
test rec_keys_one = rec_keys(Node(Leaf, Rec { k: 7, v: "x" }, Leaf)) == [7]

type Pair[A, B] = { fst: A, snd: B }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn names(t: Tree[Pair[Str, Int]]) -> List[Str] = match t { Leaf => [], Node(l, p, r) => names(l) ++ [p.fst] ++ names(r) }
test names_two = names(Node(Leaf, Pair { fst: "ab", snd: 1 }, Leaf)) == ["ab"]

type Rose[T] = RBranch(T, List[Rose[T]])
fn rose_total(r: Rose[Int]) -> Int = match r { RBranch(x, kids) => x + rose_totals(kids) }
fn rose_totals(kids: List[Rose[Int]]) -> Int = fold(kids, 0, fn(a, c) => a + rose_total(c))
test rose_total_two = rose_total(RBranch(1, [RBranch(2, []), RBranch(3, [])])) == 6

type Rose[T] = RBranch(T, List[Rose[T]])
fn rose_map[T, U](r: Rose[T], f: fn(T) -> U) -> Rose[U] = match r { RBranch(x, kids) => RBranch(f(x), rose_map_list(kids, f)) }
fn rose_map_list[T, U](kids: List[Rose[T]], f: fn(T) -> U) -> List[Rose[U]] = map(kids, fn(c) => rose_map(c, f))
test rose_map_double = rose_map(RBranch(1, [RBranch(2, [])]), fn(n) => n * 2) == RBranch(2, [RBranch(4, [])])

type Rose[T] = RBranch(T, List[Rose[T]])
fn leaves_a[T](r: Rose[T]) -> Int = match r { RBranch(_, kids) => if len(kids) == 0 then 1 else leaf_lists(kids) }
fn leaf_lists[T](kids: List[Rose[T]]) -> Int = fold(kids, 0, fn(a, c) => a + leaves_a(c))
