type Rose[T] = RBranch(T, List[Rose[T]])
fn rmax(a: Int, b: Int) -> Int = if a > b then a else b
fn rose_max(r: Rose[Int]) -> Int = match r { RBranch(x, kids) => rmax(x, kid_max(kids)) }
fn kid_max(kids: List[Rose[Int]]) -> Int = fold(kids, -1000000, fn(a, c) => rmax(a, rose_max(c)))
test rose_max_two = rose_max(RBranch(1, [RBranch(5, []), RBranch(2, [])])) == 5

type Rose[T] = RBranch(T, List[Rose[T]])
fn rose_len(r: Rose[Str]) -> Int = match r { RBranch(s, kids) => len(s) + kid_len(kids) }
fn kid_len(kids: List[Rose[Str]]) -> Int = fold(kids, 0, fn(a, c) => a + rose_len(c))
test rose_len_three = rose_len(RBranch("ab", [RBranch("c", [])])) == 3

type Rose[T] = RBranch(T, List[Rose[T]])
fn rlist[T](r: Rose[T]) -> List[T] = match r { RBranch(x, kids) => [x] ++ flat_kids(kids) }
fn flat_kids[T](kids: List[Rose[T]]) -> List[T] = let base: List[T] = [] in fold(kids, base, fn(a, c) => a ++ rlist(c))
test rlist_two = rlist(RBranch(1, [RBranch(2, []), RBranch(3, [])])) == [1, 2, 3]

type Rose[T] = RBranch(T, List[Rose[T]])
fn rose_label(r: Rose[Int]) -> Rose[Str] = match r { RBranch(x, kids) => RBranch(from_int(x), rose_label_list(kids)) }
fn rose_label_list(kids: List[Rose[Int]]) -> List[Rose[Str]] = map(kids, fn(c) => rose_label(c))
test rose_label_one = rose_label(RBranch(7, [])) == RBranch("7", [])

type Rose[T] = RBranch(T, List[Rose[T]])
fn rose_all[T](r: Rose[T], p: fn(T) -> Bool) -> Bool = match r { RBranch(x, kids) => p(x) && rose_all_list(kids, p) }
fn rose_all_list[T](kids: List[Rose[T]], p: fn(T) -> Bool) -> Bool = fold(kids, true, fn(a, c) => a && rose_all(c, p))
test rose_all_ok = rose_all(RBranch(1, [RBranch(2, [])]), fn(n) => n < 5)

type Tri[T] = TEnd | TNode(Tri[T], T, Tri[T], T, Tri[T])
fn tri_sum(t: Tri[Int]) -> Int = match t { TEnd => 0, TNode(a, x, b, y, c) => x + y + tri_sum(a) + tri_sum(b) + tri_sum(c) }
test tri_sum_one = tri_sum(TNode(TEnd, 1, TEnd, 2, TEnd)) == 3

type Quad[T] = QEnd | QNode(Quad[T], T, Quad[T], T, Quad[T], T, Quad[T])
fn quad_sum(t: Quad[Int]) -> Int = match t { QEnd => 0, QNode(a, x, b, y, c, z, d) => x + y + z + quad_sum(a) + quad_sum(b) + quad_sum(c) + quad_sum(d) }
test quad_sum_one = quad_sum(QNode(QEnd, 1, QEnd, 2, QEnd, 3, QEnd)) == 6

type Tri[T] = TEnd | TNode(Tri[T], T, Tri[T], T, Tri[T])
fn tri_map[T, U](t: Tri[T], f: fn(T) -> U) -> Tri[U] = match t { TEnd => TEnd, TNode(a, x, b, y, c) => TNode(tri_map(a, f), f(x), tri_map(b, f), f(y), tri_map(c, f)) }
test tri_map_inc = tri_map(TNode(TEnd, 1, TEnd, 2, TEnd), fn(n) => n + 1) == TNode(TEnd, 2, TEnd, 3, TEnd)

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn map_option[T](t: Tree[T], f: fn(T) -> T) -> Tree[T] = match t { Leaf => Leaf, Node(l, x, r) => Node(map_option(l, f), f(x), map_option(r, f)) }
test map_option_inc = map_option(Node(Leaf, 1, Leaf), fn(n) => n + 5) == Node(Leaf, 6, Leaf)

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn branch_count[T](t: Tree[T]) -> Int = match t { Leaf => 0, Node(Leaf, _, Leaf) => 0, Node(l, _, r) => 1 + branch_count(l) + branch_count(r) }
test branch_one = branch_count(Node(Node(Leaf, 1, Node(Leaf, 2, Leaf)), 3, Leaf)) == 2

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn swap_children[T](t: Tree[T]) -> Tree[T] = match t { Leaf => Leaf, Node(l, x, r) => Node(r, x, l) }
test swap_once = swap_children(Node(Node(Leaf, 1, Leaf), 2, Leaf)) == Node(Leaf, 2, Node(Leaf, 1, Leaf))

type Tree = Leaf | Node(Tree, Int, Tree)
fn find_depth(t: Tree, x: Int, d: Int) -> Option[Int] = match t { Leaf => None, Node(l, v, r) => if v == x then Some(d) else match find_depth(l, x, d + 1) { Some(k) => Some(k), None => find_depth(r, x, d + 1) } }
test find_depth_one = find_depth(Node(Node(Leaf, 1, Leaf), 2, Leaf), 1, 0) == Some(1)

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn collect_odd(t: Tree[Int]) -> List[Int] = match t { Leaf => [], Node(l, x, r) => collect_odd(l) ++ (if x % 2 != 0 then [x] else []) ++ collect_odd(r) }
test collect_odd_two = collect_odd(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == [1, 3]

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn repeat_tree[T](x: T, n: Int) -> Tree[T] = if n <= 0 then Leaf else Node(repeat_tree(x, n - 1), x, repeat_tree(x, n - 1))
test repeat_two = repeat_tree(7, 2) == Node(Node(Leaf, 7, Leaf), 7, Node(Leaf, 7, Leaf))

type Box[T] = { item: T }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn box_sum(t: Tree[Box[Int]]) -> Int = match t { Leaf => 0, Node(l, b, r) => b.item + box_sum(l) + box_sum(r) }
