type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn map_bool_tree(t: Tree[Bool]) -> Tree[Int] = match t { Leaf => Leaf, Node(l, b, r) => Node(map_bool_tree(l), if b then 1 else 0, map_bool_tree(r)) }
test bool_to_int = map_bool_tree(Node(Leaf, true, Node(Leaf, false, Leaf))) == Node(Leaf, 1, Node(Leaf, 0, Leaf))

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn long_words(t: Tree[Str], n: Int) -> Int = match t { Leaf => 0, Node(l, s, r) => (if len(s) > n then 1 else 0) + long_words(l, n) + long_words(r, n) }
