type Pair[A, B] = { fst: A, snd: B }
type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn key_count(t: Tree[Pair[Int, Str]], k: Int) -> Int = match t { Leaf => 0, Node(l, p, r) => (if p.fst == k then 1 else 0) + key_count(l, k) + key_count(r, k) }
