type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn count_even_depth[T](t: Tree[T], d: Int) -> Int = match t { Leaf => 0, Node(l, _, r) => (if d % 2 == 0 then 1 else 0) + count_even_depth(l, d + 1) + count_even_depth(r, d + 1) }
test even_depth_two = count_even_depth(Node(Node(Node(Leaf, 1, Leaf), 2, Leaf), 3, Leaf), 0) == 2

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn sum_positive(t: Tree[Int]) -> Int = match t { Leaf => 0, Node(l, x, r) => (if x > 0 then x else 0) + sum_positive(l) + sum_positive(r) }
