type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn depth_matches(t: Tree[Int], d: Int) -> Int = match t { Leaf => 0, Node(l, x, r) => (if x == d then 1 else 0) + depth_matches(l, d + 1) + depth_matches(r, d + 1) }
test depth_matches_one = depth_matches(Node(Leaf, 0, Leaf), 0) == 1

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
