type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn depth_sum(t: Tree[Int]) -> Int = sum_depths(t, 0)
fn sum_depths(t: Tree[Int], d: Int) -> Int = match t { Leaf => 0, Node(l, x, r) => x * d + sum_depths(l, d + 1) + sum_depths(r, d + 1) }
test depth_sum_four = depth_sum(Node(Node(Leaf, 1, Leaf), 2, Node(Leaf, 3, Leaf))) == 4

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
