type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn map_twice[T, U, V](t: Tree[T], f: fn(T) -> U, g: fn(U) -> V) -> Tree[V] = match t { Leaf => Leaf, Node(l, x, r) => Node(map_twice(l, f, g), g(f(x)), map_twice(r, f, g)) }
