type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn is_just[T](o: Option[T]) -> Bool = match o { Some(_) => true, None => false }
fn count_map[T, U](t: Tree[T], f: fn(T) -> Option[U]) -> Int = match t { Leaf => 0, Node(l, x, r) => (if is_just(f(x)) then 1 else 0) + count_map(l, f) + count_map(r, f) }
