test first_some_hit = first_some(Node(Leaf, None, Node(Leaf, Some(4), Leaf))) == Some(4)

type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn sum_opts(t: Tree[Option[Int]]) -> Int = match t { Leaf => 0, Node(l, o, r) => val_of(o) + sum_opts(l) + sum_opts(r) }
