type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn sum_list_opts(t: Tree[List[Option[Int]]]) -> Int = match t { Leaf => 0, Node(l, xs, r) => sum_opts_list(xs) + sum_list_opts(l) + sum_list_opts(r) }
fn sum_opts_list(xs: List[Option[Int]]) -> Int = fold(xs, 0, fn(a, o) => a + val_of2(o))
