test chain_ok = match chain(Ok(10), 5) { Ok(v) => v == 15, Err(_) => false }

fn checked_byte(v: Int) -> Result[Int, Str] = if v < 0 || v > 255 then Err("byte range") else Ok(v)
fn ok_only(v: Int) -> Bool = match checked_byte(v) { Ok(_) => true, Err(_) => false }
fn both_ok(a: Int, b: Int) -> Bool = ok_only(a) && ok_only(b)
test both_ok_pair = both_ok(1, 255) && !both_ok(1, 256)

fn cmp_bytes(a: Bytes, b: Bytes) -> Int = compare(bytes_to_list(a), bytes_to_list(b))
