test less_than_pair = less_than(bytes_from([1, 2]), bytes_from([1, 3])) && !less_than(bytes_from([2]), bytes_from([1]))

fn byte_or(b: Bytes, i: Int, d: Int) -> Int = match bytes_get(b, i) { Some(v) => v, None => d }
fn argmin_at(b: Bytes, i: Int, best: Int) -> Int = if i >= bytes_len(b) then best else argmin_at(b, i + 1, if byte_or(b, i, 0) < byte_or(b, best, 0) then i else best)
fn argmin(b: Bytes) -> Int = if bytes_len(b) == 0 then -1 else argmin_at(b, 0, 0)
