fn is_leap(y: Int) -> Bool = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
fn month_offset(m: Int) -> Int = match m { 1 => 0, 2 => 31, 3 => 59, 4 => 90, 5 => 120, 6 => 151, 7 => 181, 8 => 212, 9 => 243, 10 => 273, 11 => 304, 12 => 334, _ => 0 }
fn day_of_year(y: Int, m: Int, d: Int) -> Int = month_offset(m) + d + (if m > 2 && is_leap(y) then 1 else 0)
