test march_first = day_of_year(2024, 3, 1) == 61
test december_last = day_of_year(2023, 12, 31) == 365

type Day = { y: Int, m: Int, d: Int }
fn is_leap(y: Int) -> Bool = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
fn month_len(y: Int, m: Int) -> Int = match m { 2 => if is_leap(y) then 29 else 28, 4 => 30, 6 => 30, 9 => 30, 11 => 30, _ => 31 }
fn locate(y: Int, n: Int, m: Int) -> Day = if n > month_len(y, m) then locate(y, n - month_len(y, m), m + 1) else Day { y: y, m: m, d: n }
