type Date = { y: Int, m: Int, d: Int }
type Time = { h: Int, m: Int, s: Int }
type DateTime = { day: Date, moment: Time }
fn is_leap(y: Int) -> Bool = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
fn month_offset(m: Int) -> Int = match m { 1 => 0, 2 => 31, 3 => 59, 4 => 90, 5 => 120, 6 => 151, 7 => 181, 8 => 212, 9 => 243, 10 => 273, 11 => 304, 12 => 334, _ => 0 }
fn day_of_year(y: Int, m: Int, d: Int) -> Int = month_offset(m) + d + (if m > 2 && is_leap(y) then 1 else 0)
fn days_before_year(y: Int) -> Int = 365 * (y - 1) + (y - 1) / 4 - (y - 1) / 100 + (y - 1) / 400
fn serial(dt: DateTime) -> Int = days_before_year(dt.day.y) - 719162 + day_of_year(dt.day.y, dt.day.m, dt.day.d) - 1
fn stamp(dt: DateTime) -> Int = serial(dt) * 86400 + dt.moment.h * 3600 + dt.moment.m * 60 + dt.moment.s
test noon = stamp(DateTime { day: Date { y: 2024, m: 1, d: 1 }, moment: Time { h: 12, m: 0, s: 0 } }) == 1704110400
test morning = stamp(DateTime { day: Date { y: 1970, m: 1, d: 1 }, moment: Time { h: 0, m: 0, s: 1 } }) == 1

