type Date = { y: Int, m: Int, d: Int }
fn is_leap(y: Int) -> Bool = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
fn month_len(y: Int, m: Int) -> Int = match m { 2 => if is_leap(y) then 29 else 28, 4 => 30, 6 => 30, 9 => 30, 11 => 30, _ => 31 }
fn month_offset(m: Int) -> Int = match m { 1 => 0, 2 => 31, 3 => 59, 4 => 90, 5 => 120, 6 => 151, 7 => 181, 8 => 212, 9 => 243, 10 => 273, 11 => 304, 12 => 334, _ => 0 }
fn day_of_year(y: Int, m: Int, d: Int) -> Int = month_offset(m) + d + (if m > 2 && is_leap(y) then 1 else 0)
fn days_before_year(y: Int) -> Int = 365 * (y - 1) + (y - 1) / 4 - (y - 1) / 100 + (y - 1) / 400
fn find_year(ord: Int, y: Int) -> Int = if ord > days_before_year(y) + (if is_leap(y) then 366 else 365) then find_year(ord, y + 1) else y
fn locate(y: Int, n: Int, m: Int) -> Date = if n > month_len(y, m) then locate(y, n - month_len(y, m), m + 1) else Date { y: y, m: m, d: n }
fn from_epoch(n: Int) -> Date = let ord = n + 719163 in let y = find_year(ord, 1970) in locate(y, ord - days_before_year(y), 1)
fn serial(a: Date) -> Int = days_before_year(a.y) - 719162 + day_of_year(a.y, a.m, a.d) - 1
fn midpoint(a: Date, b: Date) -> Date = from_epoch((serial(a) + serial(b)) / 2)
test center = let q = midpoint(Date { y: 2024, m: 1, d: 1 }, Date { y: 2024, m: 1, d: 3 }) in q.m == 1 && q.d == 2
test same = let q = midpoint(Date { y: 2024, m: 5, d: 5 }, Date { y: 2024, m: 5, d: 5 }) in q.d == 5

type T = { h: Int, m: Int }
fn mins(t: T) -> Int = t.h * 60 + t.m
fn wrap(n: Int) -> Int = let r = n % 1440 in if r < 0 then r + 1440 else r
fn add(t: T, n: Int) -> T = let q = wrap(mins(t) + n) in T { h: q / 60, m: q % 60 }
test late = let q = add(T { h: 23, m: 30 }, 90) in q.h == 1 && q.m == 0

