type Grid = { rows: Int, cols: Int, cells: List[Int] }
fn identity(n: Int) -> Grid = Grid { rows: n, cols: n, cells: map(range(0, n * n), fn(i) => if i / n == i % n then 1 else 0) }
fn cell(g: Grid, r: Int, c: Int) -> Int = list_at(g.cells, r * g.cols + c)
fn trace(g: Grid, i: Int) -> Int = if i >= g.rows then 0 else cell(g, i, i) + trace(g, i + 1)
test trace_identity = trace(identity(3), 0) == 3

