type Grid = { rows: Int, cols: Int, cells: List[Int] }
fn cell(g: Grid, r: Int, c: Int) -> Int = list_at(g.cells, r * g.cols + c)
fn dot(a: Grid, b: Grid, r: Int, c: Int) -> Int = fold(map(range(0, a.cols), fn(k) => cell(a, r, k) * cell(b, k, c)), 0, fn(acc, x) => acc + x)
fn mul(a: Grid, b: Grid) -> Grid = Grid { rows: a.rows, cols: b.cols, cells: map(range(0, a.rows * b.cols), fn(i) => dot(a, b, i / b.cols, i % b.cols)) }
