type Grid = { rows: Int, cols: Int, cells: List[Int] }
fn on_edge(g: Grid, i: Int) -> Bool = i / g.cols == 0 || i / g.cols == g.rows - 1 || i % g.cols == 0 || i % g.cols == g.cols - 1
fn edge_sum(g: Grid, i: Int) -> Int = if i >= len(g.cells) then 0 else (if on_edge(g, i) then list_at(g.cells, i) else 0) + edge_sum(g, i + 1)
