type Frame = { rows: Int, cols: Int, cells: List[Int] }
fn cell(f: Frame, r: Int, c: Int) -> Int = list_at(f.cells, r * f.cols + c)
fn rot(f: Frame) -> Frame = Frame { rows: f.cols, cols: f.rows, cells: rot_cells(f, 0) }
fn rot_cells(f: Frame, c: Int) -> List[Int] = if c >= f.cols then [] else map(range(0, f.rows), fn(r) => cell(f, f.rows - 1 - r, c)) ++ rot_cells(f, c + 1)
test rotate_row = let m = rot(Frame { rows: 1, cols: 3, cells: [7, 8, 9] }) in m.rows == 3 && m.cells == [7, 8, 9]

type Lattice = { rows: Int, cols: Int, cells: List[Int] }
fn cell(l: Lattice, r: Int, c: Int) -> Int = list_at(l.cells, r * l.cols + c)
fn rot(l: Lattice) -> Lattice = Lattice { rows: l.cols, cols: l.rows, cells: rot_cells(l, 0) }
fn rot_cells(l: Lattice, c: Int) -> List[Int] = if c >= l.cols then [] else map(range(0, l.rows), fn(r) => cell(l, l.rows - 1 - r, c)) ++ rot_cells(l, c + 1)
test rotate_square = let m = rot(Lattice { rows: 3, cols: 3, cells: [1, 2, 3, 4, 5, 6, 7, 8, 9] }) in m.cells == [7, 4, 1, 8, 5, 2, 9, 6, 3]

type Mesh = { rows: Int, cols: Int, cells: List[Int] }
fn cell(m: Mesh, r: Int, c: Int) -> Int = list_at(m.cells, r * m.cols + c)
fn rot(m: Mesh) -> Mesh = Mesh { rows: m.cols, cols: m.rows, cells: rot_cells(m, 0) }
fn rot_cells(m: Mesh, c: Int) -> List[Int] = if c >= m.cols then [] else map(range(0, m.rows), fn(r) => cell(m, m.rows - 1 - r, c)) ++ rot_cells(m, c + 1)
test rotate_twice = let m = rot(rot(Mesh { rows: 3, cols: 3, cells: [1, 2, 3, 4, 5, 6, 7, 8, 9] })) in m.cells == [9, 8, 7, 6, 5, 4, 3, 2, 1]

type Grid = { rows: Int, cols: Int, cells: List[Int] }
