type Grid = { rows: Int, cols: Int, cells: List[Int] }
fn row(g: Grid, r: Int) -> List[Int] = map(range(0, g.cols), fn(c) => list_at(g.cells, r * g.cols + c))
fn max_list(xs: List[Int], i: Int, best: Int) -> Int = if i >= len(xs) then best else max_list(xs, i + 1, (if list_at(xs, i) > best then list_at(xs, i) else best))
fn grid_max(g: Grid, r: Int, best: Int) -> Int = if r >= g.rows then best else grid_max(g, r + 1, max_list(row(g, r), 0, best))
test max_value = grid_max(Grid { rows: 2, cols: 3, cells: [1, 9, 3, 4, 5, 6] }, 0, -1000) == 9

