type Mask = { w: Int, h: Int, bits: List[Bool] }
fn bit(m: Mask, r: Int, c: Int) -> Bool = list_at(m.bits, r * m.w + c)
fn flipped(m: Mask, r: Int, c: Int) -> Mask = Mask { w: m.w, h: m.h, bits: map(range(0, len(m.bits)), fn(i) => if i == r * m.w + c then !list_at(m.bits, i) else list_at(m.bits, i)) }
test flip_twice = let m = Mask { w: 2, h: 2, bits: [true, false, false, true] } in bit(flipped(flipped(m, 0, 1), 0, 1), 0, 1) == false

