type Cell = { row: Int, col: Int, value: Int }
type Field = { cells: List[Cell] }
fn value_at(f: Field, r: Int, c: Int, i: Int) -> Option[Int] = if i >= len(f.cells) then None else let k = list_at(f.cells, i) in if k.row == r && k.col == c then Some(k.value) else value_at(f, r, c, i + 1)
