type Sparse = { n: Int, vals: Map[Int, Int] }
fn at(s: Sparse, r: Int, c: Int) -> Int = match map_get(s.vals, r * s.n + c) { Some(v) => v, None => 0 }
fn put(s: Sparse, r: Int, c: Int, v: Int) -> Sparse = Sparse { n: s.n, vals: map_put(s.vals, r * s.n + c, v) }
test sparse_roundtrip = let s = put(Sparse { n: 3, vals: map_new() }, 1, 2, 7) in at(s, 1, 2) == 7 && at(s, 0, 0) == 0

