fn pick(xs: List[Int], i: Int) -> Int = if i < 0 || i >= len(xs) then 0 else list_at(xs, i)
fn next_row(prev: List[Int], i: Int) -> List[Int] = if i > len(prev) then [] else [pick(prev, i - 1) + pick(prev, i)] ++ next_row(prev, i + 1)
fn pascal(n: Int, rows: List[List[Int]], i: Int) -> List[List[Int]] = if i >= n then rows else pascal(n, rows ++ [if i == 0 then [1] else next_row(list_at(rows, i - 1), 0)], i + 1)
