fn cell(g: Grid, r: Int, c: Int) -> Int = list_at(g.cells, r * g.cols + c)
fn cross(g: Grid, r: Int, c: Int) -> Int = cell(g, r, c) + (if r > 0 then cell(g, r - 1, c) else 0) + (if r + 1 < g.rows then cell(g, r + 1, c) else 0) + (if c > 0 then cell(g, r, c - 1) else 0) + (if c + 1 < g.cols then cell(g, r, c + 1) else 0)
