type Lattice = { rows: Int, cols: Int, cells: List[Int] }
fn row(l: Lattice, r: Int) -> List[Int] = map(range(0, l.cols), fn(c) => list_at(l.cells, r * l.cols + c))
fn row_total(l: Lattice, r: Int) -> Int = fold(row(l, r), 0, fn(a, x) => a + x)
fn count_above(l: Lattice, k: Int, r: Int) -> Int = if r >= l.rows then 0 else (if row_total(l, r) > k then 1 else 0) + count_above(l, k, r + 1)
test above_fourteen = count_above(Lattice { rows: 3, cols: 3, cells: [1, 2, 3, 4, 5, 6, 7, 8, 9] }, 14, 0) == 2

type Panel = { rows: Int, cols: Int, cells: List[Int] }
fn row(p: Panel, r: Int) -> List[Int] = map(range(0, p.cols), fn(c) => list_at(p.cells, r * p.cols + c))
fn row_total(p: Panel, r: Int) -> Int = fold(row(p, r), 0, fn(a, x) => a + x)
fn count_above(p: Panel, k: Int, r: Int) -> Int = if r >= p.rows then 0 else (if row_total(p, r) > k then 1 else 0) + count_above(p, k, r + 1)
test above_exact = count_above(Panel { rows: 1, cols: 3, cells: [1, 2, 3] }, 6, 0) == 0

type Sheet = { rows: Int, cols: Int, cells: List[Int] }
fn row(s: Sheet, r: Int) -> List[Int] = map(range(0, s.cols), fn(c) => list_at(s.cells, r * s.cols + c))
fn row_total(s: Sheet, r: Int) -> Int = fold(row(s, r), 0, fn(a, x) => a + x)
fn count_above(s: Sheet, k: Int, r: Int) -> Int = if r >= s.rows then 0 else (if row_total(s, r) > k then 1 else 0) + count_above(s, k, r + 1)
test above_two = count_above(Sheet { rows: 2, cols: 2, cells: [1, 2, 3, 4] }, 2, 0) == 2

type Grid = { rows: Int, cols: Int, cells: List[Int] }
fn weighted(g: Grid) -> Int = fold(map(range(0, len(g.cells)), fn(i) => i * list_at(g.cells, i)), 0, fn(a, x) => a + x)
test weighted_row = weighted(Grid { rows: 1, cols: 3, cells: [1, 2, 3] }) == 8

type Matrix = { rows: Int, cols: Int, cells: List[Int] }
fn sum_squares(m: Matrix) -> Int = fold(map(m.cells, fn(x) => x * x), 0, fn(a, x) => a + x)
test squares_row = sum_squares(Matrix { rows: 1, cols: 3, cells: [1, 2, 3] }) == 14

type Table = { rows: Int, cols: Int, cells: List[Int] }
fn sum_abs(t: Table) -> Int = fold(map(t.cells, fn(x) => if x < 0 then -x else x), 0, fn(a, x) => a + x)
test abs_signed = sum_abs(Table { rows: 1, cols: 3, cells: [-1, 2, -3] }) == 6

type Frame = { rows: Int, cols: Int, cells: List[Int] }
fn evens(f: Frame) -> Int = fold(map(f.cells, fn(x) => if x % 2 == 0 then 1 else 0), 0, fn(a, x) => a + x)
test even_count = evens(Frame { rows: 2, cols: 2, cells: [1, 2, 4, 6] }) == 3

type Grid = { rows: Int, cols: Int, cells: List[Int] }
fn dot(a: Grid, b: Grid) -> Int = fold(map(range(0, len(a.cells)), fn(i) => list_at(a.cells, i) * list_at(b.cells, i)), 0, fn(acc, x) => acc + x)
test dot_three = dot(Grid { rows: 1, cols: 3, cells: [1, 2, 3] }, Grid { rows: 1, cols: 3, cells: [4, 5, 6] }) == 32

type Point = { x: Int, y: Int }
fn norm1(p: Point) -> Int = (if p.x < 0 then -p.x else p.x) + (if p.y < 0 then -p.y else p.y)
fn shift(p: Point, d: Int) -> Point = Point { x: p.x + d, y: p.y + d }
test norm1_neg = norm1(Point { x: -3, y: 4 }) == 7
test shift_ok = shift(Point { x: 1, y: 2 }, 3) == Point { x: 4, y: 5 }

type Vec2 = { a: Int, b: Int }
fn dot(u: Vec2, v: Vec2) -> Int = u.a * v.a + u.b * v.b
