type Cell = { row: Int, col: Int }
fn up(c: Cell) -> Cell = Cell { row: c.row - 1, col: c.col }
fn manhattan(a: Cell, b: Cell) -> Int = (if a.row > b.row then a.row - b.row else b.row - a.row) + (if a.col > b.col then a.col - b.col else b.col - a.col)
test up_ok = up(Cell { row: 5, col: 2 }) == Cell { row: 4, col: 2 }
test dist_ok = manhattan(Cell { row: 0, col: 0 }, Cell { row: 3, col: 4 }) == 7

type Spot = { px: Int, py: Int }
