type Json = JNull | JBool(Bool) | JNum(Int) | JStr(Str) | JArr(List[Json]) | JObj(List[Field])
type Field = { key: Str, value: Json }
fn depth(j: Json) -> Int = match j { JNull => 0, JBool(_) => 1, JNum(_) => 1, JStr(_) => 1, JArr(xs) => fold(xs, 0, fn(a, x) => if depth(x) > a then depth(x) else a) + 1, JObj(fs) => fold(fs, 0, fn(a, f) => if depth(f.value) > a then depth(f.value) else a) + 1 }
test depth_flat = depth(JObj([Field { key: "a", value: JNum(1) }])) == 2
test depth_null = depth(JNull) == 0

type Value = VNull | VNum(Int) | VText(Str) | VList(List[Value])
fn count(v: Value) -> Int = match v { VNull => 0, VNum(_) => 1, VText(_) => 1, VList(xs) => fold(xs, 0, fn(a, x) => a + count(x)) }
test count_ok = count(VList([VNum(1), VText("a"), VNull])) == 2

type Value = VNull | VNum(Int) | VText(Str) | VList(List[Value])
fn size(v: Value) -> Int = match v { VNull => 1, VNum(_) => 8, VText(s) => len(s), VList(xs) => fold(xs, 0, fn(a, x) => a + size(x)) }
test size_list = size(VList([VText("ab"), VNum(3)])) == 10

type Json = JNull | JNum(Int) | JObj(List[Field])
type Field = { key: Str, value: Json }
fn fields(j: Json) -> Int = match j { JObj(fs) => len(fs), JNull => 0, JNum(_) => 0 }
test fields_two = fields(JObj([Field { key: "a", value: JNull }, Field { key: "b", value: JNum(1) }])) == 2

type Json = JNull | JNum(Int) | JArr(List[Json])
fn sum(j: Json) -> Int = match j { JNull => 0, JNum(n) => n, JArr(xs) => fold(xs, 0, fn(a, x) => a + sum(x)) }
test sum_nested = sum(JArr([JNum(1), JArr([JNum(2), JNum(3)])])) == 6

type Json = JNull | JBool(Bool) | JNum(Int) | JStr(Str) | JArr(List[Json])
fn kind(j: Json) -> Str = match j { JNull => "null", JBool(_) => "bool", JNum(_) => "num", JStr(_) => "str", JArr(_) => "arr" }
test kind_arr = kind(JArr([JNull])) == "arr"

type Json = JNull | JStr(Str) | JArr(List[Json])
fn strings(j: Json) -> Int = match j { JNull => 0, JStr(_) => 1, JArr(xs) => fold(xs, 0, fn(a, x) => a + strings(x)) }
test strings_two = strings(JArr([JStr("a"), JArr([JStr("b")]), JNull])) == 2

type Json = JNull | JNum(Int) | JArr(List[Json])
fn nums(j: Json) -> List[Int] = match j { JNull => range(0, 0), JNum(n) => [n], JArr(xs) => fold(xs, range(0, 0), fn(a, x) => a ++ nums(x)) }
test nums_ok = nums(JArr([JNum(1), JNum(2)])) == [1, 2]

type Json = JNull | JNum(Int) | JArr(List[Json])
fn depth(j: Json) -> Int = match j { JNull => 1, JNum(_) => 1, JArr(xs) => 1 + fold(xs, 0, fn(a, x) => if depth(x) > a then depth(x) else a) }
test depth_two = depth(JArr([JArr([JNum(0)])])) == 3

type Json = JNull | JObj(List[Field])
type Field = { key: Str, value: Json }
fn has_key(j: Json, k: Str) -> Bool = match j { JNull => false, JObj(fs) => len(filter(fs, fn(f) => f.key == k)) > 0 }
test key_yes = has_key(JObj([Field { key: "a", value: JNull }]), "a")

type Json = JNull | JObj(List[Field])
type Field = { key: Str, value: Json }
fn total_fields(j: Json) -> Int = match j { JNull => 0, JObj(fs) => len(fs) + fold(fs, 0, fn(a, f) => a + total_fields(f.value)) }
test total_ok = total_fields(JObj([Field { key: "a", value: JObj([Field { key: "b", value: JNull }]) }])) == 2

type Json = JNull | JNum(Int) | JObj(List[Field])
type Field = { key: Str, value: Json }
fn field_at(fs: List[Field], i: Int, k: Str) -> Option[Json] = if i >= len(fs) then None else match get(fs, i) { Some(f) => if f.key == k then Some(f.value) else field_at(fs, i + 1, k), None => None }
fn get_field(j: Json, k: Str) -> Option[Json] = match j { JObj(fs) => field_at(fs, 0, k), _ => None }
test get_num = get_field(JObj([Field { key: "n", value: JNum(5) }]), "n") == Some(JNum(5))

type Json = JNull | JNum(Int) | JObj(List[Field])
type Field = { key: Str, value: Json }
fn find(fs: List[Field], i: Int, k: Str) -> Option[Json] = if i >= len(fs) then None else match get(fs, i) { Some(f) => if f.key == k then Some(f.value) else find(fs, i + 1, k), None => None }
fn num_or(j: Json, k: Str, d: Int) -> Int = match j { JObj(fs) => match find(fs, 0, k) { Some(JNum(n)) => n, _ => d }, _ => d }
test num_ok = num_or(JObj([Field { key: "n", value: JNum(7) }]), "n", 0) == 7
test num_default = num_or(JNull, "n", 5) == 5

type J = JNull | JObj(List[F])
type F = { k: Str, v: J }
fn scan(fs: List[F], i: Int, k: Str) -> Bool = if i >= len(fs) then false else match get(fs, i) { Some(f) => if f.k == k then true else scan(fs, i + 1, k), None => false }
fn has(j: J, k: Str) -> Bool = match j { JObj(fs) => scan(fs, 0, k), JNull => false }
test has_yes = has(JObj([F { k: "a", v: JNull }]), "a")
test has_no = !has(JNull, "a")

