type Json = JNull | JStr(Str) | JObj(List[Field])
type Field = { key: Str, value: Json }
fn first_key(j: Json) -> Option[Str] = match j { JObj(fs) => match get(fs, 0) { Some(f) => Some(f.key), None => None }, _ => None }
test first_ok = first_key(JObj([Field { key: "id", value: JStr("x") }])) == Some("id")

type Json = JNull | JNum(Int) | JObj(List[Field])
type Field = { key: Str, value: Json }
fn add_field(j: Json, k: Str, v: Json) -> Json = match j { JObj(fs) => JObj(push(fs, Field { key: k, value: v })), _ => JObj([Field { key: k, value: v }]) }
test add_ok = match add_field(JNull, "n", JNum(1)) { JObj(fs) => len(fs) == 1, _ => false }

type Json = JNull | JNum(Int) | JObj(List[Field])
