fn next_name(q: List[Str]) -> List[Str] =
  if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Str], i: Int) => push(a, list_at(q, i)))
test front_name_test = front_name(enq_name(enq_name([], "ada"), "bob")) == "ada"
test next_name_test = next_name(["ada", "bob"]) == ["bob"]

fn make_queue(n: Int) -> List[Int] = range(0, n)
fn front_or(q: List[Int], d: Int) -> Int = if len(q) == 0 then d else list_at(q, 0)
test make_test = make_queue(4) == [0, 1, 2, 3]
test front_range = front_or(make_queue(3), -1) == 0

fn queue_sum(q: List[Int]) -> Int = fold(q, 0, fn(a: Int, x: Int) => a + x)
fn queue_len(q: List[Int]) -> Int = len(q)
test sum_test = queue_sum([1, 2, 3, 4]) == 10
test empty_sum = queue_sum([]) == 0
test len_q = queue_len([1]) == 1

fn q_has(q: List[Int], x: Int) -> Bool = fold(q, false, fn(a: Bool, y: Int) => a || y == x)
fn q_count(q: List[Int], x: Int) -> Int = fold(q, 0, fn(a: Int, y: Int) => if y == x then a + 1 else a)
test has_yes = q_has([5, 6, 7], 6)
test has_no = !q_has([5, 6, 7], 8)
test count_test = q_count([1, 2, 1, 1], 1) == 3

fn q_cat(a: List[Int], b: List[Int]) -> List[Int] = concat(a, b)
fn q_first(a: List[Int], b: List[Int]) -> Option[Int] = get(concat(a, b), 0)
test cat_test = q_cat([1, 2], [3]) == [1, 2, 3]
test first_merge = q_first([], [4, 5]) == Some(4)

fn q_rev(q: List[Int]) -> List[Int] = reverse(q)
fn q_last(q: List[Int]) -> Option[Int] = get(q, len(q) - 1)
test rev_test = q_rev([1, 2, 3]) == [3, 2, 1]
test last_test = q_last(q_rev([1, 2, 3])) == Some(1)

fn take_q(q: List[Int], n: Int) -> List[Int] =
  let s = if n < 0 then 0 else n in
  fold(range(0, s), [], fn(a: List[Int], i: Int) => if i < len(q) then push(a, list_at(q, i)) else a)
fn drop_q(q: List[Int], n: Int) -> List[Int] =
  let s = if n < 0 then 0 else n in
  if s >= len(q) then [] else fold(range(s, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
test take_q_test = take_q([1, 2, 3, 4], 2) == [1, 2]
test drop_q_test = drop_q([1, 2, 3, 4], 2) == [3, 4]

type Queue = { front: List[Int], back: List[Int] }
fn q_empty() -> Queue = Queue { front: [], back: [] }
fn q_norm(q: Queue) -> Queue = if len(q.front) == 0 then Queue { front: reverse(q.back), back: [] } else q
fn q_add(q: Queue, x: Int) -> Queue = Queue { front: q.front, back: push(q.back, x) }
fn q_peek(q: Queue) -> Option[Int] = let n = q_norm(q) in get(n.front, len(n.front) - 1)
fn q_view(q: Queue) -> List[Int] = let n = q_norm(q) in n.front
test q_peek_test = q_peek(q_add(q_add(q_empty(), 1), 2)) == Some(1)
test q_view_test = q_view(q_add(q_empty(), 5)) == [5]

type QAB = { left: List[Int], right: List[Int] }
fn qab_new() -> QAB = QAB { left: [], right: [] }
fn qab_shift(q: QAB) -> QAB = if len(q.left) == 0 then QAB { left: reverse(q.right), right: [] } else q
fn qab_enq(q: QAB, x: Int) -> QAB = QAB { left: q.left, right: push(q.right, x) }
fn qab_front(q: QAB) -> Option[Int] = let s = qab_shift(q) in get(s.left, len(s.left) - 1)
test qab_front_test = qab_front(qab_enq(qab_new(), 11)) == Some(11)

type TwoStack = { inb: List[Int], outb: List[Int] }
fn ts_new() -> TwoStack = TwoStack { inb: [], outb: [] }
fn ts_norm(t: TwoStack) -> TwoStack = if len(t.outb) == 0 then TwoStack { inb: [], outb: reverse(t.inb) } else t
fn ts_push(t: TwoStack, x: Int) -> TwoStack = TwoStack { inb: push(t.inb, x), outb: t.outb }
fn ts_size(t: TwoStack) -> Int = len(t.inb) + len(t.outb)
fn ts_front(t: TwoStack) -> Option[Int] = let n = ts_norm(t) in get(n.outb, len(n.outb) - 1)
test ts_size_test = ts_size(ts_push(ts_push(ts_new(), 1), 2)) == 2
test ts_front_test = ts_front(ts_push(ts_push(ts_new(), 1), 2)) == Some(1)

type BQ = { f: List[Int], b: List[Int] }
fn bq_norm(q: BQ) -> BQ = if len(q.f) == 0 then BQ { f: reverse(q.b), b: [] } else q
fn bq_add(q: BQ, x: Int) -> BQ = BQ { f: q.f, b: push(q.b, x) }
fn bq_drop(q: BQ) -> BQ =
  let n = bq_norm(q) in
  if len(n.f) == 0 then n else BQ { f: drop_last(n.f), b: n.b }
fn drop_last(xs: List[Int]) -> List[Int] = if len(xs) == 0 then [] else take_n(xs, len(xs) - 1)
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
fn bq_front(q: BQ) -> Option[Int] = let n = bq_norm(q) in get(n.f, len(n.f) - 1)
test bq_drop_test = bq_front(bq_drop(bq_add(bq_add(BQ { f: [], b: [] }, 1), 2))) == Some(2)

type MQ = { items: List[Int], top: Option[Int] }
fn mq_add(q: MQ, x: Int) -> MQ =
  MQ { items: push(q.items, x), top: match q.top { Some(m) => Some(if x > m then x else m), None => Some(x) } }
fn mq_max(q: MQ) -> Option[Int] = q.top
test mq_max_test = mq_max(mq_add(mq_add(MQ { items: [], top: None }, 3), 8)) == Some(8)

type Job = { id: Int, cost: Int }
fn jq_push(q: List[Job], j: Job) -> List[Job] = push(q, j)
fn jq_total(q: List[Job]) -> Int = fold(q, 0, fn(a: Int, j: Job) => a + j.cost)
fn jq_first(q: List[Job]) -> Option[Job] = get(q, 0)
