test jq_first_test = jq_first(jq_push([], Job { id: 7, cost: 2 })) == Some(Job { id: 7, cost: 2 })

type Entry = { key: Int, name: Str }
fn eq_push(q: List[Entry], e: Entry) -> List[Entry] = push(q, e)
