type Front = { a: List[Int], b: List[Int] }
fn fq_norm(q: Front) -> Front = if len(q.a) == 0 then Front { a: reverse(q.b), b: [] } else q
fn fq_push(q: Front, x: Int) -> Front = Front { a: q.a, b: push(q.b, x) }
fn fq_depth(q: Front) -> Int = len(q.a) + len(q.b)
