type DQ = { head: Option[Int], rest: List[Int] }
fn dq_take(q: List[Int]) -> DQ =
  if len(q) == 0 then DQ { head: None, rest: [] }
  else DQ { head: Some(list_at(q, 0)), rest: drop_head(q) }
fn drop_head(q: List[Int]) -> List[Int] =
  if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
test dq_test = match dq_take([8, 9]) { DQ { head: h, rest: r } => h == Some(8) && r == [9] }

type QWrap = { items: List[Int] }
fn q3_push(q: QWrap, x: Int) -> QWrap = QWrap { items: push(q.items, x) }
fn q3_size(q: QWrap) -> Int = len(q.items)
fn q3_ok(q: QWrap) -> Bool = q3_size(q) == len(q.items)
test q3_test = q3_size(q3_push(q3_push(QWrap { items: [] }, 1), 2)) == 2 && q3_ok(QWrap { items: [1] })

type Stack = { items: List[Int], depth: Int }
fn st_new() -> Stack = Stack { items: [], depth: 0 }
fn st_push(s: Stack, x: Int) -> Stack = Stack { items: push(s.items, x), depth: s.depth + 1 }
fn st_pop(s: Stack) -> Stack = if s.depth == 0 then s else Stack { items: take_n(s.items, s.depth - 1), depth: s.depth - 1 }
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
fn st_depth(s: Stack) -> Int = s.depth
test st_pop_test = st_depth(st_pop(st_push(st_new(), 5))) == 0
test st_push_test = st_depth(st_push(st_new(), 5)) == 1

type StackStr = { data: List[Str], n: Int }
fn s2_empty() -> StackStr = StackStr { data: [], n: 0 }
fn s2_push(s: StackStr, w: Str) -> StackStr = StackStr { data: push(s.data, w), n: s.n + 1 }
fn s2_top(s: StackStr) -> Str = if s.n == 0 then "" else match get(s.data, s.n - 1) { Some(w) => w, None => "" }
test s2_test = s2_top(s2_push(s2_push(s2_empty(), "x"), "y")) == "y"

