fn q_swap_front(q: List[Str]) -> List[Str] =
  if len(q) < 2 then q
  else concat([list_at(q, 1), list_at(q, 0)], drop_two(q))
fn drop_two(q: List[Str]) -> List[Str] = fold(range(2, len(q)), [], fn(a: List[Str], i: Int) => push(a, list_at(q, i)))
test swap_test = q_swap_front(["a", "b", "c"]) == ["b", "a", "c"]

fn count_char(xs: List[Str], c: Str) -> Int = fold(xs, 0, fn(a: Int, s: Str) => if s == c then a + 1 else a)
fn push_char(xs: List[Str], c: Str) -> List[Str] = push(xs, c)
