fn push_s(xs: List[Str], s: Str) -> List[Str] = push(xs, s)
test filter_test = filter_stack(push_s(push_s([], "apple"), "banana"), "a") == ["apple"]

fn q_rev_str(q: List[Str]) -> List[Str] = reverse(q)
fn q_tail_str(q: List[Str]) -> List[Str] = if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Str], i: Int) => push(a, list_at(q, i)))
test rev_str_test = q_rev_str(["a", "b", "c"]) == ["c", "b", "a"]
test tail_str_test = q_tail_str(["a", "b", "c"]) == ["b", "c"]

fn b_push(xs: List[Bool], b: Bool) -> List[Bool] = push(xs, b)
fn b_top(xs: List[Bool]) -> Option[Bool] = get(xs, len(xs) - 1)
fn b_any(xs: List[Bool]) -> Bool = fold(xs, false, fn(a: Bool, b: Bool) => a || b)
test any_test = b_any(b_push(b_push([], false), true))
test top_test = b_top(b_push([], false)) == Some(false)

fn all_true(xs: List[Bool]) -> Bool = fold(xs, true, fn(a: Bool, b: Bool) => a && b)
fn push_flag(xs: List[Bool], b: Bool) -> List[Bool] = push(xs, b)
test all_test = all_true(push_flag(push_flag([], true), true)) && !all_true(push_flag(push_flag([], true), false))

fn push_opt(xs: List[Option[Int]], x: Option[Int]) -> List[Option[Int]] = push(xs, x)
fn top_opt(xs: List[Option[Int]]) -> Option[Option[Int]] = get(xs, len(xs) - 1)
fn present(xs: List[Option[Int]]) -> Int = fold(xs, 0, fn(a: Int, o: Option[Int]) => match o { Some(_) => a + 1, None => a })
test present_test = present(push_opt(push_opt([], Some(1)), None)) == 1
test top_opt_test = top_opt(push_opt([], Some(2))) == Some(Some(2))

fn push_res(xs: List[Result[Int, Str]], x: Result[Int, Str]) -> List[Result[Int, Str]] = push(xs, x)
fn ok_count(xs: List[Result[Int, Str]]) -> Int = fold(xs, 0, fn(a: Int, x: Result[Int, Str]) => match x { Ok(_) => a + 1, Err(_) => a })
test ok_test = ok_count(push_res(push_res([], Ok(1)), Err("bad"))) == 1

fn push_list(xss: List[List[Int]], xs: List[Int]) -> List[List[Int]] = push(xss, xs)
fn total(xss: List[List[Int]]) -> Int = fold(xss, 0, fn(a: Int, xs: List[Int]) => a + len(xs))
test total_test = total(push_list(push_list([], [1, 2]), [3])) == 3

fn flat_q(xss: List[List[Int]], i: Int, acc: List[Int]) -> List[Int] =
  if i >= len(xss) then acc else flat_q(xss, i + 1, concat(acc, list_at(xss, i)))
test flat_q_test = flat_q([[4], [5, 6]], 0, []) == [4, 5, 6]

fn stack_of_queues(qs: List[List[Int]], i: Int, acc: Int) -> Int =
  if i >= len(qs) then acc else stack_of_queues(qs, i + 1, acc + len(list_at(qs, i)))
test soq_test = stack_of_queues([[1], [2, 3], []], 0, 0) == 3

type Op = Add | Mul | Neg
fn m_take(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
fn m_apply(s: List[Int], o: Op) -> List[Int] =
  match o {
    Add => if len(s) < 2 then s else push(m_take(s, len(s) - 2), list_at(s, len(s) - 1) + list_at(s, len(s) - 2)),
    Mul => if len(s) < 2 then s else push(m_take(s, len(s) - 2), list_at(s, len(s) - 1) * list_at(s, len(s) - 2)),
    Neg => if len(s) == 0 then s else push(m_take(s, len(s) - 1), -list_at(s, len(s) - 1))
  }
test add_test = m_apply(m_apply([2, 3], Add), Neg) == [-5]

type Cmd = Push(Int) | Pop | Dup
fn c_apply(s: List[Int], c: Cmd) -> List[Int] =
  match c {
    Push(x) => push(s, x),
    Dup => if len(s) == 0 then s else push(s, list_at(s, len(s) - 1)),
    Pop => if len(s) == 0 then s else take_n(s, len(s) - 1)
  }
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
fn c_run(cs: List[Cmd], s: List[Int]) -> List[Int] = fold(cs, s, fn(a: List[Int], c: Cmd) => c_apply(a, c))
test cmd_test = c_run([Push(4), Dup, Push(2)], []) == [4, 4, 2]

type Move = Enq(Int) | Deq
fn mv_apply(q: List[Int], m: Move) -> List[Int] =
  match m {
    Enq(x) => push(q, x),
    Deq => if len(q) == 0 then q else drop_head(q)
  }
fn drop_head(q: List[Int]) -> List[Int] = if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
fn mv_run(ms: List[Move], q: List[Int]) -> List[Int] = fold(ms, q, fn(a: List[Int], m: Move) => mv_apply(a, m))
test mv_test = mv_run([Enq(1), Enq(2), Deq], []) == [2]

type Act = Inc | Dec | Clear
fn a_apply(s: List[Int], a: Act) -> List[Int] =
  match a {
    Inc => if len(s) == 0 then s else push(take_n(s, len(s) - 1), list_at(s, len(s) - 1) + 1),
    Dec => if len(s) == 0 then s else push(take_n(s, len(s) - 1), list_at(s, len(s) - 1) - 1),
    Clear => []
  }
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
test act_test = a_apply(a_apply([5], Inc), Dec) == [5]

type Tok = Num(Int) | Plus | Times
fn t_apply(s: List[Int], t: Tok) -> List[Int] =
  match t {
    Num(n) => push(s, n),
    Plus => if len(s) < 2 then s else push(take_n(s, len(s) - 2), list_at(s, len(s) - 2) + list_at(s, len(s) - 1)),
    Times => if len(s) < 2 then s else push(take_n(s, len(s) - 2), list_at(s, len(s) - 2) * list_at(s, len(s) - 1))
  }
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
fn eval(ts: List[Tok], s: List[Int]) -> List[Int] = fold(ts, s, fn(a: List[Int], t: Tok) => t_apply(a, t))
test rpn_test = eval([Num(3), Num(4), Plus, Num(2), Times], []) == [14]

type SOP = PS(Int) | SW
fn sop_apply(s: List[Int], o: SOP) -> List[Int] =
  match o {
    PS(x) => push(s, x),
    SW => if len(s) < 2 then s else push(push(take_n(s, len(s) - 2), list_at(s, len(s) - 1)), list_at(s, len(s) - 2))
  }
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
fn sop_run(os: List[SOP], s: List[Int]) -> List[Int] = fold(os, s, fn(a: List[Int], o: SOP) => sop_apply(a, o))
test sw_test = sop_run([PS(1), PS(2), SW], []) == [2, 1]

type Ins = Put(Int) | Drop
fn ins_apply(s: List[Int], i: Ins) -> List[Int] =
  match i {
    Put(x) => push(s, x),
    Drop => if len(s) == 0 then s else take_n(s, len(s) - 1)
  }
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
test ins_test = ins_apply(ins_apply([], Put(3)), Drop) == []

type Duo = { a: Int, b: Int }
fn pair_push(ps: List[Duo], p: Duo) -> List[Duo] = push(ps, p)
fn pair_sum(ps: List[Duo]) -> Int = fold(ps, 0, fn(acc: Int, p: Duo) => acc + p.a + p.b)
test pair_sum_test = pair_sum(pair_push(pair_push([], Duo { a: 1, b: 2 }), Duo { a: 3, b: 4 })) == 10

type PairRec = { left: Int, right: Int }
fn d_push(ps: List[PairRec], p: PairRec) -> List[PairRec] = push(ps, p)
