fn insert_sorted(q: List[Int], x: Int, i: Int, out: List[Int]) -> List[Int] =
  if i >= len(q) then push(out, x)
  else if x <= list_at(q, i) then concat(push(out, x), drop_left(q, i))
  else insert_sorted(q, x, i + 1, push(out, list_at(q, i)))
fn drop_left(q: List[Int], i: Int) -> List[Int] =
  if i >= len(q) then [] else fold(range(i, len(q)), [], fn(a: List[Int], j: Int) => push(a, list_at(q, j)))
test insert_test = insert_sorted([1, 3, 4], 2, 0, []) == [1, 2, 3, 4]
test insert_end = insert_sorted([1, 2], 9, 0, []) == [1, 2, 9]

