fn bounded_add(q: List[Int], x: Int, cap: Int) -> List[Int] =
  if len(q) < cap then push(q, x)
  else if len(q) == 0 then q
  else push(drop_head(q), x)
fn drop_head(q: List[Int]) -> List[Int] =
  if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
test bound_ok = bounded_add(bounded_add([], 1, 2), 2, 2) == [1, 2]
test bound_drop = bounded_add(bounded_add(bounded_add([], 1, 2), 2, 2), 3, 2) == [2, 3]

fn ring_add(q: List[Int], x: Int, cap: Int) -> List[Int] =
  if len(q) < cap then push(q, x) else push(ring_tail(q), x)
fn ring_tail(q: List[Int]) -> List[Int] = if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
test ring_test = ring_add(ring_add(ring_add([], 1, 2), 2, 2), 3, 2) == [2, 3]

fn keep_last(q: List[Int], x: Int, k: Int) -> List[Int] = keep_tail(push(q, x), k)
fn keep_tail(q: List[Int], k: Int) -> List[Int] =
  if len(q) <= k then q else keep_tail(drop_head(q), k)
fn drop_head(q: List[Int]) -> List[Int] = if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
test keep_test = keep_last(keep_last(keep_last([], 1, 2), 2, 2), 3, 2) == [2, 3]

fn shift_left(q: List[Int], n: Int) -> List[Int] =
  if n <= 0 || len(q) == 0 then q else shift_left(push(drop_head(q), list_at(q, 0)), n - 1)
fn drop_head(q: List[Int]) -> List[Int] = if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
test shift_test = shift_left([1, 2, 3], 1) == [2, 3, 1]

fn shift_right(q: List[Int], n: Int) -> List[Int] =
  if n <= 0 || len(q) == 0 then q
  else shift_right(concat([list_at(q, len(q) - 1)], take_n(q, len(q) - 1)), n - 1)
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
test shift_right_test = shift_right([1, 2, 3], 1) == [3, 1, 2]

fn buf_push(buf: List[Int], x: Int, cap: Int) -> List[Int] =
  let next = push(buf, x) in
  if len(next) > cap then drop_head(next) else next
fn drop_head(buf: List[Int]) -> List[Int] = if len(buf) == 0 then [] else fold(range(1, len(buf)), [], fn(a: List[Int], i: Int) => push(a, list_at(buf, i)))
test buf_test = buf_push(buf_push([], 1, 1), 2, 1) == [2]

fn window_sum(q: List[Int]) -> Int = fold(q, 0, fn(a: Int, x: Int) => a + x)
fn add_window(q: List[Int], x: Int, k: Int) -> List[Int] = keep_tail(push(q, x), k)
fn keep_tail(q: List[Int], k: Int) -> List[Int] =
  if len(q) <= k then q else keep_tail(drop_head(q), k)
fn drop_head(q: List[Int]) -> List[Int] = if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
