fn drop_n(q: List[Int], n: Int) -> List[Int] =
  if n <= 0 then q else if len(q) == 0 then [] else drop_n(drop_head(q), n - 1)
fn drop_head(q: List[Int]) -> List[Int] = if len(q) == 0 then [] else fold(range(1, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
test drop_n_test = drop_n([1, 2, 3, 4], 2) == [3, 4]

fn swap_top(xs: List[Int]) -> List[Int] =
  if len(xs) < 2 then xs
  else push(push(take_n(xs, len(xs) - 2), list_at(xs, len(xs) - 1)), list_at(xs, len(xs) - 2))
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
test swap_top_test = swap_top([1, 2, 3]) == [1, 3, 2]

fn rot_top(xs: List[Int]) -> List[Int] =
  if len(xs) == 0 then [] else concat([list_at(xs, len(xs) - 1)], take_n(xs, len(xs) - 1))
