  else rotate_k(push(drop_head(xs), list_at(xs, 0)), k - 1)
fn drop_head(xs: List[Int]) -> List[Int] = if len(xs) == 0 then [] else fold(range(1, len(xs)), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
