fn weave(a: List[Int], b: List[Int], i: Int, acc: List[Int]) -> List[Int] =
  if i >= len(a) && i >= len(b) then acc
  else if i < len(a) && i < len(b) then weave(a, b, i + 1, push(push(acc, list_at(a, i)), list_at(b, i)))
  else if i < len(a) then weave(a, b, i + 1, push(acc, list_at(a, i)))
  else weave(a, b, i + 1, push(acc, list_at(b, i)))
test weave_test = weave([1, 3], [2, 4, 5], 0, []) == [1, 2, 3, 4, 5]

