type Split = { left: List[Int], right: List[Int] }
fn split_q(q: List[Int], i: Int, s: Split) -> Split =
  if i >= len(q) then s
  else if i % 2 == 0 then split_q(q, i + 1, Split { left: push(s.left, list_at(q, i)), right: s.right })
  else split_q(q, i + 1, Split { left: s.left, right: push(s.right, list_at(q, i)) })
fn split_start(q: List[Int]) -> Split = split_q(q, 0, Split { left: [], right: [] })
fn split_left(q: List[Int]) -> List[Int] = match split_start(q) { Split { left: l, right: r } => l }
test split_test = split_left([1, 2, 3, 4]) == [1, 3]

fn has(xs: List[Int], x: Int) -> Bool = fold(xs, false, fn(a: Bool, y: Int) => a || y == x)
fn dedupe(q: List[Int], acc: List[Int], i: Int) -> List[Int] =
  if i >= len(q) then acc
  else if has(acc, list_at(q, i)) then dedupe(q, acc, i + 1)
  else dedupe(q, push(acc, list_at(q, i)), i + 1)
test dedupe_test = dedupe([1, 2, 1, 3, 2], [], 0) == [1, 2, 3]

fn even_q(q: List[Int]) -> List[Int] = filter(q, fn(x: Int) => x % 2 == 0)
