fn take_while_pos(q: List[Int], i: Int, acc: List[Int]) -> List[Int] =
  if i >= len(q) then acc
  else if list_at(q, i) > 0 then take_while_pos(q, i + 1, push(acc, list_at(q, i)))
  else acc
