fn drop_while_neg(q: List[Int], i: Int) -> List[Int] =
  if i >= len(q) then []
  else if list_at(q, i) < 0 then drop_while_neg(q, i + 1)
  else fold(range(i, len(q)), [], fn(a: List[Int], j: Int) => push(a, list_at(q, j)))
