fn pal_check(q: List[Int]) -> Bool =
  if len(q) < 2 then true
  else if list_at(q, 0) != list_at(q, len(q) - 1) then false
  else pal_check(take_mid(q))
fn take_mid(q: List[Int]) -> List[Int] =
  if len(q) < 2 then [] else fold(range(1, len(q) - 1), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
