fn is_suffix(q: List[Int], s: List[Int]) -> Bool =
  if len(s) > len(q) then false else take_tail(q, len(q) - len(s)) == s
fn take_tail(q: List[Int], n: Int) -> List[Int] =
  fold(range(n, len(q)), [], fn(a: List[Int], i: Int) => push(a, list_at(q, i)))
test suffix_test = is_suffix([1, 2, 3], [2, 3]) && !is_suffix([1, 2, 3], [1, 2])

fn b_df(xs: List[Str]) -> List[Str] = if len(xs) == 0 then [] else fold(range(1, len(xs)), [], fn(a: List[Str], i: Int) => push(a, list_at(xs, i)))
fn b_step(xs: List[Str], c: Str) -> Option[List[Str]] =
  if c == "(" then Some(push(xs, c))
  else if c == ")" then (if len(xs) == 0 then None else Some(b_df(xs)))
  else Some(xs)
fn b_fold(a: Option[List[Str]], c: Str) -> Option[List[Str]] = match a { Some(s) => b_step(s, c), None => None }
fn balanced(s: Str) -> Bool =
  let r = fold(chars(s), Some([]), fn(a: Option[List[Str]], c: Str) => b_fold(a, c)) in
  match r { Some(st) => len(st) == 0, None => false }
test balanced_test = balanced("(())") && !balanced("(()")

