fn sq_step(xs: List[Str], c: Str) -> Option[List[Str]] =
  if c == "[" then Some(push(xs, c))
  else if c == "]" then (if len(xs) == 0 then None else Some(sq_df(xs)))
  else Some(xs)
fn sq_run(xs: Option[List[Str]], c: Str) -> Option[List[Str]] = match xs { Some(s) => sq_step(s, c), None => None }
fn sq_ok(s: Str) -> Bool =
  let r = fold(chars(s), Some([]), fn(a: Option[List[Str]], c: Str) => sq_run(a, c)) in
