fn expand(a: List[List[Int]], fr: List[Int], vis: List[Int], i: Int, acc: List[Int]) -> List[Int] =
  if i >= len(fr) then acc
  else match get(fr, i) { None => acc, Some(v) => expand(a, fr, vis, i + 1, acc ++ filter(nb(a, v), fn(u) => !has(vis, u))) }
fn hops(a: List[List[Int]], fr: List[Int], vis: List[Int], goal: Int, d: Int) -> Int =
  if has(fr, goal) then d
  else if len(fr) == 0 then -1
  else next_hop(a, fr, vis, goal, d, expand(a, fr, vis, 0, []))
fn next_hop(a: List[List[Int]], fr: List[Int], vis: List[Int], goal: Int, d: Int, nx: List[Int]) -> Int =
  if len(nx) == 0 then -1 else hops(a, nx, vis ++ fr, goal, d + 1)
