type Row = Solo(Int) | Duo(Int, Int) | Blank
fn row_list(r: Row) -> List[Int] = match r { Solo(a) => [a], Duo(a, b) => [a, b], Blank => [] }
fn heap(rs: List[Row], i: Int, acc: List[List[Int]]) -> List[List[Int]] =
  if i >= len(rs) then acc
  else match get(rs, i) { None => acc, Some(r) => heap(rs, i + 1, push(acc, row_list(r))) }
fn nb(r: List[Row], v: Int) -> List[Int] = match get(heap(r, 0, []), v) { None => [], Some(xs) => xs }
fn has(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn walk(a: List[Row], v: Int, vis: List[Int]) -> List[Int] =
  if has(vis, v) then vis else fan(a, nb(a, v), 0, push(vis, v))
fn fan(a: List[Row], row: List[Int], i: Int, vis: List[Int]) -> List[Int] =
  if i >= len(row) then vis else match get(row, i) { None => vis, Some(u) => fan(a, row, i + 1, walk(a, u, vis)) }
test row_graph = len(walk([Solo(1), Duo(2, 3), Blank], 0, [])) == 4

