fn span(m: Map[Str, List[Str]], q: List[Str], i: Int, vis: List[Str]) -> List[Str] =
  if i >= len(q) then vis
  else match get(q, i) { None => vis, Some(v) => if has(vis, v) then span(m, q, i + 1, vis) else span(m, q ++ filter(out(m, v), fn(u) => !has(push(vis, v), u)), i + 1, push(vis, v)) }
