fn grow(a: List[List[Int]], fr: List[Int], vis: List[Int], i: Int, acc: List[Int]) -> List[Int] =
  if i >= len(fr) then acc
  else match get(fr, i) { None => acc, Some(v) => grow(a, fr, vis, i + 1, acc ++ filter(links(a, v), fn(u) => !has(vis, u))) }
fn ring(a: List[List[Int]], fr: List[Int], vis: List[Int], k: Int) -> List[Int] =
  if k <= 0 then vis ++ fr else ring(a, grow(a, fr, vis, 0, []), vis ++ fr, k - 1)
