type Edge = { u: Int, v: Int }
fn tails(es: List[Edge], u: Int) -> List[Int] = map(filter(es, fn(e) => e.u == u), fn(e) => e.v)
fn has(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn spread(es: List[Edge], v: Int, vis: List[Int]) -> List[Int] =
  if has(vis, v) then vis else fan(es, tails(es, v), 0, push(vis, v))
fn fan(es: List[Edge], row: List[Int], i: Int, vis: List[Int]) -> List[Int] =
  if i >= len(row) then vis else match get(row, i) { None => vis, Some(u) => fan(es, row, i + 1, spread(es, u, vis)) }
test fan_edges = len(spread([Edge { u: 0, v: 1 }, Edge { u: 0, v: 2 }, Edge { u: 2, v: 3 }], 0, [])) == 4

type Graph = { adj: List[List[Int]] }
fn links(g: Graph, v: Int) -> List[Int] = match get(g.adj, v) { Some(r) => r, None => [] }
fn known(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn crawl(g: Graph, q: List[Int], i: Int, vis: List[Int]) -> List[Int] =
  if i >= len(q) then vis
  else match get(q, i) { None => vis, Some(v) => if known(vis, v) then crawl(g, q, i + 1, vis) else crawl(g, q ++ filter(links(g, v), fn(u) => !known(push(vis, v), u)), i + 1, push(vis, v)) }
fn probe(g: Graph, s: Int) -> Int = len(crawl(g, [s], 0, []))
test wrapped = probe(Graph { adj: [[1, 2], [0, 3], [0], [1]] }, 0) == 4

