fn cell(m: List[List[Int]], r: Int, c: Int) -> Int = match get(m, r) { None => 0, Some(row) => match get(row, c) { None => 0, Some(x) => x } }
fn same_row(m: List[List[Int]], r: Int, c: Int) -> Bool =
  if c >= len(m) then true else cell(m, r, c) == cell(m, c, r) && same_row(m, r, c + 1)
fn is_undirected(m: List[List[Int]], r: Int) -> Bool =
  if r >= len(m) then true else same_row(m, r, 0) && is_undirected(m, r + 1)
test matrix_und = is_undirected([[0, 1, 1], [1, 0, 0], [1, 0, 0]], 0) && !is_undirected([[0, 1], [0, 0]], 0)

fn cell(m: List[List[Int]], r: Int, c: Int) -> Int = match get(m, r) { None => 0, Some(row) => match get(row, c) { None => 0, Some(x) => x } }
fn row_empty(m: List[List[Int]], r: Int, c: Int) -> Bool =
  if c >= len(m) then true else if cell(m, r, c) == 1 then false else row_empty(m, r, c + 1)
fn solo_rows(m: List[List[Int]], r: Int, acc: Int) -> Int =
