fn dive(a: List[List[Int]], v: Int, vis: List[Int]) -> List[Int] = if holds(vis, v) then vis else fan(a, adj_of(a, v), 0, push(vis, v))
fn fan(a: List[List[Int]], row: List[Int], i: Int, vis: List[Int]) -> List[Int] = if i >= len(row) then vis else match get(row, i) { None => vis, Some(u) => fan(a, row, i + 1, dive(a, u, vis)) }
fn smallest(a: List[List[Int]], i: Int, vis: List[Int], best: Int) -> Int =
  if i >= len(a) then best
  else if holds(vis, i) then smallest(a, i + 1, vis, best)
  else small_one(a, i, vis, best, dive(a, i, vis))
fn small_one(a: List[List[Int]], i: Int, vis: List[Int], best: Int, g: List[Int]) -> Int =
  if len(g) - len(vis) < best then smallest(a, i + 1, g, len(g) - len(vis)) else smallest(a, i + 1, g, best)
fn min_part(a: List[List[Int]]) -> Int = smallest(a, 0, [], 999)
test smallest_part = min_part([[1], [0], [2], [3]]) == 1

