fn cell(m: List[List[Int]], r: Int, c: Int) -> Int = match get(m, r) { None => 0, Some(row) => match get(row, c) { None => 0, Some(x) => x } }
fn mutual(m: List[List[Int]], r: Int, c: Int, acc: Int) -> Int =
  if r >= len(m) then acc
  else if c >= len(m) then mutual(m, r + 1, r + 2, acc)
  else mutual(m, r, c + 1, if cell(m, r, c) == 1 && cell(m, c, r) == 1 then acc + 1 else acc)
