fn add_nodes(es: List[Edge], vis: List[Int], i: Int) -> List[Int] =
  if i >= len(es) then vis
  else match get(es, i) { None => vis, Some(e) => add_nodes(es, add_one(add_one(vis, e.u), e.v), i + 1) }
