  else match get(q, i) { None => vis, Some(v) => if holds(vis, v) then roam(m, q, i + 1, vis) else roam(m, q ++ filter(out(m, v), fn(u) => !holds(push(vis, v), u)), i + 1, push(vis, v)) }
