type Span = { lo: Int, hi: Int }
fn ordered(s: Span) -> Span = if s.lo <= s.hi then s else Span { lo: s.hi, hi: s.lo }
test order_swap = ordered(Span { lo: 8, hi: 2 }) == Span { lo: 2, hi: 8 }
test order_keep = ordered(Span { lo: 1, hi: 4 }) == Span { lo: 1, hi: 4 }

type Span = { lo: Int, hi: Int }
fn meet(p: Span, q: Span) -> Option[Span] =
  let lo = if p.lo > q.lo then p.lo else q.lo in
  let hi = if p.hi < q.hi then p.hi else q.hi in
  if lo < hi then Some(Span { lo: lo, hi: hi }) else None
fn no_meet(p: Span, q: Span) -> Bool = match meet(p, q) { Some(_) => false, None => true }
test meet_mid = meet(Span { lo: 1, hi: 6 }, Span { lo: 4, hi: 9 }) == Some(Span { lo: 4, hi: 6 })
test meet_touch = no_meet(Span { lo: 1, hi: 4 }, Span { lo: 4, hi: 8 })

type Span = { lo: Int, hi: Int }
fn hull(p: Span, q: Span) -> Span =
  let lo = if p.lo < q.lo then p.lo else q.lo in
  let hi = if p.hi > q.hi then p.hi else q.hi in
  Span { lo: lo, hi: hi }
test hull_far = hull(Span { lo: 2, hi: 5 }, Span { lo: 7, hi: 9 }) == Span { lo: 2, hi: 9 }
test hull_in = hull(Span { lo: 2, hi: 9 }, Span { lo: 3, hi: 5 }) == Span { lo: 2, hi: 9 }

type Span = { lo: Int, hi: Int }
fn hits(rs: List[Span], x: Int) -> Int =
  fold(rs, 0, fn(n: Int, s: Span) => if x >= s.lo && x < s.hi then n + 1 else n)
test hit_two = hits([Span { lo: 0, hi: 3 }, Span { lo: 2, hi: 6 }], 2) == 2
test hit_none = hits([Span { lo: 0, hi: 2 }], 7) == 0

