type Span = { lo: Int, hi: Int }
fn safe_cut(a: Span, b: Span) -> Option[Span] =
  let lo = if a.lo > b.lo then a.lo else b.lo in
  let hi = if a.hi < b.hi then a.hi else b.hi in
  if hi - lo > 0 then Some(Span { lo: lo, hi: hi }) else None
