type MinHeap = Empty | Root(Int, MinHeap, MinHeap)
fn min_ok(h: MinHeap) -> Bool = match h { Empty => true, Root(x, l, r) => smaller(x, l) && smaller(x, r) && min_ok(l) && min_ok(r) }
fn smaller(x: Int, h: MinHeap) -> Bool = match h { Empty => true, Root(y, _, _) => x <= y }
test min_heap_valid = min_ok(Root(1, Root(2, Empty, Empty), Root(3, Empty, Empty)))
test min_heap_invalid = !min_ok(Root(4, Root(2, Empty, Empty), Empty))

type MaxHeap = Empty | Node(Int, MaxHeap, MaxHeap)
fn max_ok(h: MaxHeap) -> Bool = match h { Empty => true, Node(x, l, r) => larger(x, l) && larger(x, r) && max_ok(l) && max_ok(r) }
fn larger(x: Int, h: MaxHeap) -> Bool = match h { Empty => true, Node(y, _, _) => x >= y }
