type CountTree = Empty | Count(Int, CountTree)
fn inv_CountTree(c: CountTree) -> Bool = match c { Empty => true, Count(n, rest) => n > 0 && inv_CountTree(rest) }
fn count_total(c: CountTree) -> Int = match c { Empty => 0, Count(n, rest) => n + count_total(rest) }
