type BalancedTree = Tip | Fork(BalancedTree, BalancedTree)
fn bt_height(t: BalancedTree) -> Int = match t { Tip => 0, Fork(l, r) => 1 + (if bt_height(l) > bt_height(r) then bt_height(l) else bt_height(r)) }
fn gap(a: Int, b: Int) -> Int = if a > b then a - b else b - a
fn balanced(t: BalancedTree) -> Bool = match t { Tip => true, Fork(l, r) => gap(bt_height(l), bt_height(r)) <= 1 && balanced(l) && balanced(r) }
