fn p040_best(ps: List[Int], n: Int, k: Int) -> Int = if k > n then 0 else let take = p040_at(ps, k - 1) + p040_rod(ps, n - k) in let skip = p040_best(ps, n, k + 1) in if take > skip then take else skip
