fn zip_sum(a: List[Int], b: List[Int]) -> List[Int] = map(range(0, len(a)), fn(i) => list_at(a, i) + list_at(b, i))
test zip_ok = zip_sum([1, 2], [10, 20]) == [11, 22]
test zip_sum_empty = zip_sum([], []) == []

type PairI = { fst: Int, snd: Int }
fn pair_sums(ps: List[PairI]) -> List[Int] = map(ps, fn(p) => p.fst + p.snd)
test pair_sums_ok = pair_sums([PairI { fst: 1, snd: 2 }, PairI { fst: 10, snd: 5 }]) == [3, 15]

fn triple_len(xs: List[Str]) -> Int = len(filter(xs, fn(s) => len(s) == 3))
test triple_ok = triple_len(["abc", "de", "ghi"]) == 2
test triple_none = triple_len(["a", "bb"]) == 0

fn merge_lists(a: List[Int], b: List[Int]) -> List[Int] = concat(a, b)
test merge_ok = merge_lists([1], [2, 3]) == [1, 2, 3]
test merge_empty = merge_lists([], []) == []

fn sort_ints(xs: List[Int]) -> List[Int] = sort_int(xs)
test sort_ok = sort_ints([3, 1, 2]) == [1, 2, 3]
test sort_empty = sort_ints([]) == []

fn sum_evens(xs: List[Int]) -> Int = fold(filter(xs, fn(x) => x % 2 == 0), 0, fn(acc, x) => acc + x)
test sum_evens_ok = sum_evens([1, 2, 3, 4]) == 6
test sum_evens_empty = sum_evens([]) == 0

fn range_sum(n: Int) -> Int = fold(range(0, n), 0, fn(acc, x) => acc + x)
test range_sum_five = range_sum(5) == 10
test range_sum_zero = range_sum(0) == 0

fn min_list(xs: List[Int]) -> Int = min_at(xs, 1, list_at(xs, 0))
fn min_at(xs: List[Int], i: Int, best: Int) -> Int = if i >= len(xs) then best else let cand = list_at(xs, i) in let nb = if cand < best then cand else best in min_at(xs, i + 1, nb)
test min_ok = min_list([4, -1, 9]) == -1

fn count_char(s: Str, c: Str) -> Int = len(filter(chars(s), fn(ch) => ch == c))
test count_a = count_char("banana", "a") == 3
test count_no = count_char("banana", "z") == 0

fn is_vowel(ch: Str) -> Bool = contains("aeiou", ch)
fn vowel_count(s: Str) -> Int = len(filter(chars(s), fn(ch) => is_vowel(ch)))
test vowel_ok = vowel_count("hello") == 2

fn initials(words: List[Str]) -> Str = join(map(words, fn(w) => if len(w) == 0 then "" else slice(w, 0, 1)), "")
test initials_ok = initials(["Ada", "Grace", "Alan"]) == "AGA"
test initials_empty = initials([]) == ""

fn dash_join(s: Str) -> Str = join(split(trim(s), " "), "-")
test dash_ok = dash_join("  a b  ") == "a-b"
test dash_single = dash_join("x") == "x"

fn spaces_to_underscores(s: Str) -> Str = replace(s, " ", "_")
test under_ok = spaces_to_underscores("a b c") == "a_b_c"
test under_empty = spaces_to_underscores("") == ""

fn httpish(url: Str) -> Bool = starts_with(url, "http")
test http_yes = httpish("https://x")
test http_no = !httpish("ftp://x")

fn bump(s: Str) -> Option[Int] = match to_int(s) { Some(n) => Some(n + 1), None => None }
test bump_ok = bump("41") == Some(42)
test bump_bad = bump("x") == None

fn digit_check(s: Str) -> Bool = len(s) == 1 && contains("0123456789", s)
test digit_yes = digit_check("7")
test digit_no = !digit_check("x")

fn shift_char(s: Str) -> Str = if len(s) == 0 then "" else from_char_code(char_code(s) + 1)
test shift_ok = shift_char("a") == "b"
test shift_empty = shift_char("") == ""

fn csv(xs: List[Str]) -> Str = join(xs, ",")
test csv_ok = csv(["a", "b"]) == "a,b"
test csv_empty = csv([]) == ""

fn first_word(s: Str) -> Str = let parts = split(trim(s), " ") in if len(parts) == 0 then "" else list_at(parts, 0)
test first_word_ok = first_word("alpha beta") == "alpha"
test first_word_empty = first_word("") == ""

fn cap_first(s: Str) -> Str = if len(s) == 0 then s else to_upper(slice(s, 0, 1)) ++ slice(s, 1, len(s))
test cap_ok = cap_first("qal") == "Qal"
test cap_empty = cap_first("") == ""

fn repeat_str(s: Str, n: Int) -> Str = if n <= 0 then "" else s ++ repeat_str(s, n - 1)
test repeat_ok = repeat_str("ab", 3) == "ababab"
test repeat_zero = repeat_str("x", 0) == ""

fn word_count(s: Str) -> Int = len(filter(split(trim(s), " "), fn(w) => len(w) > 0))
test wc_ok = word_count("a bb ccc") == 3
test wc_empty = word_count("") == 0

fn parse_or_zero(s: Str) -> Int = match to_int(s) { Some(n) => n, None => 0 }
test parse_ok = parse_or_zero("12") == 12
test parse_bad = parse_or_zero("no") == 0

fn rev_str(s: Str) -> Str = rev_chars(chars(s), len(s) - 1)
fn rev_chars(cs: List[Str], i: Int) -> Str = if i < 0 then "" else list_at(cs, i) ++ rev_chars(cs, i - 1)
test rev_str_ok = rev_str("abc") == "cba"

fn rev_word(s: Str) -> Str = rev_chars2(chars(s), len(s) - 1)
fn rev_chars2(cs: List[Str], i: Int) -> Str = if i < 0 then "" else list_at(cs, i) ++ rev_chars2(cs, i - 1)
fn is_palindrome(s: Str) -> Bool = s == rev_word(s)
test pal_yes = is_palindrome("level")
test pal_no = !is_palindrome("levels")

fn word_lens(s: Str) -> List[Int] = map(split(s, " "), fn(w) => len(w))
test word_lens_ok = word_lens("a bb") == [1, 2]
test word_lens_single = word_lens("abc") == [3]

fn parse_or_zero2(s: Str) -> Int = match to_int(s) { Some(n) => n, None => 0 }
fn sum_strs(xs: List[Str]) -> Int = fold(xs, 0, fn(acc, s) => acc + parse_or_zero2(s))
test sum_strs_ok = sum_strs(["1", "x", "2"]) == 3

fn letters_count(s: Str) -> Int = len(chars(s))
test letters_ok = letters_count("abc") == 3
test letters_empty = letters_count("") == 0

fn letter_a() -> Str = from_char_code(97)
test letter_a_ok = letter_a() == "a"
test letter_a_len = len(letter_a()) == 1

fn locate_sub(s: Str, sub: Str) -> Option[Int] = index_of(s, sub)
test locate_ok = locate_sub("banana", "nan") == Some(2)
test locate_none = locate_sub("banana", "zz") == None

fn trunc_val(x: Float) -> Option[Int] = float_to_int(x)
test trunc_ok = trunc_val(3.0) == Some(3)
test trunc_five = trunc_val(5.0) == Some(5)

type Point = { x: Int, y: Int }
fn diff(a: Int, b: Int) -> Int = if a > b then a - b else b - a
fn manhattan(p: Point, q: Point) -> Int = diff(p.x, q.x) + diff(p.y, q.y)
test manh_ok = manhattan(Point { x: 0, y: 0 }, Point { x: 3, y: -4 }) == 7

type Rect = { w: Int, h: Int }
fn rect_area(box: Rect) -> Int = box.w * box.h
fn rect_perim(box: Rect) -> Int = 2 * (box.w + box.h)
test rect_area_ok = rect_area(Rect { w: 3, h: 4 }) == 12
test rect_perim_ok = rect_perim(Rect { w: 3, h: 4 }) == 14

type Person = { name: Str, age: Int }
fn describe(p: Person) -> Str = p.name ++ " is " ++ from_int(p.age)
test describe_ok = describe(Person { name: "Ada", age: 36 }) == "Ada is 36"

type Point2 = { x: Int, y: Int }
type Line = { a: Point2, b: Point2 }
fn line_len_sq(l: Line) -> Int = let dx = l.b.x - l.a.x in let dy = l.b.y - l.a.y in dx * dx + dy * dy
test line_ok = line_len_sq(Line { a: Point2 { x: 0, y: 0 }, b: Point2 { x: 3, y: 4 } }) == 25

type Account = { owner: Str, balance: Int }
fn deposit(acc: Account, amt: Int) -> Account = Account { owner: acc.owner, balance: acc.balance + amt }
test deposit_ok = let acc2 = deposit(Account { owner: "sam", balance: 10 }, 5) in acc2.balance == 15

type Pair[A, B] = { fst: A, snd: B }
fn flip[A, B](p: Pair[A, B]) -> Pair[B, A] = Pair { fst: p.snd, snd: p.fst }
test flip_ok = let q = flip(Pair { fst: 1, snd: "a" }) in q.fst == "a"

type Money = { cents: Int, currency: Str }
fn add_money(a: Money, b: Money) -> Money = Money { cents: a.cents + b.cents, currency: a.currency }
test money_ok = let m = add_money(Money { cents: 150, currency: "EUR" }, Money { cents: 50, currency: "EUR" }) in m.cents == 200

type Temp = { deg: Int, fahrenheit: Bool }
fn to_c(t: Temp) -> Int = if t.fahrenheit then (t.deg - 32) * 5 / 9 else t.deg
test temp_ok = to_c(Temp { deg: 212, fahrenheit: true }) == 100

type Item = { price: Int, qty: Int }
fn cart_total(items: List[Item]) -> Int = fold(items, 0, fn(acc, it) => acc + it.price * it.qty)
test cart_ok = cart_total([Item { price: 3, qty: 2 }, Item { price: 5, qty: 1 }]) == 11

type Score = { points: Int, bonus: Int }
fn grade(s: Score) -> Str = match s { Score { points: p, bonus: b } if p + b >= 90 => "A", Score { points: p, bonus: b } if p + b >= 80 => "B", Score { points: p, bonus: b } => "C" }
test grade_a = grade(Score { points: 90, bonus: 5 }) == "A"
test grade_c = grade(Score { points: 10, bonus: 5 }) == "C"

type Emp = { name: Str, salary: Int }
fn rich(es: List[Emp]) -> List[Str] = map(filter(es, fn(e) => e.salary >= 100), fn(e) => e.name)
test rich_ok = rich([Emp { name: "a", salary: 50 }, Emp { name: "b", salary: 150 }]) == ["b"]

type Emp2 = { name: Str, salary: Int }
fn payroll(es: List[Emp2]) -> Int = fold(es, 0, fn(acc, e) => acc + e.salary)
test payroll_ok = payroll([Emp2 { name: "a", salary: 100 }, Emp2 { name: "b", salary: 250 }]) == 350

type Dir = North | East | South | West
fn turn_right(d: Dir) -> Dir = match d { North => East, East => South, South => West, West => North }
test turn_ok = turn_right(North) == East

type Point3 = { x: Int, y: Int }
fn bbox_sum(xs: List[Point3]) -> Int = fold(xs, 0, fn(acc, p) => acc + p.x + p.y)
test bbox_ok = bbox_sum([Point3 { x: 1, y: 2 }, Point3 { x: 3, y: 4 }]) == 10

type Rect2 = { w: Int, h: Int }
fn scale_rect(box: Rect2, k: Int) -> Rect2 = Rect2 { w: box.w * k, h: box.h * k }
test scale_ok = let b = scale_rect(Rect2 { w: 2, h: 3 }, 4) in b.w == 8 && b.h == 12

fn inc_word(m: Map[Str, Int], w: Str) -> Map[Str, Int] = map_put(m, w, match map_get(m, w) { Some(n) => n + 1, None => 1 })
fn count_words(words: List[Str]) -> Map[Str, Int] = fold(words, map_new(), fn(m, w) => inc_word(m, w))
test count_words_ok = map_get(count_words(["a", "b", "a"]), "a") == Some(2)

fn build_map() -> Map[Int, Str] = map_put(map_put(map_new(), 1, "one"), 2, "two")
test map_size_ok = map_size(build_map()) == 2
test map_get_ok = map_get(build_map(), 1) == Some("one")

fn demo_map() -> Map[Int, Int] = map_put(map_new(), 5, 50)
test map_has_ok = map_has(demo_map(), 5)
test map_del_ok = map_size(map_del(demo_map(), 5)) == 0

fn sample_map() -> Map[Int, Int] = map_put(map_put(map_new(), 2, 20), 1, 10)
test keys_ok = map_keys(sample_map()) == [1, 2]
test values_ok = map_values(sample_map()) == [10, 20]

fn bump_score(m: Map[Str, Int], k: Str) -> Map[Str, Int] = map_put(m, k, match map_get(m, k) { Some(v) => v + 10, None => 10 })
test bump_new = map_get(bump_score(map_new(), "x"), "x") == Some(10)
test bump_old = map_get(bump_score(map_put(map_new(), "y", 5), "y"), "y") == Some(15)

fn lookup_default(m: Map[Str, Int], k: Str) -> Int = match map_get(m, k) { Some(v) => v, None => -1 }
test lookup_ok = lookup_default(map_put(map_new(), "a", 1), "a") == 1
test lookup_none = lookup_default(map_new(), "z") == -1

fn map_size_three() -> Int = map_size(map_put(map_put(map_put(map_new(), 1, "a"), 2, "b"), 3, "c"))
test map_three_ok = map_size_three() == 3
test map_three_key = map_has(map_put(map_put(map_put(map_new(), 1, "a"), 2, "b"), 3, "c"), 1)

fn overwrite(m: Map[Str, Int], k: Str, v: Int) -> Map[Str, Int] = map_put(m, k, v)
test overwrite_ok = map_get(overwrite(map_put(map_new(), "k", 1), "k", 9), "k") == Some(9)
test overwrite_new = map_get(overwrite(map_new(), "n", 4), "n") == Some(4)

fn values_sum(m: Map[Int, Int]) -> Int = fold(map_values(m), 0, fn(acc, v) => acc + v)
test values_sum_ok = values_sum(map_put(map_put(map_new(), 1, 10), 2, 20)) == 30
test values_sum_empty = values_sum(map_new()) == 0

fn keys_joined(m: Map[Int, Str]) -> Str = join(map(map_keys(m), fn(k) => from_int(k)), "-")
test keys_joined_ok = keys_joined(map_put(map_put(map_new(), 1, "a"), 2, "b")) == "1-2"
test keys_joined_one = keys_joined(map_put(map_new(), 7, "z")) == "7"

fn safe_div(a: Int, b: Int) -> Option[Int] = if b == 0 then None else Some(a / b)
test div_ok = safe_div(10, 2) == Some(5)
test div_zero = safe_div(1, 0) == None

fn parse_positive(s: Str) -> Result[Int, Str] = match to_int(s) { Some(n) => if n > 0 then Ok(n) else Err("not positive"), None => Err("not a number") }
test parse_pp = parse_positive("3") == Ok(3)
test parse_pn = parse_positive("-1") == Err("not positive")

fn double_opt(x: Option[Int]) -> Option[Int] = match x { Some(n) => Some(n * 2), None => None }
test dbl_some = double_opt(Some(4)) == Some(8)
test dbl_none = double_opt(None) == None

fn add_one_result(r: Result[Int, Str]) -> Result[Int, Str] = match r { Ok(n) => Ok(n + 1), Err(e) => Err(e) }
test add_one_ok = add_one_result(Ok(41)) == Ok(42)
test add_one_err = add_one_result(Err("bad")) == Err("bad")

fn first_pos(xs: List[Int]) -> Option[Int] = first_from(xs, 0)
fn first_from(xs: List[Int], i: Int) -> Option[Int] = if i >= len(xs) then None else if list_at(xs, i) > 0 then Some(list_at(xs, i)) else first_from(xs, i + 1)
test first_pos_ok = first_pos([-2, 0, 3, 4]) == Some(3)
test first_pos_none = first_pos([-2]) == None

fn or_else(x: Option[Int], d: Int) -> Int = match x { Some(n) => n, None => d }
test or_else_some = or_else(Some(5), 9) == 5
test or_else_none = or_else(None, 9) == 9

fn to_opt(r: Result[Int, Str]) -> Option[Int] = match r { Ok(n) => Some(n), Err(_) => None }
test to_opt_err = to_opt(Err("x")) == None
test to_opt_ok = to_opt(Ok(2)) == Some(2)

fn both_ok(a: Result[Int, Str], b: Result[Int, Str]) -> Result[Int, Str] = match a { Err(e) => Err(e), Ok(x) => match b { Err(e2) => Err(e2), Ok(y) => Ok(x + y) } }
test both_ok_ok = both_ok(Ok(1), Ok(2)) == Ok(3)
test both_err = both_ok(Err("a"), Ok(2)) == Err("a")

fn sum_options(a: Option[Int], b: Option[Int]) -> Option[Int] = match a { None => None, Some(x) => match b { None => None, Some(y) => Some(x + y) } }
test sum_opts = sum_options(Some(2), Some(3)) == Some(5)
test sum_opts_none = sum_options(Some(2), None) == None

fn require_positive(n: Int) -> Result[Int, Str] = if n > 0 then Ok(n) else Err("nope")
test req_pos = require_positive(5) == Ok(5)
test req_neg = require_positive(-5) == Err("nope")

fn compose_fns(f: fn(Int) -> Int, g: fn(Int) -> Int) -> fn(Int) -> Int = fn(x: Int) => f(g(x))
test compose_ok = let h = compose_fns(fn(x) => x + 1, fn(x) => x * 2) in h(5) == 11
test compose_id = let h2 = compose_fns(fn(x: Int) => x, fn(x: Int) => x + 1) in h2(3) == 4

fn apply_twice(f: fn(Int) -> Int, x: Int) -> Int = f(f(x))
test twice_ok = apply_twice(fn(x) => x + 3, 1) == 7
test twice_zero = apply_twice(fn(x) => x * 2, 0) == 0

fn scale_list(xs: List[Int], k: Int) -> List[Int] = map(xs, fn(x) => x * k)
test scale_ok = scale_list([1, 2, 3], 3) == [3, 6, 9]
test scale_empty = scale_list([], 5) == []

fn above(xs: List[Int], t: Int) -> List[Int] = filter(xs, fn(x) => x > t)
test above_ok = above([1, 5, 9], 4) == [5, 9]
test above_none = above([1, 2], 9) == []

fn join_nums(xs: List[Int]) -> Str = fold(xs, "", fn(acc, x) => acc ++ from_int(x))
test join_nums_ok = join_nums([1, 2, 3]) == "123"
test join_nums_empty = join_nums([]) == ""

fn apply[A, B](f: fn(A) -> B, x: A) -> B = f(x)
test apply_ok = apply(fn(n: Int) => n + 1, 41) == 42
test apply_str = apply(fn(s: Str) => s ++ "!", "hi") == "hi!"

fn pipe(x: Int) -> Int = let f = fn(n) => n * 2 in let g = fn(n) => n + 1 in g(f(x))
test pipe_ok = pipe(4) == 9
test pipe_zero = pipe(0) == 1

fn fold_max(xs: List[Int]) -> Int = fold(xs, 0, fn(acc, x) => if x > acc then x else acc)
test fold_max_ok = fold_max([3, 8, 2]) == 8
test fold_max_one = fold_max([6]) == 6

fn evens_only(xs: List[Int]) -> List[Int] = filter(xs, fn(x) => x % 2 == 0)
test evens_ok = evens_only([1, 2, 4, 5]) == [2, 4]
test evens_none = evens_only([1, 3]) == []

fn unwrap_or[A](x: Option[A], d: A) -> A = match x { Some(v) => v, None => d }
test unwrap_ok = unwrap_or(Some("x"), "y") == "x"
test unwrap_none = unwrap_or(None, "y") == "y"

fn size_of[A](xs: List[A]) -> Int = len(xs)
test size_ok = size_of([1, 2, 3]) == 3
test size_one = size_of([9]) == 1

type Pair3[A, B] = { fst: A, snd: B }
fn map_fst[A, B, C](p: Pair3[A, B], f: fn(A) -> C) -> Pair3[C, B] = Pair3 { fst: f(p.fst), snd: p.snd }
test map_fst_ok = let q = map_fst(Pair3 { fst: 2, snd: "b" }, fn(n: Int) => n * 10) in q.fst == 20

type TTree[T] = Tip | Branch(TTree[T], T, TTree[T])
fn tree_size[T](t: TTree[T]) -> Int = match t { Tip => 0, Branch(l, _, rt) => 1 + tree_size(l) + tree_size(rt) }
test tree_size_ok = tree_size(Branch(Tip, 1, Tip)) == 1

type Duo[A, B] = { left: A, right: B }
fn swap_duo[A, B](d: Duo[A, B]) -> Duo[B, A] = Duo { left: d.right, right: d.left }
test swap_duo_ok = let d = swap_duo(Duo { left: 1, right: true }) in d.left == true

type Tree2 = Leaf2 | Node2(Tree2, Tree2)
fn tree_depth(t: Tree2) -> Int = match t { Leaf2 => 0, Node2(l, rt) => let a = tree_depth(l) in let b = tree_depth(rt) in 1 + (if a > b then a else b) }
test depth_ok = tree_depth(Node2(Leaf2, Leaf2)) == 1

type PInt = { a: Int, b: Int }
fn sum_pair_list(ps: List[PInt]) -> Int = fold(ps, 0, fn(acc, p) => acc + p.a + p.b)
test sum_pair_list_ok = sum_pair_list([PInt { a: 1, b: 2 }, PInt { a: 3, b: 4 }]) == 10

fn concat_all(xss: List[List[Int]]) -> List[Int] = fold(xss, [], fn(acc, xs) => concat(acc, xs))
test concat_all_ok = concat_all([[1, 2], [3]]) == [1, 2, 3]
test concat_all_empty = concat_all([]) == []

fn byte_len(s: Str) -> Int = bytes_len(to_bytes(s))
test byte_len_ok = byte_len("abc") == 3
test byte_empty = byte_len("") == 0

fn first_byte(s: Str) -> Option[Int] = bytes_get(to_bytes(s), 0)
test first_byte_ok = first_byte("A") == Some(65)
test first_byte_none = first_byte("") == None

fn codes(s: Str) -> List[Int] = bytes_to_list(to_bytes(s))
test codes_ok = codes("AB") == [65, 66]
test codes_empty = codes("") == []

fn from_codes(xs: List[Int]) -> Option[Str] = bytes_to_str(bytes_from(xs))
test from_codes_ok = from_codes([104, 105]) == Some("hi")
test from_codes_z = from_codes([122]) == Some("z")

fn byte_sum(s: Str) -> Int = fold(bytes_to_list(to_bytes(s)), 0, fn(acc, b) => acc + b)
test byte_sum_ok = byte_sum("AB") == 131
test byte_sum_empty = byte_sum("") == 0

fn head_bytes(s: Str) -> Bytes = bytes_slice(to_bytes(s), 0, 1)
test head_bytes_ok = bytes_len(head_bytes("xyz")) == 1
test head_one = bytes_len(head_bytes("a")) == 1

fn tail_bytes(s: Str) -> Bytes = bytes_slice(to_bytes(s), 1, bytes_len(to_bytes(s)))
test tail_bytes_ok = bytes_len(tail_bytes("xyz")) == 2
test tail_empty = bytes_len(tail_bytes("a")) == 0

fn char_code_val(s: Str) -> Int = char_code(s)
test char_code_ok = char_code_val("A") == 65
test char_code_b = char_code_val("B") == 66

fn bytes_from_zero() -> Bytes = bytes_from([0, 1, 2])
test bytes_zero_ok = bytes_len(bytes_from_zero()) == 3
test bytes_zero_get = bytes_get(bytes_from_zero(), 0) == Some(0)

fn acc_build(xs: List[Int]) -> Accum[Int] = fold(xs, AccEnd, fn(a, x) => AccPush(a, x))
test acc_ok = len(acc_list(acc_build([1, 2, 3]))) == 3
test acc_empty = len(acc_list(acc_build([]))) == 0

fn collatz(n: Int, steps: Int) -> Int = if n <= 1 then steps else if n % 2 == 0 then collatz(n / 2, steps + 1) else collatz(3 * n + 1, steps + 1)
test collatz_six = collatz(6, 0) == 8
test collatz_one = collatz(1, 0) == 0

fn bin_helper(n: Int) -> Str = if n == 0 then "" else bin_helper(n / 2) ++ from_int(n % 2)
fn to_bin(n: Int) -> Str = if n == 0 then "0" else bin_helper(n)
